// p8misc live-tour catalogue batch lt1 (meals .. finance). Row order: en, pl, ro, ur, pa, bn, ar, pt, es, fr, cy.
export const rows: Record<string, readonly string[]> = {
  "lt_meals_title": ["Meals", "Posiłki", "Mese", "کھانے", "ਭੋਜਨ", "খাবার", "الوجبات", "Refeições", "Comidas", "Repas", "Prydau bwyd"],
  "lt_meals_intro": ["This is where you build reusable menus, plan their dishes onto each listing's run-days, and set who sees what — families then add and pay for meals right in the booking basket, and every order and change lands back here.", "Tutaj tworzysz menu do wielokrotnego użytku, planujesz dania na poszczególne dni ofert i ustawiasz, kto co widzi — rodziny dodają posiłki i płacą za nie od razu w koszyku rezerwacji, a każde zamówienie i zmiana wracają tutaj.", "Aici creezi meniuri reutilizabile, planifici preparatele pe zilele fiecărei oferte și stabilești cine vede ce — familiile adaugă mesele și le plătesc chiar în coșul de rezervare, iar fiecare comandă și modificare ajunge înapoi aici.", "یہاں آپ دوبارہ استعمال ہونے والے مینو بناتے ہیں، ہر لسٹنگ کے دنوں میں کھانے طے کرتے ہیں، اور یہ بھی کہ کون کیا دیکھے — خاندان بکنگ باسکٹ میں ہی کھانے شامل کر کے ادائیگی کرتے ہیں، اور ہر آرڈر اور تبدیلی واپس یہیں پہنچ جاتی ہے۔", "ਇੱਥੇ ਤੁਸੀਂ ਵਾਰ-ਵਾਰ ਵਰਤੇ ਜਾਣ ਵਾਲੇ ਮੀਨੂ ਬਣਾਉਂਦੇ ਹੋ, ਹਰ ਲਿਸਟਿੰਗ ਦੇ ਦਿਨਾਂ ਲਈ ਪਕਵਾਨ ਤੈਅ ਕਰਦੇ ਹੋ, ਅਤੇ ਇਹ ਵੀ ਕਿ ਕੌਣ ਕੀ ਵੇਖੇ — ਪਰਿਵਾਰ ਬੁਕਿੰਗ ਟੋਕਰੀ ਵਿੱਚ ਹੀ ਭੋਜਨ ਜੋੜ ਕੇ ਭੁਗਤਾਨ ਕਰਦੇ ਹਨ, ਅਤੇ ਹਰ ਆਰਡਰ ਤੇ ਤਬਦੀਲੀ ਵਾਪਸ ਇੱਥੇ ਆ ਜਾਂਦੀ ਹੈ।", "এখানে আপনি পুনরায় ব্যবহারযোগ্য মেনু বানান, প্রতিটি লিস্টিংয়ের দিনে কোন খাবার থাকবে তা ঠিক করেন, আর কে কী দেখবে তাও ঠিক করেন — পরিবারগুলো বুকিং বাস্কেটেই খাবার যোগ করে দাম মেটায়, আর প্রতিটি অর্ডার ও পরিবর্তন এখানে ফিরে আসে।", "هنا تُنشئ قوائم طعام قابلة لإعادة الاستخدام، وتوزّع أطباقها على أيام كل عرض، وتحدّد من يرى ماذا — فتضيف العائلات الوجبات وتدفع ثمنها مباشرة في سلة الحجز، ويصلك كل طلب وكل تغيير هنا.", "É aqui que cria menus reutilizáveis, planeia os pratos para os dias de cada oferta e define quem vê o quê — as famílias adicionam e pagam as refeições no próprio cesto de reserva, e cada pedido e alteração chega de volta aqui.", "Aquí creas menús reutilizables, planificas los platos en los días de cada oferta y decides quién ve qué: las familias añaden y pagan las comidas en la propia cesta de reserva, y cada pedido y cambio te llega de vuelta aquí.", "C'est ici que vous créez des menus réutilisables, planifiez les plats sur les jours de chaque offre et choisissez qui voit quoi : les familles ajoutent et paient les repas directement dans le panier de réservation, et chaque commande et chaque changement revient ici.", "Dyma lle rydych chi'n creu bwydlenni y gellir eu hailddefnyddio, cynllunio'r prydau ar gyfer diwrnodau pob rhestriad, a gosod pwy sy'n gweld beth — mae teuluoedd yn ychwanegu ac yn talu am brydau yn y fasged archebu ei hun, ac mae pob archeb a newid yn dod yn ôl yma."],
  "lt_meals_done": ["And that's Meals — build a menu once, drop it onto the days, and every order, swap and 'not yet chosen' nudge lands right back here for you.", "I to tyle w temacie Posiłków — menu tworzysz raz, przypisujesz do dni, a każde zamówienie, zamiana i przypomnienie „jeszcze nie wybrano” wracają do Ciebie tutaj.", "Și gata cu Mesele — creezi un meniu o singură dată, îl așezi pe zile, iar fiecare comandă, schimbare și memento „încă nealeasă” ajunge înapoi la tine aici.", "بس یہ تھا کھانوں کا حصہ — مینو ایک بار بنائیں، دنوں پر لگائیں، اور ہر آرڈر، تبدیلی اور «ابھی منتخب نہیں کیا» کی یاد دہانی آپ کے پاس یہیں واپس آ جاتی ہے۔", "ਬੱਸ ਇਹੀ ਹੈ ਭੋਜਨ ਦਾ ਹਿੱਸਾ — ਮੀਨੂ ਇੱਕ ਵਾਰ ਬਣਾਓ, ਦਿਨਾਂ ਉੱਤੇ ਲਗਾਓ, ਅਤੇ ਹਰ ਆਰਡਰ, ਬਦਲੀ ਅਤੇ «ਅਜੇ ਚੁਣਿਆ ਨਹੀਂ» ਦੀ ਯਾਦ-ਦਹਾਨੀ ਤੁਹਾਡੇ ਕੋਲ ਇੱਥੇ ਹੀ ਵਾਪਸ ਆ ਜਾਂਦੀ ਹੈ।", "খাবার অংশ এখানেই শেষ — একবার মেনু বানান, দিনগুলোতে বসিয়ে দিন, আর প্রতিটি অর্ডার, বদল এবং «এখনও বেছে নেওয়া হয়নি» অনুস্মারক আপনার কাছে এখানেই ফিরে আসে।", "وهكذا تنتهي جولة الوجبات — أنشئ قائمة طعام مرة واحدة، وضعها على الأيام، ويعود إليك هنا كل طلب وتبديل وتذكير «لم يُختَر بعد».", "E pronto, é isto nas Refeições — crie um menu uma só vez, coloque-o nos dias, e cada pedido, troca e lembrete de «ainda por escolher» chega de volta aqui.", "Y eso es todo en Comidas: creas un menú una vez, lo colocas en los días, y cada pedido, cambio y aviso de «aún sin elegir» te llega de vuelta aquí.", "Et voilà pour les Repas : créez un menu une fois, posez-le sur les jours, et chaque commande, échange et rappel « pas encore choisi » revient ici.", "A dyna ni gyda Prydau bwyd — crëwch fwydlen unwaith, rhowch hi ar y diwrnodau, ac mae pob archeb, newid a nodyn atgoffa «heb ddewis eto» yn dod yn ôl atoch chi yma."],
  "lt_meals_s0": ["Everything starts on this first tab. You choose a season, then the listing that slides out beside it, and the planner runs left to right across three tabs. Any listing that already has a meal plan is listed below to jump straight back into.", "Wszystko zaczyna się na tej pierwszej karcie. Wybierasz sezon, potem ofertę, która wysuwa się obok, a planer biegnie od lewej do prawej przez trzy karty. Każda oferta, która ma już plan posiłków, jest wymieniona poniżej, żeby od razu do niej wrócić.", "Totul începe în această primă filă. Alegi un sezon, apoi oferta care se deschide lângă el, iar planificatorul merge de la stânga la dreapta prin trei file. Orice ofertă care are deja un plan de mese apare mai jos, ca să revii direct la ea.", "سب کچھ اسی پہلے ٹیب سے شروع ہوتا ہے۔ آپ ایک سیزن چنتے ہیں، پھر اس کے ساتھ کھلنے والی لسٹنگ، اور پلانر تین ٹیبز میں بائیں سے دائیں چلتا ہے۔ جس لسٹنگ کا کھانوں کا پلان پہلے سے موجود ہو وہ نیچے درج ہے تاکہ آپ سیدھا اس میں جا سکیں۔", "ਸਭ ਕੁਝ ਇਸ ਪਹਿਲੇ ਟੈਬ ਤੋਂ ਸ਼ੁਰੂ ਹੁੰਦਾ ਹੈ। ਤੁਸੀਂ ਇੱਕ ਸੀਜ਼ਨ ਚੁਣਦੇ ਹੋ, ਫਿਰ ਉਸ ਦੇ ਕੋਲ ਖੁੱਲ੍ਹਣ ਵਾਲੀ ਲਿਸਟਿੰਗ, ਅਤੇ ਪਲੈਨਰ ਤਿੰਨ ਟੈਬਾਂ ਵਿੱਚ ਖੱਬਿਓਂ ਸੱਜੇ ਚੱਲਦਾ ਹੈ। ਜਿਸ ਲਿਸਟਿੰਗ ਦਾ ਭੋਜਨ ਪਲਾਨ ਪਹਿਲਾਂ ਹੀ ਹੈ, ਉਹ ਹੇਠਾਂ ਦਿੱਤੀ ਹੈ ਤਾਂ ਜੋ ਸਿੱਧਾ ਉਸ ਵਿੱਚ ਜਾ ਸਕੋ।", "সবকিছু এই প্রথম ট্যাব থেকে শুরু হয়। আপনি একটি সিজন বেছে নেন, তারপর পাশে খুলে যাওয়া লিস্টিং, আর প্ল্যানার তিনটি ট্যাবে বাঁ থেকে ডানে চলে। যে লিস্টিংয়ের খাবারের পরিকল্পনা আগে থেকেই আছে, সেটি নিচে তালিকাভুক্ত থাকে, যাতে সরাসরি সেখানে ফিরে যেতে পারেন।", "كل شيء يبدأ من هذا التبويب الأول. تختار موسمًا، ثم العرض الذي ينزلق بجانبه، ويسير المخطِّط من اليمين إلى اليسار عبر ثلاثة تبويبات. أي عرض لديه خطة وجبات مسبقًا يظهر في الأسفل لتعود إليه مباشرة.", "Tudo começa neste primeiro separador. Escolhe uma época, depois a oferta que surge ao lado, e o planeador segue da esquerda para a direita por três separadores. Qualquer oferta que já tenha um plano de refeições aparece abaixo para voltar diretamente a ela.", "Todo empieza en esta primera pestaña. Eliges una temporada, luego la oferta que se desliza a su lado, y el planificador avanza de izquierda a derecha por tres pestañas. Cualquier oferta que ya tenga un plan de comidas aparece debajo para volver directamente a ella.", "Tout commence dans ce premier onglet. Vous choisissez une saison, puis l'offre qui apparaît à côté, et le planificateur avance de gauche à droite sur trois onglets. Toute offre qui a déjà un plan de repas est listée en dessous pour y retourner directement.", "Mae popeth yn dechrau ar y tab cyntaf hwn. Rydych chi'n dewis tymor, yna'r rhestriad sy'n llithro allan wrth ei ymyl, ac mae'r cynlluniwr yn rhedeg o'r chwith i'r dde ar draws tri thab. Mae unrhyw restriad sydd eisoes â chynllun prydau wedi'i restru isod i neidio'n syth yn ôl iddo."],
  "lt_meals_s1": ["The Menu and Days tabs are where you plan. You tap a menu, pick which dish or two each weekday serves — offer both a meat and a veg and families choose at checkout — then paint it onto the run-days. It all saves as you go.", "Karty Menu i Dni służą do planowania. Stukasz w menu, wybierasz, jedno czy dwa dania serwuje każdy dzień tygodnia — jeśli dasz i mięsne, i wegetariańskie, rodziny wybierają przy płatności — a potem rozkładasz je na dni. Wszystko zapisuje się na bieżąco.", "Filele Meniu și Zile sunt locul unde planifici. Atingi un meniu, alegi ce preparat sau două se servesc în fiecare zi a săptămânii — dacă oferi și unul cu carne, și unul vegetarian, familiile aleg la finalizarea comenzii — apoi îl așezi pe zilele de desfășurare. Totul se salvează pe parcurs.", "مینو اور دن کے ٹیب وہ جگہ ہیں جہاں آپ منصوبہ بناتے ہیں۔ آپ ایک مینو پر ٹیپ کرتے ہیں، ہر ہفتے کے دن کے لیے ایک یا دو کھانے چنتے ہیں — گوشت اور سبزی دونوں رکھیں تو خاندان چیک آؤٹ پر چنتے ہیں — پھر اسے چلنے والے دنوں پر لگاتے ہیں۔ سب کچھ ساتھ ساتھ محفوظ ہوتا جاتا ہے۔", "ਮੀਨੂ ਅਤੇ ਦਿਨ ਟੈਬ ਉਹ ਥਾਂ ਹਨ ਜਿੱਥੇ ਤੁਸੀਂ ਯੋਜਨਾ ਬਣਾਉਂਦੇ ਹੋ। ਤੁਸੀਂ ਇੱਕ ਮੀਨੂ ਉੱਤੇ ਟੈਪ ਕਰਦੇ ਹੋ, ਹਰ ਹਫ਼ਤੇ ਦੇ ਦਿਨ ਲਈ ਇੱਕ ਜਾਂ ਦੋ ਪਕਵਾਨ ਚੁਣਦੇ ਹੋ — ਮਾਸ ਅਤੇ ਸਬਜ਼ੀ ਦੋਵੇਂ ਦਿਓ ਤਾਂ ਪਰਿਵਾਰ ਚੈੱਕਆਉਟ ਵੇਲੇ ਚੁਣਦੇ ਹਨ — ਫਿਰ ਇਸ ਨੂੰ ਚੱਲਣ ਵਾਲੇ ਦਿਨਾਂ ਉੱਤੇ ਲਗਾਉਂਦੇ ਹੋ। ਸਭ ਕੁਝ ਨਾਲੋ-ਨਾਲ ਸੁਰੱਖਿਅਤ ਹੁੰਦਾ ਜਾਂਦਾ ਹੈ।", "মেনু ও দিন ট্যাবে আপনি পরিকল্পনা করেন। একটি মেনুতে ট্যাপ করুন, সপ্তাহের প্রতিটি দিনে কোন একটি বা দুটি খাবার পরিবেশন হবে তা বেছে নিন — মাংস আর নিরামিষ দুটোই দিলে পরিবার চেকআউটের সময় বেছে নেয় — তারপর সেটি চলার দিনগুলোতে বসিয়ে দিন। সবকিছু চলতে চলতেই সেভ হয়ে যায়।", "تبويبا القائمة والأيام هما مكان التخطيط. تضغط على قائمة طعام، وتختار طبقًا أو طبقين لكل يوم من أيام الأسبوع — فإن قدّمت طبق لحم وطبقًا نباتيًا اختارت العائلات عند الدفع — ثم توزّعها على أيام التشغيل. ويُحفظ كل شيء أولًا بأول.", "Os separadores Menu e Dias são onde planeia. Toca num menu, escolhe que prato ou dois serve cada dia da semana — se oferecer um de carne e um vegetariano, as famílias escolhem no pagamento — e depois distribui-o pelos dias de funcionamento. Tudo é guardado à medida que avança.", "Las pestañas Menú y Días son donde planificas. Tocas un menú, eliges qué plato o dos sirve cada día de la semana (si ofreces uno de carne y otro vegetariano, las familias eligen al pagar) y luego lo extiendes por los días de la actividad. Todo se guarda sobre la marcha.", "Les onglets Menu et Jours sont l'endroit où vous planifiez. Vous touchez un menu, choisissez quel plat ou quels deux plats sont servis chaque jour de la semaine — si vous proposez un plat de viande et un végétarien, les familles choisissent au paiement — puis vous l'étalez sur les jours d'activité. Tout s'enregistre au fur et à mesure.", "Y tabiau Bwydlen a Diwrnodau yw lle rydych chi'n cynllunio. Tapiwch fwydlen, dewiswch pa bryd neu ddau sy'n cael ei weini bob diwrnod o'r wythnos — cynigiwch gig a llysieuol a bydd teuluoedd yn dewis wrth dalu — yna paentiwch hi ar y diwrnodau rhedeg. Mae'r cyfan yn cael ei gadw wrth i chi fynd."],
  "lt_meals_s2": ["The Sharing tab sets the rules: who sees each day's menu, how late families can order, a standard allergen note, and whether meal swaps need your say-so. Each saved plan can also email its caterer the orders on a schedule.", "Karta Udostępnianie ustala zasady: kto widzi menu na dany dzień, do kiedy rodziny mogą zamawiać, standardową informację o alergenach i to, czy zamiana posiłków wymaga Twojej zgody. Każdy zapisany plan może też wysyłać cateringowi zamówienia e-mailem według harmonogramu.", "Fila Partajare stabilește regulile: cine vede meniul fiecărei zile, cât de târziu pot comanda familiile, o notă standard despre alergeni și dacă schimbarea meselor necesită acordul tău. Fiecare plan salvat poate trimite prin e-mail comenzile către furnizorul de catering, după un program.", "شیئرنگ ٹیب اصول طے کرتا ہے: ہر دن کا مینو کون دیکھے، خاندان کتنی دیر تک آرڈر کر سکتے ہیں، الرجی کا ایک معیاری نوٹ، اور کھانوں کی تبدیلی کے لیے آپ کی منظوری ضروری ہے یا نہیں۔ ہر محفوظ پلان شیڈول کے مطابق کیٹرر کو آرڈر ای میل بھی کر سکتا ہے۔", "ਸ਼ੇਅਰਿੰਗ ਟੈਬ ਨਿਯਮ ਤੈਅ ਕਰਦਾ ਹੈ: ਹਰ ਦਿਨ ਦਾ ਮੀਨੂ ਕੌਣ ਵੇਖੇ, ਪਰਿਵਾਰ ਕਿੰਨੀ ਦੇਰ ਤੱਕ ਆਰਡਰ ਕਰ ਸਕਦੇ ਹਨ, ਐਲਰਜੀ ਬਾਰੇ ਇੱਕ ਮਿਆਰੀ ਨੋਟ, ਅਤੇ ਕੀ ਭੋਜਨ ਬਦਲਣ ਲਈ ਤੁਹਾਡੀ ਮਨਜ਼ੂਰੀ ਚਾਹੀਦੀ ਹੈ। ਹਰ ਸੁਰੱਖਿਅਤ ਪਲਾਨ ਸਮਾਂ-ਸਾਰਣੀ ਅਨੁਸਾਰ ਕੇਟਰਰ ਨੂੰ ਆਰਡਰ ਈਮੇਲ ਵੀ ਕਰ ਸਕਦਾ ਹੈ।", "শেয়ারিং ট্যাব নিয়ম ঠিক করে: প্রতিদিনের মেনু কে দেখবে, পরিবারগুলো কত দেরি পর্যন্ত অর্ডার করতে পারবে, অ্যালার্জি নিয়ে একটি স্ট্যান্ডার্ড নোট, আর খাবার বদলাতে আপনার অনুমোদন লাগবে কি না। প্রতিটি সংরক্ষিত পরিকল্পনা নির্ধারিত সময়ে ক্যাটারারকে অর্ডার ইমেইলও করতে পারে।", "تبويب المشاركة يضع القواعد: من يرى قائمة كل يوم، ومتى آخر موعد تطلب فيه العائلات، وملاحظة موحّدة عن الحساسية، وهل يحتاج تبديل الوجبات إلى موافقتك. ويمكن لكل خطة محفوظة أيضًا أن ترسل الطلبات بالبريد الإلكتروني إلى متعهّد الطعام وفق جدول.", "O separador Partilha define as regras: quem vê o menu de cada dia, até que hora as famílias podem encomendar, uma nota padrão sobre alergénios e se as trocas de refeição precisam da sua aprovação. Cada plano guardado pode também enviar por e-mail os pedidos ao fornecedor, segundo um calendário.", "La pestaña Compartir fija las reglas: quién ve el menú de cada día, hasta qué hora pueden pedir las familias, una nota estándar sobre alérgenos y si los cambios de comida necesitan tu visto bueno. Cada plan guardado también puede enviar por correo los pedidos a su proveedor de catering según un calendario.", "L'onglet Partage fixe les règles : qui voit le menu de chaque jour, jusqu'à quelle heure les familles peuvent commander, une note standard sur les allergènes, et si les échanges de repas nécessitent votre accord. Chaque plan enregistré peut aussi envoyer les commandes par e-mail à son traiteur selon un calendrier.", "Mae'r tab Rhannu yn gosod y rheolau: pwy sy'n gweld bwydlen pob diwrnod, pa mor hwyr y gall teuluoedd archebu, nodyn alergenau safonol, ac a oes angen eich cymeradwyaeth ar gyfer cyfnewid prydau. Gall pob cynllun sydd wedi'i gadw hefyd anfon yr archebion at ei gyflenwr bwyd trwy e-bost yn ôl amserlen."],
  "lt_meals_s3": ["Menus have their own tab and get reused across all your listings. Let's build one together now.", "Menu mają własną kartę i są używane ponownie we wszystkich Twoich ofertach. Zbudujmy teraz jedno razem.", "Meniurile au propria filă și se reutilizează în toate ofertele tale. Hai să construim unul împreună chiar acum.", "مینو کا اپنا ٹیب ہے اور انہیں آپ کی تمام لسٹنگز میں دوبارہ استعمال کیا جاتا ہے۔ آئیے اب مل کر ایک بناتے ہیں۔", "ਮੀਨੂ ਦਾ ਆਪਣਾ ਟੈਬ ਹੈ ਅਤੇ ਇਹ ਤੁਹਾਡੀਆਂ ਸਾਰੀਆਂ ਲਿਸਟਿੰਗਾਂ ਵਿੱਚ ਦੁਬਾਰਾ ਵਰਤੇ ਜਾਂਦੇ ਹਨ। ਆਓ ਹੁਣ ਮਿਲ ਕੇ ਇੱਕ ਬਣਾਈਏ।", "মেনুর নিজস্ব ট্যাব আছে এবং সেগুলো আপনার সব লিস্টিংয়ে আবার ব্যবহার করা যায়। চলুন এখনই একসঙ্গে একটি বানাই।", "لقوائم الطعام تبويبها الخاص، وتُعاد الاستفادة منها في جميع عروضك. هيا ننشئ واحدة معًا الآن.", "Os menus têm o seu próprio separador e são reutilizados em todas as suas ofertas. Vamos criar um juntos agora.", "Los menús tienen su propia pestaña y se reutilizan en todas tus ofertas. Vamos a crear uno juntos ahora.", "Les menus ont leur propre onglet et sont réutilisés dans toutes vos offres. Construisons-en un ensemble maintenant.", "Mae gan fwydlenni eu tab eu hunain ac maen nhw'n cael eu hailddefnyddio ar draws eich holl restriadau. Gadewch i ni adeiladu un gyda'n gilydd nawr."],
  "lt_meals_s4": ["To add one, you press New menu, and this form opens.", "Aby dodać menu, naciskasz Nowe menu i otwiera się ten formularz.", "Pentru a adăuga unul, apeși Meniu nou și se deschide acest formular.", "نیا شامل کرنے کے لیے آپ «نیا مینو» دباتے ہیں، اور یہ فارم کھل جاتا ہے۔", "ਨਵਾਂ ਜੋੜਨ ਲਈ ਤੁਸੀਂ «ਨਵਾਂ ਮੀਨੂ» ਦਬਾਉਂਦੇ ਹੋ, ਅਤੇ ਇਹ ਫਾਰਮ ਖੁੱਲ੍ਹ ਜਾਂਦਾ ਹੈ।", "একটি যোগ করতে আপনি «নতুন মেনু» চাপেন, আর এই ফর্মটি খুলে যায়।", "لإضافة واحدة، تضغط على «قائمة جديدة» فيُفتح هذا النموذج.", "Para adicionar um, prime Novo menu e este formulário abre-se.", "Para añadir uno, pulsas Nuevo menú y se abre este formulario.", "Pour en ajouter un, vous appuyez sur Nouveau menu et ce formulaire s'ouvre.", "I ychwanegu un, pwyswch Bwydlen newydd ac mae'r ffurflen hon yn agor."],
  "lt_meals_s5": ["First give the menu a name you'll recognise — something like Summer camp hot lunches.", "Najpierw nadaj menu nazwę, którą łatwo rozpoznasz — na przykład Gorące obiady na obozie letnim.", "Mai întâi dă meniului un nume pe care îl vei recunoaște — de exemplu Prânzuri calde la tabăra de vară.", "پہلے مینو کو ایسا نام دیں جو آپ پہچان سکیں — مثلاً سمر کیمپ کے گرم لنچ۔", "ਪਹਿਲਾਂ ਮੀਨੂ ਨੂੰ ਇੱਕ ਅਜਿਹਾ ਨਾਂ ਦਿਓ ਜੋ ਤੁਸੀਂ ਪਛਾਣ ਸਕੋ — ਜਿਵੇਂ ਸਮਰ ਕੈਂਪ ਦੇ ਗਰਮ ਲੰਚ।", "প্রথমে মেনুর এমন একটি নাম দিন যা আপনি চিনতে পারবেন — যেমন সামার ক্যাম্পের গরম দুপুরের খাবার।", "أولًا أعطِ القائمة اسمًا تتعرّف عليه — مثل «غداء ساخن لمخيم الصيف».", "Primeiro dê ao menu um nome que reconheça — algo como Almoços quentes do campo de verão.", "Primero ponle al menú un nombre que reconozcas, algo como Comidas calientes del campamento de verano.", "Commencez par donner au menu un nom que vous reconnaîtrez, par exemple Déjeuners chauds du camp d'été.", "Yn gyntaf rhowch enw i'r fwydlen y byddwch chi'n ei adnabod — rhywbeth fel Cinio poeth gwersyll yr haf."],
  "lt_meals_s6": ["Now add a meal: its name, the price in pounds, a daily limit if the kitchen caps it, and a quick description. Tag it Meat, Vegetarian or Vegan so families can filter at a glance.", "Teraz dodaj posiłek: jego nazwę, cenę w funtach, dzienny limit, jeśli kuchnia go ustala, i krótki opis. Oznacz go jako Mięsny, Wegetariański lub Wegański, żeby rodziny mogły szybko filtrować.", "Acum adaugă o masă: numele ei, prețul în lire, o limită zilnică dacă bucătăria are una și o scurtă descriere. Marchează-o ca Carne, Vegetarian sau Vegan, ca familiile să filtreze dintr-o privire.", "اب ایک کھانا شامل کریں: اس کا نام، پاؤنڈ میں قیمت، اگر باورچی خانہ حد مقرر کرے تو روزانہ کی حد، اور مختصر وضاحت۔ اسے گوشت، سبزی خور یا ویگن کا ٹیگ دیں تاکہ خاندان ایک نظر میں فلٹر کر سکیں۔", "ਹੁਣ ਇੱਕ ਭੋਜਨ ਜੋੜੋ: ਉਸ ਦਾ ਨਾਂ, ਪੌਂਡ ਵਿੱਚ ਕੀਮਤ, ਜੇ ਰਸੋਈ ਸੀਮਾ ਰੱਖਦੀ ਹੈ ਤਾਂ ਰੋਜ਼ਾਨਾ ਸੀਮਾ, ਅਤੇ ਇੱਕ ਛੋਟਾ ਵੇਰਵਾ। ਇਸ ਨੂੰ ਮਾਸਾਹਾਰੀ, ਸ਼ਾਕਾਹਾਰੀ ਜਾਂ ਵੀਗਨ ਟੈਗ ਕਰੋ ਤਾਂ ਜੋ ਪਰਿਵਾਰ ਇੱਕ ਨਜ਼ਰ ਵਿੱਚ ਫਿਲਟਰ ਕਰ ਸਕਣ।", "এবার একটি খাবার যোগ করুন: তার নাম, পাউন্ডে দাম, রান্নাঘর সীমা রাখলে দৈনিক সীমা, আর সংক্ষিপ্ত বিবরণ। এটিকে মাংস, নিরামিষ বা ভেগান ট্যাগ করুন, যাতে পরিবারগুলো এক নজরে ফিল্টার করতে পারে।", "الآن أضِف وجبة: اسمها، وسعرها بالجنيه، وحدًّا يوميًا إن كان المطبخ يضع حدًّا، ووصفًا مختصرًا. صنِّفها لحمًا أو نباتيًا أو نباتيًا صرفًا (فيغان) لتتمكّن العائلات من التصفية بنظرة سريعة.", "Agora adicione uma refeição: o nome, o preço em libras, um limite diário se a cozinha tiver um, e uma breve descrição. Etiquete-a como Carne, Vegetariana ou Vegana para as famílias filtrarem de relance.", "Ahora añade una comida: su nombre, el precio en libras, un límite diario si la cocina lo fija y una breve descripción. Etiquétala como Carne, Vegetariana o Vegana para que las familias filtren de un vistazo.", "Ajoutez maintenant un repas : son nom, le prix en livres, une limite quotidienne si la cuisine en fixe une, et une courte description. Indiquez Viande, Végétarien ou Végan pour que les familles filtrent en un coup d'œil.", "Nawr ychwanegwch bryd: ei enw, y pris mewn punnoedd, terfyn dyddiol os yw'r gegin yn gosod un, a disgrifiad byr. Tagiwch ef yn Cig, Llysieuol neu Figan fel y gall teuluoedd hidlo'n gyflym."],
  "lt_meals_s7": ["Then tick any of the fourteen UK allergens it contains — here gluten and milk — so every family sees them spelled out clearly.", "Potem zaznacz wszystkie z czternastu brytyjskich alergenów, które zawiera — tu gluten i mleko — żeby każda rodzina widziała je wyraźnie wypisane.", "Apoi bifează oricare dintre cei paisprezece alergeni din Marea Britanie pe care îi conține — aici gluten și lapte — ca fiecare familie să îi vadă clar scriși.", "پھر یو کے کے چودہ الرجنز میں سے جو بھی اس میں ہوں انہیں ٹک کریں — یہاں گلوٹن اور دودھ — تاکہ ہر خاندان انہیں صاف لکھا ہوا دیکھے۔", "ਫਿਰ ਯੂਕੇ ਦੇ ਚੌਦਾਂ ਐਲਰਜਨਾਂ ਵਿੱਚੋਂ ਜੋ ਵੀ ਇਸ ਵਿੱਚ ਹਨ ਉਨ੍ਹਾਂ ਨੂੰ ਟਿੱਕ ਕਰੋ — ਇੱਥੇ ਗਲੂਟਨ ਅਤੇ ਦੁੱਧ — ਤਾਂ ਜੋ ਹਰ ਪਰਿਵਾਰ ਉਨ੍ਹਾਂ ਨੂੰ ਸਾਫ਼ ਲਿਖਿਆ ਵੇਖੇ।", "তারপর যুক্তরাজ্যের চৌদ্দটি অ্যালার্জেনের মধ্যে যেগুলো এতে আছে সেগুলোতে টিক দিন — এখানে গ্লুটেন ও দুধ — যাতে প্রতিটি পরিবার সেগুলো স্পষ্ট লেখা দেখে।", "ثم ضع علامة على أي من مسبّبات الحساسية الأربعة عشر في المملكة المتحدة التي تحتويها الوجبة — هنا الغلوتين والحليب — لكي ترى كل عائلة ذلك مكتوبًا بوضوح.", "Depois assinale qualquer um dos catorze alergénios do Reino Unido que contenha — aqui glúten e leite — para que cada família os veja claramente indicados.", "Luego marca cualquiera de los catorce alérgenos del Reino Unido que contenga (aquí gluten y leche) para que cada familia los vea indicados con claridad.", "Cochez ensuite chacun des quatorze allergènes britanniques qu'il contient — ici le gluten et le lait — pour que chaque famille les voie clairement indiqués.", "Yna ticiwch unrhyw un o'r pedwar alergen ar ddeg yn y DU y mae'n eu cynnwys — glwten a llaeth yma — fel bod pob teulu'n eu gweld wedi'u nodi'n glir."],
  "lt_meals_s8": ["You can press Add another meal to pop in the veg choice too — then press Save menu. That stores it in your library, ready to drop onto any listing's days.", "Możesz nacisnąć Dodaj kolejny posiłek, żeby dorzucić też wariant wegetariański — a potem Zapisz menu. Trafi ono do Twojej biblioteki, gotowe do przypisania do dni dowolnej oferty.", "Poți apăsa Adaugă încă o masă ca să introduci și opțiunea vegetariană — apoi apeși Salvează meniul. Se păstrează în biblioteca ta, gata de așezat pe zilele oricărei oferte.", "آپ «ایک اور کھانا شامل کریں» دبا کر سبزی والا انتخاب بھی ڈال سکتے ہیں — پھر «مینو محفوظ کریں» دبائیں۔ یہ آپ کی لائبریری میں محفوظ ہو جاتا ہے، کسی بھی لسٹنگ کے دنوں پر لگانے کے لیے تیار۔", "ਤੁਸੀਂ «ਇੱਕ ਹੋਰ ਭੋਜਨ ਜੋੜੋ» ਦਬਾ ਕੇ ਸ਼ਾਕਾਹਾਰੀ ਵਿਕਲਪ ਵੀ ਪਾ ਸਕਦੇ ਹੋ — ਫਿਰ «ਮੀਨੂ ਸੰਭਾਲੋ» ਦਬਾਓ। ਇਹ ਤੁਹਾਡੀ ਲਾਇਬ੍ਰੇਰੀ ਵਿੱਚ ਸੁਰੱਖਿਅਤ ਹੋ ਜਾਂਦਾ ਹੈ, ਕਿਸੇ ਵੀ ਲਿਸਟਿੰਗ ਦੇ ਦਿਨਾਂ ਉੱਤੇ ਲਗਾਉਣ ਲਈ ਤਿਆਰ।", "«আরেকটি খাবার যোগ করুন» চেপে নিরামিষ বিকল্পটিও দিতে পারেন — তারপর «মেনু সেভ করুন» চাপুন। এটি আপনার লাইব্রেরিতে জমা হয়, যেকোনো লিস্টিংয়ের দিনে বসানোর জন্য প্রস্তুত।", "يمكنك الضغط على «إضافة وجبة أخرى» لإدخال الخيار النباتي أيضًا — ثم اضغط «حفظ القائمة». بذلك تُخزَّن في مكتبتك، جاهزة لوضعها على أيام أي عرض.", "Pode premir Adicionar outra refeição para incluir também a opção vegetariana — e depois Guardar menu. Fica na sua biblioteca, pronto para ser colocado nos dias de qualquer oferta.", "Puedes pulsar Añadir otra comida para incluir también la opción vegetariana, y luego Guardar menú. Se guarda en tu biblioteca, listo para colocarlo en los días de cualquier oferta.", "Vous pouvez appuyer sur Ajouter un autre repas pour glisser aussi le choix végétarien, puis sur Enregistrer le menu. Il est stocké dans votre bibliothèque, prêt à être posé sur les jours de n'importe quelle offre.", "Gallwch wasgu Ychwanegu pryd arall i roi'r dewis llysieuol i mewn hefyd — yna pwyswch Cadw bwydlen. Mae'n cael ei storio yn eich llyfrgell, yn barod i'w roi ar ddiwrnodau unrhyw restriad."],
  "lt_customers_title": ["Families", "Rodziny", "Familii", "خاندان", "ਪਰਿਵਾਰ", "পরিবার", "العائلات", "Famílias", "Familias", "Familles", "Teuluoedd"],
  "lt_customers_intro": ["This is your self-filling little black book (the page calls it Leads and customers) — every booking quietly pops the family in here, so you only ever type when someone rings up or you spot a correction, and you can see exactly where each family sits from first enquiry to happy regular.", "To Twój samouzupełniający się notesik z kontaktami (na stronie nazywa się Potencjalni i klienci) — każda rezerwacja po cichu dodaje tu rodzinę, więc piszesz tylko wtedy, gdy ktoś zadzwoni albo zauważysz poprawkę, i widzisz dokładnie, na jakim etapie jest każda rodzina, od pierwszego zapytania po stałego klienta.", "Acesta este carnetul tău de contacte care se completează singur (pagina îl numește Potențiali clienți și clienți) — fiecare rezervare adaugă discret familia aici, așa că scrii doar când sună cineva sau vezi o corectură, și vezi exact unde se află fiecare familie, de la prima solicitare până la client fidel.", "یہ آپ کی خود بخود بھرنے والی چھوٹی سی رابطہ کتاب ہے (صفحے پر اس کا نام لیڈز اور کسٹمرز ہے) — ہر بکنگ خاموشی سے خاندان کو یہاں شامل کر دیتی ہے، اس لیے آپ کو صرف تب ٹائپ کرنا پڑتا ہے جب کوئی فون کرے یا کوئی درستی نظر آئے، اور آپ دیکھ سکتے ہیں کہ ہر خاندان پہلی پوچھ گچھ سے لے کر مستقل گاہک بننے تک کہاں کھڑا ہے۔", "ਇਹ ਤੁਹਾਡੀ ਆਪਣੇ-ਆਪ ਭਰਨ ਵਾਲੀ ਛੋਟੀ ਸੰਪਰਕ ਕਿਤਾਬ ਹੈ (ਪੰਨੇ ਉੱਤੇ ਇਸ ਨੂੰ ਲੀਡਜ਼ ਅਤੇ ਗਾਹਕ ਕਿਹਾ ਜਾਂਦਾ ਹੈ) — ਹਰ ਬੁਕਿੰਗ ਚੁੱਪ-ਚਾਪ ਪਰਿਵਾਰ ਨੂੰ ਇੱਥੇ ਜੋੜ ਦਿੰਦੀ ਹੈ, ਇਸ ਲਈ ਤੁਸੀਂ ਸਿਰਫ਼ ਓਦੋਂ ਟਾਈਪ ਕਰਦੇ ਹੋ ਜਦੋਂ ਕੋਈ ਫ਼ੋਨ ਕਰੇ ਜਾਂ ਸੁਧਾਰ ਦਿਸੇ, ਅਤੇ ਤੁਸੀਂ ਵੇਖ ਸਕਦੇ ਹੋ ਕਿ ਹਰ ਪਰਿਵਾਰ ਪਹਿਲੀ ਪੁੱਛਗਿੱਛ ਤੋਂ ਪੱਕੇ ਗਾਹਕ ਤੱਕ ਕਿੱਥੇ ਹੈ।", "এটি আপনার নিজে নিজে ভরে যাওয়া ছোট্ট যোগাযোগের খাতা (পেজে এর নাম লিডস ও গ্রাহক) — প্রতিটি বুকিং চুপচাপ পরিবারটিকে এখানে যোগ করে দেয়, তাই কেউ ফোন করলে বা কোনো সংশোধন চোখে পড়লেই আপনাকে লিখতে হয়, আর প্রথম জিজ্ঞাসা থেকে নিয়মিত গ্রাহক হওয়া পর্যন্ত প্রতিটি পরিবার ঠিক কোথায় আছে তা দেখতে পান।", "هذا دفتر عناوينك الصغير الذي يملأ نفسه بنفسه (تسمّيه الصفحة «العملاء المحتملون والعملاء») — كل حجز يضيف العائلة إلى هنا بهدوء، فلا تكتب إلا حين يتصل أحدهم أو تلاحظ تصحيحًا، وترى بالضبط أين تقف كل عائلة، من أول استفسار إلى عميل دائم.", "Este é o seu livrinho de contactos que se preenche sozinho (a página chama-lhe Potenciais clientes e clientes) — cada reserva coloca discretamente a família aqui, por isso só escreve quando alguém telefona ou nota uma correção, e vê exatamente em que fase está cada família, desde o primeiro contacto até ao cliente habitual.", "Esta es tu agenda que se rellena sola (la página la llama Contactos y clientes): cada reserva añade discretamente a la familia aquí, así que solo escribes cuando alguien llama o ves una corrección, y ves exactamente en qué punto está cada familia, desde la primera consulta hasta cliente habitual.", "C'est votre petit carnet d'adresses qui se remplit tout seul (la page l'appelle Prospects et clients) — chaque réservation y ajoute discrètement la famille, donc vous ne saisissez que lorsqu'on vous appelle ou que vous repérez une correction, et vous voyez exactement où en est chaque famille, de la première demande au client fidèle.", "Dyma'ch llyfr cyfeiriadau bach sy'n llenwi ei hun (mae'r dudalen yn ei alw'n Ymholiadau a chwsmeriaid) — mae pob archeb yn ychwanegu'r teulu yma'n dawel, felly dim ond pan fydd rhywun yn ffonio neu pan welwch gywiriad y byddwch chi'n teipio, a gallwch weld yn union ble mae pob teulu, o'r ymholiad cyntaf i fod yn gwsmer rheolaidd."],
  "lt_customers_done": ["And that's Families — a CRM that mostly fills itself in, so you can spend your time chasing bookings rather than typing them up.", "I to wszystko o Rodzinach — CRM, który w większości wypełnia się sam, więc czas możesz poświęcić na zdobywanie rezerwacji, a nie na ich przepisywanie.", "Și gata cu Familiile — un CRM care se completează în mare parte singur, ca să-ți petreci timpul atrăgând rezervări, nu tastându-le.", "بس یہ تھا خاندانوں کا حصہ — ایک سی آر ایم جو زیادہ تر خود ہی بھر جاتا ہے، تاکہ آپ بکنگز ٹائپ کرنے کے بجائے بکنگز حاصل کرنے میں وقت لگائیں۔", "ਬੱਸ ਇਹੀ ਹੈ ਪਰਿਵਾਰਾਂ ਦਾ ਹਿੱਸਾ — ਇੱਕ ਸੀਆਰਐਮ ਜੋ ਜ਼ਿਆਦਾਤਰ ਆਪਣੇ-ਆਪ ਭਰ ਜਾਂਦਾ ਹੈ, ਤਾਂ ਜੋ ਤੁਸੀਂ ਬੁਕਿੰਗਾਂ ਟਾਈਪ ਕਰਨ ਦੀ ਬਜਾਏ ਬੁਕਿੰਗਾਂ ਲੱਭਣ ਵਿੱਚ ਸਮਾਂ ਲਗਾਓ।", "পরিবার অংশ এখানেই শেষ — একটি সিআরএম যা বেশিরভাগ নিজেই ভরে যায়, যাতে আপনি বুকিং টাইপ করার বদলে বুকিং পেতে সময় দিতে পারেন।", "وهذا كل شيء عن العائلات — نظام لإدارة العملاء يملأ نفسه في الغالب، فتقضي وقتك في جلب الحجوزات بدل كتابتها.", "E é isto nas Famílias — um CRM que se preenche quase sozinho, para gastar o seu tempo a conseguir reservas em vez de as escrever.", "Y eso es todo en Familias: un CRM que casi se rellena solo, para que dediques tu tiempo a conseguir reservas en vez de teclearlas.", "Et voilà pour les Familles — un CRM qui se remplit presque tout seul, pour que vous passiez votre temps à décrocher des réservations plutôt qu'à les saisir.", "A dyna ni gyda Teuluoedd — CRM sy'n llenwi ei hun gan amlaf, fel y gallwch dreulio'ch amser yn denu archebion yn hytrach na'u teipio."],
  "lt_customers_s0": ["This page is your self-filling little black book. Every booking quietly drops the family in here, so you only ever type when someone rings up or you spot a correction.", "Ta strona to Twój samouzupełniający się notesik. Każda rezerwacja po cichu dodaje tu rodzinę, więc piszesz tylko wtedy, gdy ktoś zadzwoni albo zauważysz poprawkę.", "Această pagină este carnetul tău de contacte care se completează singur. Fiecare rezervare adaugă discret familia aici, așa că scrii doar când sună cineva sau vezi o corectură.", "یہ صفحہ آپ کی خود بخود بھرنے والی چھوٹی رابطہ کتاب ہے۔ ہر بکنگ خاموشی سے خاندان کو یہاں ڈال دیتی ہے، اس لیے آپ کو صرف تب ٹائپ کرنا پڑتا ہے جب کوئی فون کرے یا کوئی درستی نظر آئے۔", "ਇਹ ਪੰਨਾ ਤੁਹਾਡੀ ਆਪਣੇ-ਆਪ ਭਰਨ ਵਾਲੀ ਛੋਟੀ ਸੰਪਰਕ ਕਿਤਾਬ ਹੈ। ਹਰ ਬੁਕਿੰਗ ਚੁੱਪ-ਚਾਪ ਪਰਿਵਾਰ ਨੂੰ ਇੱਥੇ ਪਾ ਦਿੰਦੀ ਹੈ, ਇਸ ਲਈ ਤੁਸੀਂ ਸਿਰਫ਼ ਓਦੋਂ ਟਾਈਪ ਕਰਦੇ ਹੋ ਜਦੋਂ ਕੋਈ ਫ਼ੋਨ ਕਰੇ ਜਾਂ ਸੁਧਾਰ ਦਿਸੇ।", "এই পেজটি আপনার নিজে নিজে ভরে যাওয়া ছোট্ট যোগাযোগের খাতা। প্রতিটি বুকিং চুপচাপ পরিবারটিকে এখানে যোগ করে, তাই কেউ ফোন করলে বা কোনো সংশোধন চোখে পড়লেই আপনাকে লিখতে হয়।", "هذه الصفحة هي دفتر عناوينك الصغير الذي يملأ نفسه. كل حجز يضع العائلة هنا بهدوء، فلا تكتب إلا حين يتصل أحدهم أو تلاحظ تصحيحًا.", "Esta página é o seu livrinho de contactos que se preenche sozinho. Cada reserva coloca discretamente a família aqui, por isso só escreve quando alguém telefona ou nota uma correção.", "Esta página es tu agenda que se rellena sola. Cada reserva deja a la familia aquí discretamente, así que solo escribes cuando alguien llama o ves una corrección.", "Cette page est votre petit carnet d'adresses qui se remplit tout seul. Chaque réservation y dépose discrètement la famille, donc vous ne saisissez que lorsqu'on vous appelle ou que vous repérez une correction.", "Y dudalen hon yw'ch llyfr cyfeiriadau bach sy'n llenwi ei hun. Mae pob archeb yn gollwng y teulu yma'n dawel, felly dim ond pan fydd rhywun yn ffonio neu pan welwch gywiriad y byddwch chi'n teipio."],
  "lt_customers_s1": ["The tiles across the top are your funnel and your filter in one. Each count shows where families have got to, and tapping a tile narrows the list to just that stage — leads, invited, customers and repeats.", "Kafelki u góry to jednocześnie Twój lejek i filtr. Każda liczba pokazuje, na jakim etapie są rodziny, a stuknięcie kafelka zawęża listę do tego etapu — potencjalni, zaproszeni, klienci i powracający.", "Casetele de sus sunt pâlnia ta și filtrul tău într-una. Fiecare număr arată unde au ajuns familiile, iar atingerea unei casete restrânge lista la acea etapă — potențiali, invitați, clienți și clienți recurenți.", "اوپر کی ٹائلیں آپ کا فنل اور فلٹر دونوں ہیں۔ ہر گنتی دکھاتی ہے کہ خاندان کہاں تک پہنچے ہیں، اور کسی ٹائل پر ٹیپ کرنے سے فہرست اسی مرحلے تک محدود ہو جاتی ہے — لیڈز، مدعو کیے گئے، گاہک اور دوبارہ آنے والے۔", "ਉੱਪਰਲੀਆਂ ਟਾਈਲਾਂ ਤੁਹਾਡਾ ਫਨਲ ਵੀ ਹਨ ਅਤੇ ਫਿਲਟਰ ਵੀ। ਹਰ ਗਿਣਤੀ ਦੱਸਦੀ ਹੈ ਕਿ ਪਰਿਵਾਰ ਕਿੱਥੇ ਤੱਕ ਪਹੁੰਚੇ ਹਨ, ਅਤੇ ਕਿਸੇ ਟਾਈਲ ਉੱਤੇ ਟੈਪ ਕਰਨ ਨਾਲ ਸੂਚੀ ਉਸੇ ਪੜਾਅ ਤੱਕ ਸੀਮਤ ਹੋ ਜਾਂਦੀ ਹੈ — ਲੀਡਜ਼, ਸੱਦੇ ਗਏ, ਗਾਹਕ ਅਤੇ ਦੁਬਾਰਾ ਆਉਣ ਵਾਲੇ।", "ওপরের টাইলগুলো একসঙ্গে আপনার ফানেল আর ফিল্টার। প্রতিটি সংখ্যা দেখায় পরিবারগুলো কোথায় পৌঁছেছে, আর কোনো টাইলে ট্যাপ করলে তালিকা সেই ধাপেই সীমিত হয়ে যায় — লিডস, আমন্ত্রিত, গ্রাহক এবং পুনরাগত।", "البطاقات في الأعلى هي قمعك ومرشّحك في آن واحد. كل رقم يُظهر أين وصلت العائلات، وبالضغط على بطاقة تُحصَر القائمة في تلك المرحلة فقط — المحتملون، المدعوّون، العملاء، والمتكررون.", "Os mosaicos no topo são o seu funil e o seu filtro ao mesmo tempo. Cada número mostra onde as famílias chegaram, e tocar num mosaico reduz a lista a essa fase — potenciais clientes, convidados, clientes e repetentes.", "Las tarjetas de arriba son tu embudo y tu filtro a la vez. Cada cifra muestra hasta dónde han llegado las familias, y al tocar una tarjeta la lista se limita a esa fase: contactos, invitados, clientes y repetidores.", "Les tuiles en haut sont à la fois votre entonnoir et votre filtre. Chaque chiffre montre où en sont les familles, et toucher une tuile réduit la liste à cette étape — prospects, invités, clients et habitués.", "Mae'r teils ar draws y brig yn twndis ac yn hidlydd i chi ar unwaith. Mae pob cyfrif yn dangos ble mae teuluoedd wedi cyrraedd, ac mae tapio teil yn cyfyngu'r rhestr i'r cam hwnnw — ymholiadau, gwahoddedig, cwsmeriaid ac ailadroddwyr."],
  "lt_customers_s2": ["Two shortcuts sit up here. Import bulk-adds families from a spreadsheet and can invite them in one go, and Export pulls any slice of your list — your pick of families, columns and format. These show only for you, never for staff, who see the page read-only.", "Są tu dwa skróty. Import dodaje rodziny hurtowo z arkusza kalkulacyjnego i może od razu je zaprosić, a Eksport wyciąga dowolny wycinek listy — wybierasz rodziny, kolumny i format. Widzisz je tylko Ty, nigdy personel, który ma tę stronę tylko do odczytu.", "Sus sunt două scurtături. Importul adaugă familii în masă dintr-o foaie de calcul și le poate invita dintr-o dată, iar Exportul extrage orice porțiune din listă — alegi familiile, coloanele și formatul. Apar doar pentru tine, niciodată pentru personal, care vede pagina doar în citire.", "یہاں اوپر دو شارٹ کٹ ہیں۔ امپورٹ اسپریڈشیٹ سے ایک ساتھ بہت سے خاندان شامل کرتا ہے اور انہیں ایک ہی بار مدعو بھی کر سکتا ہے، اور ایکسپورٹ آپ کی فہرست کا کوئی بھی حصہ نکالتا ہے — خاندان، کالم اور فارمیٹ آپ کی پسند کے۔ یہ صرف آپ کو نظر آتے ہیں، عملے کو کبھی نہیں، جو صفحہ صرف پڑھ سکتے ہیں۔", "ਇੱਥੇ ਉੱਪਰ ਦੋ ਸ਼ਾਰਟਕੱਟ ਹਨ। ਇੰਪੋਰਟ ਸਪ੍ਰੈਡਸ਼ੀਟ ਤੋਂ ਕਈ ਪਰਿਵਾਰ ਇਕੱਠੇ ਜੋੜਦਾ ਹੈ ਅਤੇ ਉਨ੍ਹਾਂ ਨੂੰ ਇੱਕੋ ਵਾਰ ਸੱਦਾ ਵੀ ਦੇ ਸਕਦਾ ਹੈ, ਅਤੇ ਐਕਸਪੋਰਟ ਤੁਹਾਡੀ ਸੂਚੀ ਦਾ ਕੋਈ ਵੀ ਹਿੱਸਾ ਕੱਢਦਾ ਹੈ — ਪਰਿਵਾਰ, ਕਾਲਮ ਅਤੇ ਫਾਰਮੈਟ ਤੁਹਾਡੀ ਮਰਜ਼ੀ ਦੇ। ਇਹ ਸਿਰਫ਼ ਤੁਹਾਨੂੰ ਦਿਸਦੇ ਹਨ, ਸਟਾਫ਼ ਨੂੰ ਕਦੇ ਨਹੀਂ, ਜੋ ਪੰਨਾ ਸਿਰਫ਼ ਪੜ੍ਹ ਸਕਦੇ ਹਨ।", "এখানে ওপরে দুটি শর্টকাট আছে। ইমপোর্ট স্প্রেডশিট থেকে একসঙ্গে অনেক পরিবার যোগ করে এবং একবারেই আমন্ত্রণও পাঠাতে পারে, আর এক্সপোর্ট আপনার তালিকার যেকোনো অংশ বের করে আনে — আপনার পছন্দের পরিবার, কলাম ও ফরম্যাটে। এগুলো শুধু আপনিই দেখতে পান, কর্মীরা কখনও নয়, তারা পেজটি শুধু পড়তে পারে।", "هنا في الأعلى اختصاران. «استيراد» يضيف عائلات دفعة واحدة من جدول بيانات ويمكنه دعوتها مرة واحدة، و«تصدير» يستخرج أي جزء من قائمتك — حسب اختيارك للعائلات والأعمدة والصيغة. يظهران لك وحدك، وليس للموظفين الذين يرون الصفحة للقراءة فقط.", "Há aqui dois atalhos. Importar adiciona famílias em massa a partir de uma folha de cálculo e pode convidá-las de uma só vez, e Exportar extrai qualquer parte da sua lista — à sua escolha de famílias, colunas e formato. Só aparecem para si, nunca para a equipa, que vê a página apenas em leitura.", "Aquí arriba hay dos atajos. Importar añade familias en bloque desde una hoja de cálculo y puede invitarlas de una vez, y Exportar extrae cualquier parte de tu lista, con las familias, columnas y formato que elijas. Solo los ves tú, nunca el personal, que ve la página en modo de solo lectura.", "Deux raccourcis se trouvent ici. Importer ajoute des familles en masse depuis un tableur et peut les inviter d'un coup, et Exporter extrait n'importe quelle partie de votre liste — familles, colonnes et format à votre choix. Ils n'apparaissent que pour vous, jamais pour le personnel, qui voit la page en lecture seule.", "Mae dwy ffordd gyflym yma. Mae Mewnforio yn ychwanegu teuluoedd mewn swmp o daenlen a gall eu gwahodd i gyd ar unwaith, ac mae Allforio yn tynnu unrhyw ran o'ch rhestr — eich dewis chi o deuluoedd, colofnau a fformat. Dim ond chi sy'n eu gweld, byth staff, sy'n gweld y dudalen yn ddarllen-yn-unig."],
  "lt_customers_s3": ["For the manual cases — say a parent rings up — you press Add family, and this form opens.", "W przypadkach ręcznych — na przykład gdy zadzwoni rodzic — naciskasz Dodaj rodzinę i otwiera się ten formularz.", "Pentru cazurile manuale — de pildă când sună un părinte — apeși Adaugă familie și se deschide acest formular.", "دستی صورتوں کے لیے — مثلاً جب کوئی والدین فون کریں — آپ «خاندان شامل کریں» دباتے ہیں، اور یہ فارم کھل جاتا ہے۔", "ਹੱਥੀਂ ਕੇਸਾਂ ਲਈ — ਜਿਵੇਂ ਕੋਈ ਮਾਪੇ ਫ਼ੋਨ ਕਰਨ — ਤੁਸੀਂ «ਪਰਿਵਾਰ ਜੋੜੋ» ਦਬਾਉਂਦੇ ਹੋ, ਅਤੇ ਇਹ ਫਾਰਮ ਖੁੱਲ੍ਹ ਜਾਂਦਾ ਹੈ।", "হাতে করা ক্ষেত্রগুলোর জন্য — ধরুন কোনো অভিভাবক ফোন করলেন — আপনি «পরিবার যোগ করুন» চাপেন, আর এই ফর্মটি খুলে যায়।", "في الحالات اليدوية — كأن يتصل أحد الوالدين مثلًا — تضغط على «إضافة عائلة» فيُفتح هذا النموذج.", "Nos casos manuais — por exemplo, quando um pai ou uma mãe telefona — prime Adicionar família e este formulário abre-se.", "Para los casos manuales, por ejemplo cuando llama un padre o una madre, pulsas Añadir familia y se abre este formulario.", "Pour les cas manuels — par exemple quand un parent appelle — vous appuyez sur Ajouter une famille et ce formulaire s'ouvre.", "Ar gyfer yr achosion â llaw — dyweder bod rhiant yn ffonio — pwyswch Ychwanegu teulu ac mae'r ffurflen hon yn agor."],
  "lt_customers_s4": ["Pop the parent's details straight in — first name, surname, email, and a phone number if they gave one.", "Wpisz od razu dane rodzica — imię, nazwisko, e-mail i numer telefonu, jeśli go podał.", "Introdu direct datele părintelui — prenumele, numele, e-mailul și un număr de telefon, dacă l-a dat.", "والدین کی تفصیلات سیدھی ڈال دیں — پہلا نام، آخری نام، ای میل، اور اگر انہوں نے فون نمبر دیا ہو تو وہ بھی۔", "ਮਾਪਿਆਂ ਦੇ ਵੇਰਵੇ ਸਿੱਧੇ ਪਾ ਦਿਓ — ਪਹਿਲਾ ਨਾਂ, ਸਰਨੇਮ, ਈਮੇਲ, ਅਤੇ ਜੇ ਉਨ੍ਹਾਂ ਨੇ ਦਿੱਤਾ ਹੋਵੇ ਤਾਂ ਫ਼ੋਨ ਨੰਬਰ।", "অভিভাবকের তথ্য সরাসরি লিখে ফেলুন — নাম, পদবি, ইমেইল, আর ফোন নম্বর দিলে সেটিও।", "أدخل بيانات ولي الأمر مباشرة — الاسم الأول واسم العائلة والبريد الإلكتروني، ورقم الهاتف إن أعطاه.", "Introduza logo os dados do pai ou da mãe — nome, apelido, e-mail e um número de telefone, se o tiver dado.", "Introduce directamente los datos del padre o la madre: nombre, apellidos, correo y un teléfono si lo ha dado.", "Saisissez directement les coordonnées du parent — prénom, nom, e-mail, et un numéro de téléphone s'il en a donné un.", "Rhowch fanylion y rhiant i mewn yn syth — enw cyntaf, cyfenw, e-bost, a rhif ffôn os rhoddon nhw un."],
  "lt_customers_s5": ["Jot down what they told you in the notes. Only your team ever sees this, never the family — so the camp and club they asked about, the children's ages, and the site they want all live here for when you follow up.", "Zapisz w notatkach to, co Ci powiedzieli. Widzi je tylko Twój zespół, nigdy rodzina — więc obóz i kółko, o które pytali, wiek dzieci i wybrane miejsce znajdują się tutaj, na czas, gdy będziesz się z nimi kontaktować.", "Notează în observații ce ți-au spus. Le vede doar echipa ta, niciodată familia — așa că tabăra și clubul despre care au întrebat, vârstele copiilor și locația dorită stau toate aici, pentru când revii la ei.", "جو کچھ انہوں نے بتایا وہ نوٹس میں لکھ لیں۔ اسے صرف آپ کی ٹیم دیکھتی ہے، خاندان کبھی نہیں — اس لیے جس کیمپ اور کلب کے بارے میں پوچھا، بچوں کی عمریں اور مطلوبہ جگہ سب یہیں رہتے ہیں، تاکہ فالو اپ کے وقت کام آئیں۔", "ਜੋ ਕੁਝ ਉਨ੍ਹਾਂ ਨੇ ਦੱਸਿਆ ਉਹ ਨੋਟਸ ਵਿੱਚ ਲਿਖ ਲਓ। ਇਹ ਸਿਰਫ਼ ਤੁਹਾਡੀ ਟੀਮ ਵੇਖਦੀ ਹੈ, ਪਰਿਵਾਰ ਕਦੇ ਨਹੀਂ — ਇਸ ਲਈ ਜਿਸ ਕੈਂਪ ਅਤੇ ਕਲੱਬ ਬਾਰੇ ਪੁੱਛਿਆ, ਬੱਚਿਆਂ ਦੀ ਉਮਰ ਅਤੇ ਚਾਹੀਦੀ ਥਾਂ ਸਭ ਇੱਥੇ ਹੀ ਰਹਿੰਦੇ ਹਨ, ਤਾਂ ਜੋ ਫਾਲੋ-ਅੱਪ ਵੇਲੇ ਕੰਮ ਆਉਣ।", "তাঁরা যা বলেছেন তা নোটে লিখে রাখুন। এটি শুধু আপনার টিম দেখে, পরিবার কখনও নয় — তাই যে ক্যাম্প ও ক্লাবের কথা জিজ্ঞেস করেছেন, শিশুদের বয়স আর কোন জায়গা চান, সবই এখানে থাকে, পরে যোগাযোগের সময় কাজে লাগবে।", "دوِّن ما أخبروك به في الملاحظات. لا يراها سوى فريقك، ولا تراها العائلة أبدًا — فالمخيم والنادي اللذان سألوا عنهما وأعمار الأطفال والموقع المطلوب كلها تُحفَظ هنا لحين المتابعة.", "Anote nas notas o que lhe disseram. Só a sua equipa vê isto, nunca a família — por isso o campo e o clube por que perguntaram, as idades das crianças e o local que querem ficam aqui, para quando voltar a contactá-los.", "Anota en las notas lo que te han dicho. Solo lo ve tu equipo, nunca la familia, así que el campamento y el club por los que preguntaron, las edades de los niños y la sede que quieren quedan aquí para cuando les hagas seguimiento.", "Notez dans les notes ce qu'ils vous ont dit. Seule votre équipe le voit, jamais la famille — le camp et le club demandés, l'âge des enfants et le site souhaité restent donc ici pour le moment où vous les recontactez.", "Nodwch yn y nodiadau yr hyn a ddywedon nhw wrthych. Dim ond eich tîm sy'n gweld hyn, byth y teulu — felly mae'r gwersyll a'r clwb y gofynnon nhw amdanynt, oedrannau'r plant a'r safle maen nhw ei eisiau i gyd yma ar gyfer pan fyddwch chi'n dilyn i fyny."],
  "lt_customers_s6": ["Only tick this if they actually agreed on the call. Marketing email without consent is unlawful, and this box is your record that they said yes.", "Zaznacz to tylko wtedy, gdy naprawdę się zgodzili podczas rozmowy. Marketing e-mailowy bez zgody jest niezgodny z prawem, a to pole jest Twoim zapisem, że powiedzieli „tak”.", "Bifează doar dacă au fost într-adevăr de acord la telefon. Marketingul prin e-mail fără consimțământ este ilegal, iar această casetă este dovada ta că au spus da.", "اسے صرف تب ٹک کریں جب وہ واقعی کال پر راضی ہوئے ہوں۔ رضامندی کے بغیر مارکیٹنگ ای میل غیر قانونی ہے، اور یہ خانہ اس بات کا آپ کا ریکارڈ ہے کہ انہوں نے ہاں کہا۔", "ਇਸ ਨੂੰ ਸਿਰਫ਼ ਓਦੋਂ ਟਿੱਕ ਕਰੋ ਜਦੋਂ ਉਹ ਸੱਚਮੁੱਚ ਕਾਲ ਉੱਤੇ ਸਹਿਮਤ ਹੋਏ ਹੋਣ। ਸਹਿਮਤੀ ਤੋਂ ਬਿਨਾਂ ਮਾਰਕੀਟਿੰਗ ਈਮੇਲ ਗੈਰ-ਕਾਨੂੰਨੀ ਹੈ, ਅਤੇ ਇਹ ਡੱਬਾ ਇਸ ਗੱਲ ਦਾ ਤੁਹਾਡਾ ਰਿਕਾਰਡ ਹੈ ਕਿ ਉਨ੍ਹਾਂ ਨੇ ਹਾਂ ਕਿਹਾ।", "এটিতে টিক দিন কেবল তখনই যখন তাঁরা সত্যিই ফোনে রাজি হয়েছেন। সম্মতি ছাড়া মার্কেটিং ইমেইল পাঠানো বেআইনি, আর এই বাক্সটি হলো তাঁরা হ্যাঁ বলেছেন তার আপনার রেকর্ড।", "ضع علامة هنا فقط إن وافقوا فعلًا أثناء المكالمة. إرسال بريد تسويقي دون موافقة أمر غير قانوني، وهذا المربع هو سجلّك بأنهم قالوا نعم.", "Só assinale se eles realmente concordaram na chamada. O marketing por e-mail sem consentimento é ilegal, e esta caixa é o seu registo de que disseram que sim.", "Márcalo solo si realmente aceptaron en la llamada. El marketing por correo sin consentimiento es ilegal, y esta casilla es tu registro de que dijeron que sí.", "Ne cochez cette case que s'ils ont vraiment donné leur accord pendant l'appel. L'e-mail marketing sans consentement est illégal, et cette case est la preuve qu'ils ont dit oui.", "Ticiwch hwn dim ond os gwnaethon nhw gytuno ar yr alwad mewn gwirionedd. Mae e-bost marchnata heb gydsyniad yn anghyfreithlon, a'r blwch hwn yw eich cofnod eu bod wedi dweud ie."],
  "lt_customers_s7": ["Press Save and send sign-up link and it does both at once — files the family and emails them a link to set a password and land in their own area, where they add their own children. Plain Save just files them without the email.", "Naciśnięcie Zapisz i wyślij link rejestracyjny robi obie rzeczy naraz — zapisuje rodzinę i wysyła jej e-mailem link do ustawienia hasła i wejścia do własnego panelu, gdzie sama doda swoje dzieci. Zwykłe Zapisz tylko zapisuje rodzinę, bez e-maila.", "Apăsarea pe Salvează și trimite linkul de înscriere face ambele lucruri deodată — înregistrează familia și îi trimite prin e-mail un link pentru a seta o parolă și a intra în propria zonă, unde își adaugă singură copiii. Simplul Salvează doar înregistrează familia, fără e-mail.", "«محفوظ کریں اور سائن اپ لنک بھیجیں» دبانے سے دونوں کام ایک ساتھ ہو جاتے ہیں — خاندان محفوظ ہو جاتا ہے اور انہیں ای میل پر ایک لنک جاتا ہے جس سے وہ پاس ورڈ بنا کر اپنے حصے میں آ جاتے ہیں، جہاں وہ اپنے بچے خود شامل کرتے ہیں۔ عام «محفوظ کریں» صرف خاندان کو محفوظ کرتا ہے، ای میل کے بغیر۔", "«ਸੰਭਾਲੋ ਅਤੇ ਸਾਈਨ-ਅੱਪ ਲਿੰਕ ਭੇਜੋ» ਦਬਾਉਣ ਨਾਲ ਦੋਵੇਂ ਕੰਮ ਇਕੱਠੇ ਹੋ ਜਾਂਦੇ ਹਨ — ਪਰਿਵਾਰ ਸੰਭਾਲਿਆ ਜਾਂਦਾ ਹੈ ਅਤੇ ਉਨ੍ਹਾਂ ਨੂੰ ਪਾਸਵਰਡ ਬਣਾ ਕੇ ਆਪਣੇ ਖੇਤਰ ਵਿੱਚ ਆਉਣ ਲਈ ਲਿੰਕ ਈਮੇਲ ਹੁੰਦਾ ਹੈ, ਜਿੱਥੇ ਉਹ ਆਪਣੇ ਬੱਚੇ ਆਪ ਜੋੜਦੇ ਹਨ। ਸਾਧਾਰਨ «ਸੰਭਾਲੋ» ਸਿਰਫ਼ ਪਰਿਵਾਰ ਨੂੰ ਸੰਭਾਲਦਾ ਹੈ, ਈਮੇਲ ਤੋਂ ਬਿਨਾਂ।", "«সেভ করুন ও সাইন-আপ লিংক পাঠান» চাপলে দুটো কাজ একসঙ্গে হয় — পরিবারটি সংরক্ষিত হয় এবং তাঁদের ইমেইলে একটি লিংক যায়, যা দিয়ে পাসওয়ার্ড বানিয়ে নিজেদের এলাকায় ঢোকা যায়, যেখানে তাঁরা নিজেরাই সন্তানদের যোগ করেন। সাধারণ «সেভ করুন» শুধু পরিবারটিকে সংরক্ষণ করে, ইমেইল ছাড়া।", "الضغط على «حفظ وإرسال رابط التسجيل» يفعل الأمرين معًا — يحفظ العائلة ويرسل لها رابطًا بالبريد لتعيين كلمة مرور والدخول إلى منطقتها الخاصة، حيث تضيف أطفالها بنفسها. أما «حفظ» العادية فتحفظ العائلة فقط دون بريد.", "Premir Guardar e enviar ligação de registo faz as duas coisas de uma vez — guarda a família e envia-lhe por e-mail uma ligação para definir uma palavra-passe e entrar na sua própria área, onde acrescenta os seus filhos. O simples Guardar apenas guarda a família, sem e-mail.", "Al pulsar Guardar y enviar enlace de registro se hacen ambas cosas a la vez: se guarda a la familia y se le envía por correo un enlace para crear una contraseña y entrar en su propia zona, donde añade a sus hijos. El simple Guardar solo archiva a la familia, sin correo.", "Appuyer sur Enregistrer et envoyer le lien d'inscription fait les deux à la fois : la famille est enregistrée et reçoit par e-mail un lien pour créer un mot de passe et accéder à son propre espace, où elle ajoute ses enfants. Un simple Enregistrer classe juste la famille, sans e-mail.", "Mae pwyso Cadw ac anfon dolen cofrestru yn gwneud y ddau ar unwaith — mae'n cofnodi'r teulu ac yn anfon dolen atyn nhw drwy e-bost i osod cyfrinair a mynd i'w hardal eu hunain, lle maen nhw'n ychwanegu eu plant eu hunain. Mae Cadw syml yn cofnodi'r teulu yn unig, heb e-bost."],
  "lt_email_title": ["Email", "E-mail", "E-mail", "ای میل", "ਈਮੇਲ", "ইমেইল", "البريد الإلكتروني", "E-mail", "Correo electrónico", "E-mail", "E-bost"],
  "lt_email_intro": ["This is your whole comms hub — a Gmail-style inbox and composer for writing to parents one-to-one, a marketing pipeline for branded campaigns to your live audiences, and the automatic emails {brand} sends for you.", "To całe Twoje centrum komunikacji — skrzynka odbiorcza i edytor w stylu Gmaila do pisania do rodziców indywidualnie, lejek marketingowy do kampanii z Twoją marką dla aktywnych odbiorców oraz automatyczne e-maile, które {brand} wysyła za Ciebie.", "Acesta este întregul tău centru de comunicare — o căsuță de e-mail în stil Gmail și un editor pentru a scrie părinților individual, un circuit de marketing pentru campanii cu marca ta către audiențele tale active și e-mailurile automate pe care {brand} le trimite în locul tău.", "یہ آپ کا مکمل مواصلاتی مرکز ہے — والدین کو انفرادی طور پر لکھنے کے لیے جی میل جیسا ان باکس اور کمپوزر، آپ کے فعال سامعین کو برانڈڈ مہمیں بھیجنے کی مارکیٹنگ پائپ لائن، اور وہ خودکار ای میلز جو {brand} آپ کی طرف سے بھیجتا ہے۔", "ਇਹ ਤੁਹਾਡਾ ਪੂਰਾ ਸੰਚਾਰ ਕੇਂਦਰ ਹੈ — ਮਾਪਿਆਂ ਨੂੰ ਇੱਕ-ਇੱਕ ਕਰਕੇ ਲਿਖਣ ਲਈ ਜੀਮੇਲ ਵਰਗਾ ਇਨਬਾਕਸ ਅਤੇ ਕੰਪੋਜ਼ਰ, ਤੁਹਾਡੇ ਸਰਗਰਮ ਦਰਸ਼ਕਾਂ ਨੂੰ ਬ੍ਰਾਂਡ ਵਾਲੀਆਂ ਮੁਹਿੰਮਾਂ ਭੇਜਣ ਲਈ ਮਾਰਕੀਟਿੰਗ ਪਾਈਪਲਾਈਨ, ਅਤੇ ਉਹ ਆਟੋਮੈਟਿਕ ਈਮੇਲਾਂ ਜੋ {brand} ਤੁਹਾਡੇ ਵੱਲੋਂ ਭੇਜਦਾ ਹੈ।", "এটি আপনার পুরো যোগাযোগ কেন্দ্র — অভিভাবকদের আলাদা করে লেখার জন্য জিমেইলের মতো ইনবক্স ও কম্পোজার, আপনার সক্রিয় শ্রোতাদের ব্র্যান্ডেড ক্যাম্পেইন পাঠানোর মার্কেটিং পাইপলাইন, এবং {brand} আপনার হয়ে যে স্বয়ংক্রিয় ইমেইলগুলো পাঠায়।", "هذا هو مركز التواصل بالكامل — صندوق وارد ومحرّر بأسلوب جيميل للكتابة إلى أولياء الأمور فرديًا، ومسار تسويقي لحملات بعلامتك إلى جمهورك النشط، والرسائل التلقائية التي يرسلها {brand} نيابةً عنك.", "Este é todo o seu centro de comunicações — uma caixa de entrada e um editor ao estilo do Gmail para escrever aos pais individualmente, um funil de marketing para campanhas com a sua marca aos seus públicos ativos e os e-mails automáticos que o {brand} envia por si.", "Este es todo tu centro de comunicaciones: una bandeja de entrada y un redactor al estilo Gmail para escribir a los padres uno a uno, un canal de marketing para campañas con tu marca a tus audiencias activas y los correos automáticos que {brand} envía por ti.", "C'est tout votre centre de communication — une boîte de réception et un éditeur façon Gmail pour écrire aux parents un par un, un circuit marketing pour des campagnes à votre image auprès de vos audiences actives, et les e-mails automatiques que {brand} envoie pour vous.", "Dyma'ch canolfan gyfathrebu gyfan — mewnflwch a golygydd tebyg i Gmail i ysgrifennu at rieni fesul un, piblinell farchnata ar gyfer ymgyrchoedd wedi'u brandio i'ch cynulleidfaoedd byw, a'r e-byst awtomatig y mae {brand} yn eu hanfon ar eich rhan."],
  "lt_email_done": ["Write to parents from the Inbox, fire branded campaigns at your live audiences, let {brand} send the routine emails for you, and read the numbers to see what's landing.", "Pisz do rodziców ze Skrzynki odbiorczej, wysyłaj kampanie z Twoją marką do aktywnych odbiorców, pozwól {brand} wysyłać rutynowe e-maile za Ciebie i czytaj statystyki, żeby widzieć, co trafia w punkt.", "Scrie părinților din Inbox, trimite campanii cu marca ta către audiențele active, lasă {brand} să trimită în locul tău e-mailurile de rutină și citește cifrele ca să vezi ce funcționează.", "ان باکس سے والدین کو لکھیں، اپنے فعال سامعین کو برانڈڈ مہمیں بھیجیں، معمول کی ای میلز {brand} کو بھیجنے دیں، اور اعداد و شمار پڑھ کر دیکھیں کہ کیا اثر کر رہا ہے۔", "ਇਨਬਾਕਸ ਤੋਂ ਮਾਪਿਆਂ ਨੂੰ ਲਿਖੋ, ਆਪਣੇ ਸਰਗਰਮ ਦਰਸ਼ਕਾਂ ਨੂੰ ਬ੍ਰਾਂਡ ਵਾਲੀਆਂ ਮੁਹਿੰਮਾਂ ਭੇਜੋ, ਰੁਟੀਨ ਈਮੇਲਾਂ {brand} ਨੂੰ ਭੇਜਣ ਦਿਓ, ਅਤੇ ਅੰਕੜੇ ਪੜ੍ਹ ਕੇ ਵੇਖੋ ਕਿ ਕੀ ਕੰਮ ਕਰ ਰਿਹਾ ਹੈ।", "ইনবক্স থেকে অভিভাবকদের লিখুন, আপনার সক্রিয় শ্রোতাদের ব্র্যান্ডেড ক্যাম্পেইন পাঠান, নিয়মিত ইমেইলগুলো {brand}-কে পাঠাতে দিন, আর সংখ্যাগুলো দেখে বুঝে নিন কোনটা কাজ করছে।", "اكتب إلى أولياء الأمور من صندوق الوارد، وأطلق حملات بعلامتك إلى جمهورك النشط، ودع {brand} يرسل الرسائل الروتينية عنك، واقرأ الأرقام لترى ما الذي يحقق نتيجة.", "Escreva aos pais a partir da Caixa de entrada, lance campanhas com a sua marca aos seus públicos ativos, deixe o {brand} enviar os e-mails de rotina por si e leia os números para ver o que está a resultar.", "Escribe a los padres desde la Bandeja de entrada, lanza campañas con tu marca a tus audiencias activas, deja que {brand} envíe los correos rutinarios por ti y consulta las cifras para ver qué está funcionando.", "Écrivez aux parents depuis la Boîte de réception, lancez des campagnes à votre image auprès de vos audiences actives, laissez {brand} envoyer les e-mails de routine pour vous et lisez les chiffres pour voir ce qui fonctionne.", "Ysgrifennwch at rieni o'r Mewnflwch, anfonwch ymgyrchoedd wedi'u brandio at eich cynulleidfaoedd byw, gadewch i {brand} anfon yr e-byst arferol ar eich rhan, a darllenwch y ffigurau i weld beth sy'n gweithio."],
  "lt_email_s0": ["Everything on this page lives under a row of eight tabs — the first two are your one-to-one mailbox and writing desk, the middle three run your bulk marketing, and the last three are the emails {brand} sends automatically plus your settings.", "Wszystko na tej stronie mieści się w rzędzie ośmiu kart — pierwsze dwie to Twoja skrzynka do indywidualnej korespondencji i biurko do pisania, trzy środkowe obsługują masowy marketing, a ostatnie trzy to e-maile wysyłane automatycznie przez {brand} oraz Twoje ustawienia.", "Tot ce e pe această pagină se află sub un rând de opt file — primele două sunt căsuța ta pentru mesaje individuale și biroul de scris, cele trei din mijloc gestionează marketingul în masă, iar ultimele trei sunt e-mailurile trimise automat de {brand} plus setările tale.", "اس صفحے پر ہر چیز آٹھ ٹیبز کی ایک قطار کے نیچے ہے — پہلے دو آپ کا انفرادی میل باکس اور لکھنے کی میز ہیں، درمیان کے تین آپ کی بڑی مارکیٹنگ چلاتے ہیں، اور آخری تین وہ ای میلز ہیں جو {brand} خود بخود بھیجتا ہے اور آپ کی ترتیبات۔", "ਇਸ ਪੰਨੇ ਉੱਤੇ ਹਰ ਚੀਜ਼ ਅੱਠ ਟੈਬਾਂ ਦੀ ਇੱਕ ਕਤਾਰ ਹੇਠ ਹੈ — ਪਹਿਲੇ ਦੋ ਤੁਹਾਡਾ ਇੱਕ-ਇੱਕ ਕਰਕੇ ਮੇਲਬਾਕਸ ਅਤੇ ਲਿਖਣ ਵਾਲੀ ਮੇਜ਼ ਹਨ, ਵਿਚਕਾਰਲੇ ਤਿੰਨ ਤੁਹਾਡੀ ਵੱਡੀ ਮਾਰਕੀਟਿੰਗ ਚਲਾਉਂਦੇ ਹਨ, ਅਤੇ ਆਖਰੀ ਤਿੰਨ ਉਹ ਈਮੇਲਾਂ ਹਨ ਜੋ {brand} ਆਪਣੇ-ਆਪ ਭੇਜਦਾ ਹੈ ਅਤੇ ਤੁਹਾਡੀਆਂ ਸੈਟਿੰਗਾਂ।", "এই পেজের সবকিছু আটটি ট্যাবের একটি সারিতে আছে — প্রথম দুটি আপনার একে একে লেখার মেইলবক্স ও লেখার টেবিল, মাঝের তিনটি আপনার বাল্ক মার্কেটিং চালায়, আর শেষ তিনটি {brand} স্বয়ংক্রিয়ভাবে যে ইমেইল পাঠায় সেগুলো এবং আপনার সেটিংস।", "كل ما في هذه الصفحة موزّع على صف من ثمانية تبويبات — الأولان صندوق بريدك الفردي ومكتب الكتابة، والثلاثة الأوسط تدير تسويقك الجماعي، والثلاثة الأخيرة هي الرسائل التي يرسلها {brand} تلقائيًا إضافةً إلى إعداداتك.", "Tudo nesta página está sob uma fila de oito separadores — os dois primeiros são a sua caixa de correio individual e a mesa de escrita, os três do meio gerem o seu marketing em massa e os últimos três são os e-mails que o {brand} envia automaticamente, mais as suas definições.", "Todo lo de esta página está bajo una fila de ocho pestañas: las dos primeras son tu buzón uno a uno y tu mesa de redacción, las tres del medio gestionan tu marketing masivo y las tres últimas son los correos que {brand} envía automáticamente y tus ajustes.", "Tout sur cette page se trouve sous une rangée de huit onglets — les deux premiers sont votre boîte aux lettres en tête-à-tête et votre bureau de rédaction, les trois du milieu gèrent votre marketing de masse, et les trois derniers sont les e-mails que {brand} envoie automatiquement plus vos réglages.", "Mae popeth ar y dudalen hon o dan res o wyth tab — y ddau gyntaf yw eich blwch post un-i-un a'ch desg ysgrifennu, mae'r tri yn y canol yn rhedeg eich marchnata swmp, a'r tri olaf yw'r e-byst y mae {brand} yn eu hanfon yn awtomatig ynghyd â'ch gosodiadau."],
  "lt_email_s1": ["These aren't fixed lists — each is a live rule that recounts from your bookings every send, with opt-outs always left out; they split into your booked parents and your enquiries, interested folk who've yet to book.", "To nie są stałe listy — każda jest żywą regułą, która przelicza się z Twoich rezerwacji przy każdej wysyłce, z zawsze pominiętymi osobami, które zrezygnowały; dzielą się na rodziców z rezerwacją i zapytania, czyli zainteresowanych, którzy jeszcze nie zarezerwowali.", "Acestea nu sunt liste fixe — fiecare este o regulă vie care se recalculează din rezervările tale la fiecare trimitere, cu excluderea mereu a celor care s-au dezabonat; se împart în părinții cu rezervare și solicitările tale, adică persoane interesate care nu au rezervat încă.", "یہ مقررہ فہرستیں نہیں ہیں — ہر ایک ایک زندہ اصول ہے جو ہر بار بھیجنے پر آپ کی بکنگز سے دوبارہ گنتا ہے، اور اجتماعی رکنیت ختم کرنے والے ہمیشہ خارج رہتے ہیں؛ یہ آپ کے بکنگ کروانے والے والدین اور آپ کی پوچھ گچھ میں تقسیم ہیں، یعنی دلچسپی رکھنے والے لوگ جنہوں نے ابھی بکنگ نہیں کی۔", "ਇਹ ਪੱਕੀਆਂ ਸੂਚੀਆਂ ਨਹੀਂ ਹਨ — ਹਰ ਇੱਕ ਜੀਵਤ ਨਿਯਮ ਹੈ ਜੋ ਹਰ ਵਾਰ ਭੇਜਣ ਸਮੇਂ ਤੁਹਾਡੀਆਂ ਬੁਕਿੰਗਾਂ ਤੋਂ ਦੁਬਾਰਾ ਗਿਣਦਾ ਹੈ, ਅਤੇ ਬਾਹਰ ਨਿਕਲਣ ਵਾਲੇ ਹਮੇਸ਼ਾ ਛੱਡ ਦਿੱਤੇ ਜਾਂਦੇ ਹਨ; ਇਹ ਤੁਹਾਡੇ ਬੁਕਿੰਗ ਕਰਨ ਵਾਲੇ ਮਾਪਿਆਂ ਅਤੇ ਤੁਹਾਡੀਆਂ ਪੁੱਛਗਿੱਛਾਂ ਵਿੱਚ ਵੰਡੀਆਂ ਹਨ, ਯਾਨੀ ਦਿਲਚਸਪੀ ਰੱਖਣ ਵਾਲੇ ਲੋਕ ਜਿਨ੍ਹਾਂ ਨੇ ਅਜੇ ਬੁਕਿੰਗ ਨਹੀਂ ਕੀਤੀ।", "এগুলো স্থির তালিকা নয় — প্রতিটি একটি জীবন্ত নিয়ম, যা প্রতিবার পাঠানোর সময় আপনার বুকিং থেকে আবার গুনে নেয়, আর যারা অপ্ট-আউট করেছেন তাঁরা সবসময় বাদ থাকেন; এগুলো ভাগ হয় আপনার বুকিং করা অভিভাবক ও আপনার জিজ্ঞাসাকারীদের মধ্যে, অর্থাৎ আগ্রহী মানুষ যাঁরা এখনও বুকিং করেননি।", "هذه ليست قوائم ثابتة — كل منها قاعدة حيّة يُعاد احتسابها من حجوزاتك عند كل إرسال، مع استبعاد من ألغوا اشتراكهم دائمًا؛ وهي تنقسم إلى أولياء الأمور الذين حجزوا والمستفسرين، أي المهتمين الذين لم يحجزوا بعد.", "Estas não são listas fixas — cada uma é uma regra viva que volta a contar a partir das suas reservas a cada envio, deixando sempre de fora quem cancelou a subscrição; dividem-se nos seus pais com reserva e nos seus contactos, pessoas interessadas que ainda não reservaram.", "No son listas fijas: cada una es una regla viva que se recalcula a partir de tus reservas en cada envío, dejando siempre fuera a quienes se han dado de baja; se dividen en tus padres con reserva y tus consultas, personas interesadas que aún no han reservado.", "Ce ne sont pas des listes figées — chacune est une règle vivante qui se recalcule à partir de vos réservations à chaque envoi, en excluant toujours les désabonnés ; elles se répartissent entre vos parents ayant réservé et vos demandes, des personnes intéressées qui n'ont pas encore réservé.", "Nid rhestrau sefydlog yw'r rhain — mae pob un yn rheol fyw sy'n ailgyfrif o'ch archebion ar bob anfon, gyda'r rhai sydd wedi dewis peidio bob amser yn cael eu gadael allan; maen nhw'n rhannu'n rhieni sydd wedi archebu a'ch ymholiadau, pobl â diddordeb nad ydyn nhw wedi archebu eto."],
  "lt_email_s2": ["Beyond what you write, {brand} quietly sends a batch on your behalf — booking confirmations, receipts, session reminders, late-collection alerts and review requests — and this tab is where you switch any off or change when the reminders go out.", "Oprócz tego, co piszesz sam, {brand} po cichu wysyła za Ciebie całą paczkę — potwierdzenia rezerwacji, rachunki, przypomnienia o zajęciach, alerty o spóźnionym odbiorze i prośby o opinię — a ta karta służy do wyłączania dowolnego z nich lub zmiany terminu przypomnień.", "Pe lângă ce scrii tu, {brand} trimite discret un lot întreg în numele tău — confirmări de rezervare, chitanțe, mementouri pentru sesiuni, alerte de preluare întârziată și solicitări de recenzii — iar această filă este locul unde oprești oricare dintre ele sau schimbi când pleacă mementourile.", "آپ جو خود لکھتے ہیں اس کے علاوہ، {brand} آپ کی طرف سے خاموشی سے ایک پورا بیچ بھیجتا ہے — بکنگ کی تصدیقیں، رسیدیں، سیشن کی یاد دہانیاں، دیر سے لینے کے الرٹ اور جائزے کی درخواستیں — اور یہ ٹیب وہ جگہ ہے جہاں آپ کوئی بھی بند کر سکتے ہیں یا یاد دہانیوں کا وقت بدل سکتے ہیں۔", "ਤੁਹਾਡੇ ਆਪ ਲਿਖੇ ਤੋਂ ਇਲਾਵਾ, {brand} ਤੁਹਾਡੇ ਵੱਲੋਂ ਚੁੱਪ-ਚਾਪ ਇੱਕ ਪੂਰਾ ਜੱਥਾ ਭੇਜਦਾ ਹੈ — ਬੁਕਿੰਗ ਦੀ ਪੁਸ਼ਟੀ, ਰਸੀਦਾਂ, ਸੈਸ਼ਨ ਦੀਆਂ ਯਾਦ-ਦਹਾਨੀਆਂ, ਦੇਰ ਨਾਲ ਲੈਣ ਦੇ ਅਲਰਟ ਅਤੇ ਸਮੀਖਿਆ ਦੀਆਂ ਬੇਨਤੀਆਂ — ਅਤੇ ਇਹ ਟੈਬ ਉਹ ਥਾਂ ਹੈ ਜਿੱਥੇ ਤੁਸੀਂ ਕੋਈ ਵੀ ਬੰਦ ਕਰ ਸਕਦੇ ਹੋ ਜਾਂ ਯਾਦ-ਦਹਾਨੀਆਂ ਦਾ ਸਮਾਂ ਬਦਲ ਸਕਦੇ ਹੋ।", "আপনি নিজে যা লেখেন তার বাইরেও, {brand} আপনার হয়ে চুপচাপ একটি পুরো ব্যাচ পাঠায় — বুকিং নিশ্চিতকরণ, রসিদ, সেশনের অনুস্মারক, দেরিতে নেওয়ার সতর্কতা ও রিভিউ অনুরোধ — আর এই ট্যাবে আপনি যেকোনোটি বন্ধ করতে বা অনুস্মারক কখন যাবে তা বদলাতে পারেন।", "إلى جانب ما تكتبه بنفسك، يرسل {brand} بهدوء دفعة كاملة نيابةً عنك — تأكيدات الحجز والإيصالات وتذكيرات الجلسات وتنبيهات الاستلام المتأخر وطلبات التقييم — وهذا التبويب هو المكان الذي توقف فيه أيًّا منها أو تغيّر موعد إرسال التذكيرات.", "Além do que escreve, o {brand} envia discretamente um conjunto inteiro em seu nome — confirmações de reserva, recibos, lembretes de sessão, alertas de recolha tardia e pedidos de avaliação — e este separador é onde desliga qualquer um ou muda quando saem os lembretes.", "Además de lo que escribes tú, {brand} envía discretamente todo un lote en tu nombre (confirmaciones de reserva, recibos, recordatorios de sesión, avisos de recogida tardía y solicitudes de opinión), y esta pestaña es donde desactivas cualquiera o cambias cuándo salen los recordatorios.", "Au-delà de ce que vous écrivez, {brand} envoie discrètement toute une série de messages en votre nom — confirmations de réservation, reçus, rappels de séance, alertes de retard de récupération et demandes d'avis — et cet onglet vous permet d'en désactiver ou de changer le moment d'envoi des rappels.", "Y tu hwnt i'r hyn rydych chi'n ei ysgrifennu, mae {brand} yn anfon swp cyfan yn dawel ar eich rhan — cadarnhadau archebu, derbynebau, nodiadau atgoffa sesiwn, rhybuddion casglu hwyr a cheisiadau am adolygiad — a'r tab hwn yw lle rydych chi'n diffodd unrhyw un neu'n newid pryd mae'r nodiadau atgoffa'n mynd allan."],
  "lt_email_s3": ["To write one yourself, you press Compose, and this composer opens.", "Aby napisać wiadomość samodzielnie, naciskasz Nowa wiadomość i otwiera się ten edytor.", "Pentru a scrie unul singur, apeși Compune și se deschide acest editor.", "خود لکھنے کے لیے آپ «کمپوز» دباتے ہیں، اور یہ کمپوزر کھل جاتا ہے۔", "ਆਪ ਲਿਖਣ ਲਈ ਤੁਸੀਂ «ਕੰਪੋਜ਼» ਦਬਾਉਂਦੇ ਹੋ, ਅਤੇ ਇਹ ਕੰਪੋਜ਼ਰ ਖੁੱਲ੍ਹ ਜਾਂਦਾ ਹੈ।", "নিজে লিখতে আপনি «কম্পোজ» চাপেন, আর এই কম্পোজারটি খুলে যায়।", "لكتابة رسالة بنفسك، تضغط على «إنشاء رسالة» فيُفتح هذا المحرّر.", "Para escrever um e-mail, prime Escrever e este editor abre-se.", "Para escribir uno tú mismo, pulsas Redactar y se abre este editor.", "Pour en écrire un vous-même, vous appuyez sur Rédiger et cet éditeur s'ouvre.", "I ysgrifennu un eich hun, pwyswch Cyfansoddi ac mae'r cyfansoddwr hwn yn agor."],
  "lt_email_s4": ["First, choose who it's going to — all your families, everyone booked on one listing, or, as here, a single address; we'll pop in Sarah's email, since she asked about the August camp.", "Najpierw wybierz odbiorców — wszystkie rodziny, wszystkich zapisanych na jedną ofertę albo, jak tutaj, jeden adres; wpiszemy e-mail Sarah, bo pytała o sierpniowy obóz.", "Mai întâi alege cui îl trimiți — tuturor familiilor, tuturor celor înscriși la o ofertă sau, ca aici, unei singure adrese; vom pune e-mailul Sarei, pentru că a întrebat despre tabăra din august.", "پہلے چنیں کہ یہ کس کو جا رہا ہے — آپ کے تمام خاندان، کسی ایک لسٹنگ پر بکنگ والے سب، یا جیسے یہاں، ایک ہی پتہ؛ ہم سارہ کی ای میل ڈالیں گے، کیونکہ اس نے اگست کے کیمپ کے بارے میں پوچھا تھا۔", "ਪਹਿਲਾਂ ਚੁਣੋ ਕਿ ਇਹ ਕਿਸ ਨੂੰ ਜਾ ਰਿਹਾ ਹੈ — ਤੁਹਾਡੇ ਸਾਰੇ ਪਰਿਵਾਰ, ਇੱਕ ਲਿਸਟਿੰਗ ਉੱਤੇ ਬੁਕ ਹੋਏ ਸਾਰੇ, ਜਾਂ ਜਿਵੇਂ ਇੱਥੇ, ਇੱਕ ਪਤਾ; ਅਸੀਂ ਸਾਰਾਹ ਦੀ ਈਮੇਲ ਪਾਵਾਂਗੇ, ਕਿਉਂਕਿ ਉਸ ਨੇ ਅਗਸਤ ਦੇ ਕੈਂਪ ਬਾਰੇ ਪੁੱਛਿਆ ਸੀ।", "প্রথমে বেছে নিন এটি কার কাছে যাবে — আপনার সব পরিবার, একটি লিস্টিংয়ে বুকিং করা সবাই, অথবা এখানকার মতো একটি ঠিকানা; আমরা সারার ইমেইল দেব, কারণ সে আগস্টের ক্যাম্প নিয়ে জিজ্ঞেস করেছিল।", "أولًا اختر لمن ستُرسل — جميع عائلاتك، أو كل من حجز في عرض واحد، أو كما هنا، عنوان واحد؛ سنضع بريد سارة لأنها سألت عن مخيم أغسطس.", "Primeiro escolha para quem vai — todas as suas famílias, todos os reservados numa oferta ou, como aqui, um único endereço; vamos pôr o e-mail da Sarah, porque ela perguntou pelo campo de agosto.", "Primero elige a quién va dirigido: todas tus familias, todos los reservados en una oferta o, como aquí, una sola dirección; pondremos el correo de Sarah, porque preguntó por el campamento de agosto.", "D'abord, choisissez le destinataire — toutes vos familles, tous les inscrits à une offre ou, comme ici, une seule adresse ; nous mettrons l'e-mail de Sarah, car elle s'est renseignée sur le camp d'août.", "Yn gyntaf, dewiswch at bwy mae'n mynd — eich holl deuluoedd, pawb sydd wedi archebu ar un rhestriad, neu, fel yma, un cyfeiriad; rhown e-bost Sarah i mewn, gan iddi holi am wersyll mis Awst."],
  "lt_email_s5": ["Next the subject line — the first thing families read in their inbox, so we'll make it count.", "Teraz temat — pierwsza rzecz, którą rodziny czytają w skrzynce, więc niech zrobi wrażenie.", "Apoi subiectul — primul lucru pe care îl citesc familiile în inbox, așa că îl vom face să conteze.", "اب سبجیکٹ لائن — یہ وہ پہلی چیز ہے جو خاندان اپنے ان باکس میں پڑھتے ہیں، تو اسے اثر دار بنائیں۔", "ਹੁਣ ਵਿਸ਼ਾ ਲਾਈਨ — ਇਹ ਪਹਿਲੀ ਚੀਜ਼ ਹੈ ਜੋ ਪਰਿਵਾਰ ਆਪਣੇ ਇਨਬਾਕਸ ਵਿੱਚ ਪੜ੍ਹਦੇ ਹਨ, ਇਸ ਲਈ ਇਸ ਨੂੰ ਅਸਰਦਾਰ ਬਣਾਈਏ।", "এবার বিষয় লাইন — ইনবক্সে পরিবারগুলো প্রথমেই এটি পড়ে, তাই এটিকে কার্যকর করে তুলি।", "ثم سطر الموضوع — أول ما تقرؤه العائلات في صندوق الوارد، فلنجعله مؤثرًا.", "Depois o assunto — a primeira coisa que as famílias leem na caixa de entrada, por isso vamos fazê-lo contar.", "Luego el asunto: lo primero que leen las familias en su bandeja de entrada, así que hagamos que cuente.", "Puis l'objet — la première chose que les familles lisent dans leur boîte de réception, alors faisons en sorte qu'il compte.", "Nesaf, y llinell pwnc — y peth cyntaf y mae teuluoedd yn ei ddarllen yn eu mewnflwch, felly gadewch i ni wneud iddi gyfrif."],
  "lt_email_s6": ["Then the message itself — you write it right here, with photos, attachments, a saved signature and a Help-me-write button all to hand.", "A potem sama wiadomość — piszesz ją właśnie tutaj, mając pod ręką zdjęcia, załączniki, zapisany podpis i przycisk Pomóż mi napisać.", "Apoi mesajul propriu-zis — îl scrii chiar aici, cu poze, atașamente, o semnătură salvată și un buton Ajută-mă să scriu la îndemână.", "پھر خود پیغام — آپ اسے یہیں لکھتے ہیں، تصاویر، اٹیچمنٹس، محفوظ دستخط اور «لکھنے میں میری مدد کریں» بٹن سب ہاتھ کے قریب ہیں۔", "ਫਿਰ ਸੁਨੇਹਾ ਆਪ — ਤੁਸੀਂ ਇਸ ਨੂੰ ਇੱਥੇ ਹੀ ਲਿਖਦੇ ਹੋ, ਤਸਵੀਰਾਂ, ਅਟੈਚਮੈਂਟਾਂ, ਸੰਭਾਲਿਆ ਦਸਤਖ਼ਤ ਅਤੇ «ਲਿਖਣ ਵਿੱਚ ਮੇਰੀ ਮਦਦ ਕਰੋ» ਬਟਨ ਸਭ ਹੱਥ ਦੇ ਕੋਲ ਹਨ।", "তারপর বার্তাটি নিজেই — আপনি এখানেই লেখেন, ছবি, সংযুক্তি, সংরক্ষিত স্বাক্ষর ও «লিখতে সাহায্য করুন» বোতাম সবই হাতের কাছে।", "ثم الرسالة نفسها — تكتبها هنا مباشرة، والصور والمرفقات والتوقيع المحفوظ وزر «ساعدني في الكتابة» كلها في متناول يدك.", "Depois a própria mensagem — escreve-a mesmo aqui, com fotografias, anexos, uma assinatura guardada e um botão Ajuda-me a escrever à mão.", "Después el mensaje en sí: lo escribes aquí mismo, con fotos, adjuntos, una firma guardada y un botón Ayúdame a escribir a mano.", "Puis le message lui-même — vous le rédigez ici même, avec photos, pièces jointes, une signature enregistrée et un bouton Aide-moi à écrire sous la main.", "Yna'r neges ei hun — rydych chi'n ei hysgrifennu yma, gyda lluniau, atodiadau, llofnod wedi'i gadw a botwm Helpwch fi i ysgrifennu wrth law."],
  "lt_email_s7": ["And that's it — press Send to 1 recipient and it's on its way, with a short undo-send window in case you have second thoughts.", "I gotowe — naciskasz Wyślij do 1 odbiorcy i wiadomość wyrusza, z krótkim oknem cofnięcia wysyłki na wypadek, gdybyś zmienił zdanie.", "Și gata — apeși Trimite către 1 destinatar și pleacă, cu o scurtă fereastră de anulare a trimiterii, în caz că te răzgândești.", "بس یہی — «1 وصول کنندہ کو بھیجیں» دبائیں اور پیغام روانہ ہو جاتا ہے، اور اگر آپ کا ارادہ بدل جائے تو بھیجنا واپس لینے کے لیے مختصر وقت ملتا ہے۔", "ਬੱਸ ਇਹੀ — «1 ਪ੍ਰਾਪਤਕਰਤਾ ਨੂੰ ਭੇਜੋ» ਦਬਾਓ ਅਤੇ ਸੁਨੇਹਾ ਰਵਾਨਾ ਹੋ ਜਾਂਦਾ ਹੈ, ਜੇ ਤੁਹਾਡਾ ਮਨ ਬਦਲ ਜਾਵੇ ਤਾਂ ਭੇਜਣਾ ਵਾਪਸ ਲੈਣ ਲਈ ਇੱਕ ਛੋਟੀ ਖਿੜਕੀ ਵੀ ਹੈ।", "ব্যস — «১ প্রাপককে পাঠান» চাপুন আর বার্তা রওনা হয়ে যায়, মন বদলালে পাঠানো ফিরিয়ে নেওয়ার জন্য একটু সময়ও থাকে।", "وهذا كل شيء — اضغط «إرسال إلى مستلم واحد» فتنطلق الرسالة، مع مهلة قصيرة للتراجع عن الإرسال إن غيّرت رأيك.", "E já está — prima Enviar para 1 destinatário e segue caminho, com uma curta janela para anular o envio, caso mude de ideias.", "Y ya está: pulsas Enviar a 1 destinatario y sale, con una breve ventana para deshacer el envío por si te lo piensas mejor.", "Et voilà — appuyez sur Envoyer à 1 destinataire et il part, avec un court délai pour annuler l'envoi si vous changez d'avis.", "A dyna ni — pwyswch Anfon at 1 derbynnydd ac mae ar ei ffordd, gyda ffenestr fer i ddadwneud anfon rhag ofn y byddwch yn newid eich meddwl."],
  "lt_timetable_title": ["Building an activity timetable", "Tworzenie planu zajęć", "Crearea unui orar de activități", "سرگرمیوں کا ٹائم ٹیبل بنانا", "ਸਰਗਰਮੀਆਂ ਦੀ ਸਮਾਂ-ਸਾਰਣੀ ਬਣਾਉਣਾ", "কার্যক্রমের সময়সূচি তৈরি করা", "إنشاء جدول الأنشطة", "Criar um horário de atividades", "Crear un horario de actividades", "Créer un emploi du temps d'activités", "Adeiladu amserlen gweithgareddau"],
  "lt_timetable_intro": ["The timetable builder plans the day itself — every session, break and sign-in — from your own activity bank, then publishes it to staff and parents. Let me build one with you.", "Kreator planu zajęć układa sam dzień — każde zajęcia, przerwę i rejestrację — z Twojego własnego banku aktywności, a potem publikuje go dla personelu i rodziców. Zbudujmy jeden razem.", "Generatorul de orar planifică chiar ziua — fiecare sesiune, pauză și sosire — din propria ta bancă de activități, apoi îl publică pentru personal și părinți. Hai să construim unul împreună.", "ٹائم ٹیبل بلڈر خود دن کی منصوبہ بندی کرتا ہے — ہر سیشن، وقفہ اور آمد — آپ کے اپنے سرگرمیوں کے ذخیرے سے، پھر اسے عملے اور والدین کے لیے شائع کر دیتا ہے۔ آئیے مل کر ایک بناتے ہیں۔", "ਟਾਈਮਟੇਬਲ ਬਿਲਡਰ ਦਿਨ ਦੀ ਆਪ ਯੋਜਨਾ ਬਣਾਉਂਦਾ ਹੈ — ਹਰ ਸੈਸ਼ਨ, ਵਿਰਾਮ ਅਤੇ ਹਾਜ਼ਰੀ — ਤੁਹਾਡੇ ਆਪਣੇ ਸਰਗਰਮੀਆਂ ਦੇ ਭੰਡਾਰ ਤੋਂ, ਫਿਰ ਇਸ ਨੂੰ ਸਟਾਫ਼ ਅਤੇ ਮਾਪਿਆਂ ਲਈ ਪ੍ਰਕਾਸ਼ਿਤ ਕਰਦਾ ਹੈ। ਆਓ ਮਿਲ ਕੇ ਇੱਕ ਬਣਾਈਏ।", "টাইমটেবিল বিল্ডার দিনটির পরিকল্পনা নিজেই করে — প্রতিটি সেশন, বিরতি ও সাইন-ইন — আপনার নিজের কার্যক্রম ভান্ডার থেকে, তারপর কর্মী ও অভিভাবকদের জন্য প্রকাশ করে। চলুন একসঙ্গে একটি বানাই।", "يخطّط منشئ الجدول اليوم نفسه — كل جلسة واستراحة وتسجيل وصول — من بنك أنشطتك الخاص، ثم ينشره للموظفين وأولياء الأمور. هيا نبنِ واحدًا معًا.", "O construtor de horários planeia o próprio dia — cada sessão, pausa e entrada — a partir do seu banco de atividades e depois publica-o para a equipa e os pais. Vamos construir um juntos.", "El creador de horarios planifica el propio día —cada sesión, pausa y registro de entrada— a partir de tu banco de actividades y luego lo publica para el personal y los padres. Vamos a crear uno juntos.", "Le créateur d'emploi du temps planifie la journée elle-même — chaque séance, pause et arrivée — à partir de votre propre banque d'activités, puis le publie pour le personnel et les parents. Construisons-en un ensemble.", "Mae'r adeiladwr amserlen yn cynllunio'r diwrnod ei hun — pob sesiwn, egwyl a mewngofnodi — o'ch banc gweithgareddau eich hun, yna'n ei gyhoeddi i staff a rhieni. Gadewch i ni adeiladu un gyda'n gilydd."],
  "lt_timetable_done": ["That's a full day mapped out. Auto-fill does the heavy lifting, then Publish timetable shares it — staff see their sessions and parents see the plan for their booked days.", "Cały dzień rozplanowany. Autouzupełnianie wykonuje ciężką pracę, a Opublikuj plan go udostępnia — personel widzi swoje zajęcia, a rodzice plan na swoje zarezerwowane dni.", "O zi întreagă planificată. Completarea automată face munca grea, apoi Publică orarul îl partajează — personalul își vede sesiunile, iar părinții văd planul pentru zilele lor rezervate.", "پورا دن ترتیب پا گیا۔ آٹو فل بھاری کام کر دیتا ہے، پھر «ٹائم ٹیبل شائع کریں» اسے شیئر کرتا ہے — عملہ اپنے سیشن دیکھتا ہے اور والدین اپنے بک کیے دنوں کا منصوبہ۔", "ਪੂਰਾ ਦਿਨ ਤਰਤੀਬ ਵਿੱਚ ਆ ਗਿਆ। ਆਟੋ-ਫਿਲ ਭਾਰੀ ਕੰਮ ਕਰਦਾ ਹੈ, ਫਿਰ «ਟਾਈਮਟੇਬਲ ਪ੍ਰਕਾਸ਼ਿਤ ਕਰੋ» ਇਸ ਨੂੰ ਸਾਂਝਾ ਕਰਦਾ ਹੈ — ਸਟਾਫ਼ ਆਪਣੇ ਸੈਸ਼ਨ ਵੇਖਦਾ ਹੈ ਅਤੇ ਮਾਪੇ ਆਪਣੇ ਬੁਕ ਕੀਤੇ ਦਿਨਾਂ ਦੀ ਯੋਜਨਾ।", "পুরো দিনটি সাজানো হয়ে গেল। অটো-ফিল ভারী কাজটা করে, তারপর «টাইমটেবিল প্রকাশ করুন» সেটি শেয়ার করে — কর্মীরা তাদের সেশন দেখে আর অভিভাবকরা তাদের বুক করা দিনগুলোর পরিকল্পনা দেখেন।", "اكتمل تخطيط يوم كامل. يتولّى الملء التلقائي العمل الشاق، ثم يشاركه «نشر الجدول» — فيرى الموظفون جلساتهم ويرى أولياء الأمور الخطة لأيام حجزهم.", "Um dia inteiro planeado. O preenchimento automático faz o trabalho pesado e depois Publicar horário partilha-o — a equipa vê as suas sessões e os pais veem o plano dos seus dias reservados.", "Un día completo organizado. El autorrelleno hace el trabajo pesado y luego Publicar horario lo comparte: el personal ve sus sesiones y los padres ven el plan de sus días reservados.", "Une journée entière organisée. Le remplissage automatique fait le gros du travail, puis Publier l'emploi du temps le partage — le personnel voit ses séances et les parents voient le programme de leurs jours réservés.", "Diwrnod llawn wedi'i fapio. Mae Llenwi'n awtomatig yn gwneud y gwaith trwm, yna mae Cyhoeddi amserlen yn ei rannu — mae staff yn gweld eu sesiynau ac mae rhieni'n gweld y cynllun ar gyfer eu diwrnodau archebedig."],
  "lt_timetable_s0": ["This is where you plan the day itself — every session, break and sign-in, built from your own activity bank. Works for a holiday camp, an after-school club or a weekly class.", "Tutaj planujesz sam dzień — każde zajęcia, przerwę i rejestrację — z własnego banku aktywności. Sprawdza się przy obozie wakacyjnym, kółku po szkole i cotygodniowych zajęciach.", "Aici planifici chiar ziua — fiecare sesiune, pauză și sosire — din propria ta bancă de activități. Merge pentru o tabără de vacanță, un club după școală sau o oră săptămânală.", "یہاں آپ خود دن کی منصوبہ بندی کرتے ہیں — ہر سیشن، وقفہ اور آمد — اپنے سرگرمیوں کے ذخیرے سے۔ یہ چھٹیوں کے کیمپ، اسکول کے بعد کے کلب یا ہفتہ وار کلاس کے لیے کام کرتا ہے۔", "ਇੱਥੇ ਤੁਸੀਂ ਦਿਨ ਦੀ ਆਪ ਯੋਜਨਾ ਬਣਾਉਂਦੇ ਹੋ — ਹਰ ਸੈਸ਼ਨ, ਵਿਰਾਮ ਅਤੇ ਹਾਜ਼ਰੀ — ਆਪਣੇ ਸਰਗਰਮੀਆਂ ਦੇ ਭੰਡਾਰ ਤੋਂ। ਇਹ ਛੁੱਟੀਆਂ ਦੇ ਕੈਂਪ, ਸਕੂਲ ਤੋਂ ਬਾਅਦ ਦੇ ਕਲੱਬ ਜਾਂ ਹਫ਼ਤਾਵਾਰੀ ਕਲਾਸ ਲਈ ਕੰਮ ਕਰਦਾ ਹੈ।", "এখানে আপনি দিনটির পরিকল্পনা নিজেই করেন — প্রতিটি সেশন, বিরতি ও সাইন-ইন — আপনার নিজের কার্যক্রম ভান্ডার থেকে। ছুটির ক্যাম্প, স্কুলের পরের ক্লাব বা সাপ্তাহিক ক্লাসের জন্য এটি কাজ করে।", "هنا تخطّط اليوم نفسه — كل جلسة واستراحة وتسجيل وصول — من بنك أنشطتك الخاص. ويصلح لمخيم عطلة أو نادٍ بعد المدرسة أو حصة أسبوعية.", "É aqui que planeia o próprio dia — cada sessão, pausa e entrada — a partir do seu banco de atividades. Serve para um campo de férias, um clube pós-escolar ou uma aula semanal.", "Aquí planificas el propio día —cada sesión, pausa y registro de entrada— a partir de tu banco de actividades. Sirve para un campamento de vacaciones, un club extraescolar o una clase semanal.", "C'est ici que vous planifiez la journée elle-même — chaque séance, pause et arrivée — à partir de votre banque d'activités. Cela convient à un camp de vacances, un club après l'école ou un cours hebdomadaire.", "Dyma lle rydych chi'n cynllunio'r diwrnod ei hun — pob sesiwn, egwyl a mewngofnodi — o'ch banc gweithgareddau eich hun. Mae'n gweithio ar gyfer gwersyll gwyliau, clwb ar ôl ysgol neu ddosbarth wythnosol."],
  "lt_timetable_s1": ["Seven quick steps run across the top — from the dates, through the shape of the day, to arrivals, spaces and groups.", "U góry jest siedem szybkich kroków — od dat, przez kształt dnia, po przyjazdy, pomieszczenia i grupy.", "Sus sunt șapte pași rapizi — de la date, prin forma zilei, până la sosiri, spații și grupe.", "اوپر سات تیز قدم ہیں — تاریخوں سے لے کر دن کی ساخت، آمد، جگہوں اور گروپس تک۔", "ਉੱਪਰ ਸੱਤ ਤੇਜ਼ ਕਦਮ ਹਨ — ਤਾਰੀਖਾਂ ਤੋਂ ਲੈ ਕੇ ਦਿਨ ਦੀ ਬਣਤਰ, ਆਮਦ, ਥਾਵਾਂ ਅਤੇ ਗਰੁੱਪਾਂ ਤੱਕ।", "ওপরে সাতটি দ্রুত ধাপ আছে — তারিখ থেকে শুরু করে দিনের কাঠামো, আগমন, জায়গা ও গ্রুপ পর্যন্ত।", "في الأعلى سبع خطوات سريعة — من التواريخ، مرورًا بهيكل اليوم، إلى الوصول والأماكن والمجموعات.", "No topo estão sete passos rápidos — das datas, passando pela forma do dia, até às chegadas, espaços e grupos.", "Arriba hay siete pasos rápidos: desde las fechas, pasando por la estructura del día, hasta las llegadas, los espacios y los grupos.", "Sept étapes rapides s'enchaînent en haut — des dates, à la forme de la journée, puis aux arrivées, aux espaces et aux groupes.", "Mae saith cam cyflym ar draws y brig — o'r dyddiadau, drwy siâp y diwrnod, i gyrraedd, lleoedd a grwpiau."],
  "lt_timetable_s2": ["The last step builds it: auto-fill the whole week in one go, or lay it out by hand — then publish to staff and parents.", "Ostatni krok to budowa: automatycznie wypełnij cały tydzień za jednym razem albo ułóż go ręcznie — a potem opublikuj dla personelu i rodziców.", "Ultimul pas îl construiește: completezi automat toată săptămâna dintr-o dată sau îl aranjezi manual — apoi publici pentru personal și părinți.", "آخری قدم اسے بناتا ہے: پورا ہفتہ ایک ہی بار میں آٹو فل کریں یا ہاتھ سے ترتیب دیں — پھر عملے اور والدین کے لیے شائع کریں۔", "ਆਖਰੀ ਕਦਮ ਇਸ ਨੂੰ ਬਣਾਉਂਦਾ ਹੈ: ਪੂਰਾ ਹਫ਼ਤਾ ਇੱਕੋ ਵਾਰ ਆਟੋ-ਫਿਲ ਕਰੋ ਜਾਂ ਹੱਥੀਂ ਤਰਤੀਬ ਦਿਓ — ਫਿਰ ਸਟਾਫ਼ ਅਤੇ ਮਾਪਿਆਂ ਲਈ ਪ੍ਰਕਾਸ਼ਿਤ ਕਰੋ।", "শেষ ধাপটি এটি তৈরি করে: পুরো সপ্তাহ একবারে অটো-ফিল করুন বা হাতে সাজান — তারপর কর্মী ও অভিভাবকদের জন্য প্রকাশ করুন।", "الخطوة الأخيرة تبني الجدول: املأ الأسبوع كله دفعة واحدة تلقائيًا أو رتّبه يدويًا — ثم انشره للموظفين وأولياء الأمور.", "O último passo constrói-o: preencha a semana inteira de uma vez automaticamente ou organize-o à mão — e depois publique para a equipa e os pais.", "El último paso lo construye: rellena toda la semana de una vez automáticamente o dispónla a mano, y luego publícala para el personal y los padres.", "La dernière étape le construit : remplissez toute la semaine d'un coup automatiquement ou composez-la à la main — puis publiez pour le personnel et les parents.", "Mae'r cam olaf yn ei adeiladu: llenwch yr wythnos gyfan ar unwaith yn awtomatig, neu trefnwch hi â llaw — yna cyhoeddwch i staff a rhieni."],
  "lt_timetable_s3": ["The builder opens on step one. Pick the listing — say the Newport Pagnell football camp — and set the dates, the eleventh to the fourteenth of August.", "Kreator otwiera się na kroku pierwszym. Wybierz ofertę — powiedzmy obóz piłkarski w Newport Pagnell — i ustaw daty, od jedenastego do czternastego sierpnia.", "Generatorul se deschide la pasul unu. Alege oferta — de exemplu tabăra de fotbal din Newport Pagnell — și setează datele, de la 11 la 14 august.", "بلڈر پہلے قدم پر کھلتا ہے۔ لسٹنگ چنیں — مثلاً نیوپورٹ پیگنیل کا فٹبال کیمپ — اور تاریخیں طے کریں، گیارہ سے چودہ اگست۔", "ਬਿਲਡਰ ਪਹਿਲੇ ਕਦਮ ਉੱਤੇ ਖੁੱਲ੍ਹਦਾ ਹੈ। ਲਿਸਟਿੰਗ ਚੁਣੋ — ਮੰਨ ਲਓ ਨਿਊਪੋਰਟ ਪੈਗਨਲ ਦਾ ਫੁੱਟਬਾਲ ਕੈਂਪ — ਅਤੇ ਤਾਰੀਖਾਂ ਤੈਅ ਕਰੋ, ਗਿਆਰਾਂ ਤੋਂ ਚੌਦਾਂ ਅਗਸਤ।", "বিল্ডার প্রথম ধাপে খোলে। লিস্টিং বেছে নিন — ধরুন নিউপোর্ট প্যাগনেল ফুটবল ক্যাম্প — আর তারিখ ঠিক করুন, এগারো থেকে চৌদ্দ আগস্ট।", "يُفتح المنشئ على الخطوة الأولى. اختر العرض — لنقل مخيم كرة القدم في نيوبورت باغنيل — وحدّد التواريخ، من الحادي عشر إلى الرابع عشر من أغسطس.", "O construtor abre no passo um. Escolha a oferta — digamos o campo de futebol de Newport Pagnell — e defina as datas, de 11 a 14 de agosto.", "El creador se abre en el paso uno. Elige la oferta (digamos, el campamento de fútbol de Newport Pagnell) y fija las fechas, del 11 al 14 de agosto.", "Le créateur s'ouvre à l'étape un. Choisissez l'offre — disons le camp de football de Newport Pagnell — et fixez les dates, du 11 au 14 août.", "Mae'r adeiladwr yn agor ar gam un. Dewiswch y rhestriad — dyweder gwersyll pêl-droed Newport Pagnell — a gosodwch y dyddiadau, yr unfed ar ddeg i'r pedwerydd ar ddeg o Awst."],
  "lt_timetable_s4": ["Next, shape the day. Doors open at nine, home time at three, with lunch at half past twelve.", "Teraz nadaj kształt dniowi. Drzwi otwarte o dziewiątej, powrót do domu o piętnastej, a obiad o wpół do pierwszej.", "Apoi dă formă zilei. Ușile se deschid la nouă, plecarea acasă este la trei, iar prânzul la douăsprezece și jumătate.", "اگلا قدم دن کی ساخت طے کرنا ہے۔ نو بجے دروازے کھلتے ہیں، تین بجے چھٹی، اور ساڑھے بارہ بجے لنچ۔", "ਅੱਗੇ ਦਿਨ ਦੀ ਬਣਤਰ ਤੈਅ ਕਰੋ। ਨੌਂ ਵਜੇ ਦਰਵਾਜ਼ੇ ਖੁੱਲ੍ਹਦੇ ਹਨ, ਤਿੰਨ ਵਜੇ ਘਰ ਜਾਣ ਦਾ ਸਮਾਂ, ਅਤੇ ਸਾਢੇ ਬਾਰਾਂ ਵਜੇ ਲੰਚ।", "এরপর দিনের কাঠামো ঠিক করুন। নয়টায় দরজা খোলে, তিনটায় বাড়ি ফেরার সময়, আর সাড়ে বারোটায় দুপুরের খাবার।", "بعد ذلك حدّد شكل اليوم. تُفتح الأبواب في التاسعة، وموعد العودة إلى المنزل في الثالثة، والغداء في الثانية عشرة والنصف.", "A seguir, dê forma ao dia. As portas abrem às nove, a saída é às três e o almoço às doze e meia.", "Después, da forma al día. Las puertas abren a las nueve, la salida es a las tres y el almuerzo a las doce y media.", "Ensuite, donnez sa forme à la journée. Ouverture des portes à neuf heures, départ à quinze heures, avec le déjeuner à midi et demi.", "Nesaf, siapiwch y diwrnod. Mae'r drysau'n agor am naw, amser mynd adref am dri, gyda chinio am hanner awr wedi deuddeg."],
  "lt_timetable_s5": ["Now tick the spaces you've got. There's no pool at this venue, so tap it off — the plan simply won't schedule swimming.", "Teraz zaznacz dostępne pomieszczenia. W tym miejscu nie ma basenu, więc odznacz go — plan po prostu nie zaplanuje pływania.", "Acum bifează spațiile pe care le ai. La acest loc nu există piscină, așa că debifeaz-o — planul pur și simplu nu va programa înot.", "اب وہ جگہیں ٹک کریں جو آپ کے پاس ہیں۔ اس مقام پر تالاب نہیں ہے، اس لیے اسے بند کر دیں — پلان میں تیراکی شامل ہی نہیں ہوگی۔", "ਹੁਣ ਉਹ ਥਾਵਾਂ ਟਿੱਕ ਕਰੋ ਜੋ ਤੁਹਾਡੇ ਕੋਲ ਹਨ। ਇਸ ਥਾਂ ਉੱਤੇ ਤਲਾਬ ਨਹੀਂ ਹੈ, ਇਸ ਲਈ ਇਸ ਨੂੰ ਬੰਦ ਕਰ ਦਿਓ — ਯੋਜਨਾ ਵਿੱਚ ਤੈਰਾਕੀ ਸ਼ਾਮਲ ਹੀ ਨਹੀਂ ਹੋਵੇਗੀ।", "এবার আপনার কাছে থাকা জায়গাগুলোতে টিক দিন। এই ভেন্যুতে সুইমিং পুল নেই, তাই সেটি বন্ধ করে দিন — পরিকল্পনায় সাঁতার রাখাই হবে না।", "الآن ضع علامة على الأماكن المتوفرة لديك. لا يوجد مسبح في هذا المكان، فألغِه — ولن تُدرج الخطة السباحة.", "Agora assinale os espaços que tem. Neste local não há piscina, por isso desmarque-a — o plano simplesmente não agendará natação.", "Ahora marca los espacios que tienes. En esta sede no hay piscina, así que desmárcala: el plan simplemente no programará natación.", "Cochez maintenant les espaces dont vous disposez. Il n'y a pas de piscine sur ce site, décochez-la — le plan ne programmera simplement pas de natation.", "Nawr ticiwch y lleoedd sydd gennych. Nid oes pwll nofio yn y lleoliad hwn, felly tapiwch ef i ffwrdd — yn syml, ni fydd y cynllun yn trefnu nofio."],
  "lt_timetable_s6": ["Set your groups and age bands. Add a new one — Tigers, ages four to six — and choose which activity types join the rotation.", "Ustaw grupy i przedziały wiekowe. Dodaj nową — Tygrysy, wiek od czterech do sześciu lat — i wybierz, które rodzaje zajęć wejdą do rotacji.", "Stabilește grupele și intervalele de vârstă. Adaugă una nouă — Tigrii, 4–6 ani — și alege ce tipuri de activități intră în rotație.", "اپنے گروپس اور عمر کے دائرے طے کریں۔ ایک نیا شامل کریں — ٹائیگرز، چار سے چھ سال کی عمر — اور چنیں کہ کون سی اقسام کی سرگرمیاں باری باری میں شامل ہوں۔", "ਆਪਣੇ ਗਰੁੱਪ ਅਤੇ ਉਮਰ ਵਰਗ ਤੈਅ ਕਰੋ। ਇੱਕ ਨਵਾਂ ਜੋੜੋ — ਟਾਈਗਰਜ਼, ਚਾਰ ਤੋਂ ਛੇ ਸਾਲ ਦੀ ਉਮਰ — ਅਤੇ ਚੁਣੋ ਕਿ ਕਿਹੜੀਆਂ ਕਿਸਮਾਂ ਦੀਆਂ ਸਰਗਰਮੀਆਂ ਵਾਰੀ-ਵਾਰੀ ਵਿੱਚ ਸ਼ਾਮਲ ਹੋਣ।", "আপনার গ্রুপ ও বয়সের সীমা ঠিক করুন। একটি নতুন গ্রুপ যোগ করুন — টাইগারস, বয়স চার থেকে ছয় — এবং বেছে নিন কোন ধরনের কার্যক্রম পালাক্রমে থাকবে।", "حدّد مجموعاتك وفئاتك العمرية. أضِف مجموعة جديدة — «النمور»، من أربع إلى ست سنوات — واختر أنواع الأنشطة التي تدخل في التناوب.", "Defina os seus grupos e faixas etárias. Adicione um novo — Tigres, de quatro a seis anos — e escolha que tipos de atividade entram na rotação.", "Fija tus grupos y franjas de edad. Añade uno nuevo (Tigres, de cuatro a seis años) y elige qué tipos de actividad entran en la rotación.", "Définissez vos groupes et tranches d'âge. Ajoutez-en un nouveau — les Tigres, de quatre à six ans — et choisissez quels types d'activités entrent dans la rotation.", "Gosodwch eich grwpiau a'ch bandiau oedran. Ychwanegwch un newydd — Teigrod, oedran pedwar i chwech — a dewiswch pa fathau o weithgareddau sy'n ymuno â'r gylchdro."],
  "lt_timetable_s7": ["Finally, press Automatic and the week fills itself, balancing variety, spaces and age groups. From there, Publish timetable shares it with your staff and parents. That's your timetable built.", "Na koniec naciśnij Automatycznie, a tydzień wypełni się sam, równoważąc różnorodność, pomieszczenia i grupy wiekowe. Stamtąd Opublikuj plan udostępnia go personelowi i rodzicom. Plan gotowy.", "În final, apeși Automat și săptămâna se completează singură, echilibrând varietatea, spațiile și grupele de vârstă. De acolo, Publică orarul îl partajează cu personalul și părinții. Orarul tău este gata.", "آخر میں «خودکار» دبائیں اور ہفتہ خود بھر جاتا ہے، جو تنوع، جگہوں اور عمر کے گروپس میں توازن رکھتا ہے۔ وہاں سے «ٹائم ٹیبل شائع کریں» اسے آپ کے عملے اور والدین کے ساتھ شیئر کرتا ہے۔ آپ کا ٹائم ٹیبل تیار ہے۔", "ਅਖੀਰ ਵਿੱਚ «ਆਟੋਮੈਟਿਕ» ਦਬਾਓ ਅਤੇ ਹਫ਼ਤਾ ਆਪ ਭਰ ਜਾਂਦਾ ਹੈ, ਜੋ ਵੰਨ-ਸੁਵੰਨਤਾ, ਥਾਵਾਂ ਅਤੇ ਉਮਰ ਗਰੁੱਪਾਂ ਵਿੱਚ ਸੰਤੁਲਨ ਰੱਖਦਾ ਹੈ। ਉੱਥੋਂ «ਟਾਈਮਟੇਬਲ ਪ੍ਰਕਾਸ਼ਿਤ ਕਰੋ» ਇਸ ਨੂੰ ਤੁਹਾਡੇ ਸਟਾਫ਼ ਅਤੇ ਮਾਪਿਆਂ ਨਾਲ ਸਾਂਝਾ ਕਰਦਾ ਹੈ। ਤੁਹਾਡੀ ਸਮਾਂ-ਸਾਰਣੀ ਤਿਆਰ ਹੈ।", "সবশেষে «স্বয়ংক্রিয়» চাপুন আর সপ্তাহটি নিজেই ভরে যায়, বৈচিত্র্য, জায়গা ও বয়সভিত্তিক গ্রুপের মধ্যে ভারসাম্য রেখে। সেখান থেকে «টাইমটেবিল প্রকাশ করুন» সেটি আপনার কর্মী ও অভিভাবকদের সঙ্গে শেয়ার করে। আপনার টাইমটেবিল তৈরি।", "وأخيرًا اضغط «تلقائي» فيمتلئ الأسبوع بنفسه، موازنًا بين التنوع والأماكن والفئات العمرية. ومن هناك يشاركه «نشر الجدول» مع موظفيك وأولياء الأمور. وبذلك يكون جدولك قد اكتمل.", "Por fim, prima Automático e a semana preenche-se sozinha, equilibrando variedade, espaços e grupos etários. A partir daí, Publicar horário partilha-o com a sua equipa e os pais. O seu horário está construído.", "Por último, pulsa Automático y la semana se rellena sola, equilibrando variedad, espacios y grupos de edad. A partir de ahí, Publicar horario lo comparte con tu personal y los padres. Tu horario está creado.", "Enfin, appuyez sur Automatique et la semaine se remplit toute seule, en équilibrant variété, espaces et groupes d'âge. Ensuite, Publier l'emploi du temps le partage avec votre personnel et les parents. Votre emploi du temps est prêt.", "Yn olaf, pwyswch Awtomatig ac mae'r wythnos yn llenwi ei hun, gan gydbwyso amrywiaeth, lleoedd a grwpiau oedran. O'r fan honno, mae Cyhoeddi amserlen yn ei rannu gyda'ch staff a'ch rhieni. Dyna'ch amserlen wedi'i hadeiladu."],
  "lt_calendar_title": ["Events calendar", "Kalendarz wydarzeń", "Calendar de evenimente", "ایونٹس کیلنڈر", "ਸਮਾਗਮ ਕੈਲੰਡਰ", "ইভেন্ট ক্যালেন্ডার", "تقويم الفعاليات", "Calendário de eventos", "Calendario de eventos", "Calendrier des événements", "Calendr digwyddiadau"],
  "lt_calendar_intro": ["This is your one big calendar — every booked session across your listings, laid over the meetings, INSET days and closures you add yourself.", "To Twój jeden wielki kalendarz — wszystkie zarezerwowane zajęcia ze wszystkich ofert, nałożone na spotkania, dni szkoleniowe (INSET) i zamknięcia, które dodajesz sam.", "Acesta este calendarul tău unic — toate sesiunile rezervate din toate ofertele, suprapuse peste întâlnirile, zilele INSET și închiderile pe care le adaugi tu.", "یہ آپ کا ایک بڑا کیلنڈر ہے — آپ کی تمام لسٹنگز کے ہر بک سیشن کو، ان میٹنگز، انسیٹ (INSET) دنوں اور بندشوں کے اوپر رکھ کر جو آپ خود شامل کرتے ہیں۔", "ਇਹ ਤੁਹਾਡਾ ਇੱਕ ਵੱਡਾ ਕੈਲੰਡਰ ਹੈ — ਤੁਹਾਡੀਆਂ ਸਾਰੀਆਂ ਲਿਸਟਿੰਗਾਂ ਦੇ ਹਰ ਬੁਕ ਹੋਏ ਸੈਸ਼ਨ, ਉਨ੍ਹਾਂ ਮੀਟਿੰਗਾਂ, INSET ਦਿਨਾਂ ਅਤੇ ਬੰਦੀਆਂ ਦੇ ਉੱਪਰ ਜੋ ਤੁਸੀਂ ਆਪ ਜੋੜਦੇ ਹੋ।", "এটি আপনার একটি বড় ক্যালেন্ডার — আপনার সব লিস্টিংয়ের প্রতিটি বুক করা সেশন, সঙ্গে আপনি নিজে যে মিটিং, INSET দিন ও বন্ধের দিন যোগ করেন সেগুলো।", "هذا هو تقويمك الكبير الواحد — كل جلسة محجوزة في جميع عروضك، فوق الاجتماعات وأيام التدريب (INSET) وفترات الإغلاق التي تضيفها بنفسك.", "Este é o seu grande calendário único — todas as sessões reservadas em todas as suas ofertas, sobrepostas às reuniões, dias INSET e encerramentos que acrescenta.", "Este es tu gran calendario único: todas las sesiones reservadas de todas tus ofertas, superpuestas a las reuniones, los días INSET y los cierres que añades tú mismo.", "C'est votre grand calendrier unique — chaque séance réservée de toutes vos offres, superposée aux réunions, journées INSET et fermetures que vous ajoutez vous-même.", "Dyma'ch un calendr mawr — pob sesiwn sydd wedi'i harchebu ar draws eich rhestriadau, wedi'i gosod dros y cyfarfodydd, y diwrnodau HMS (INSET) a'r cau rydych chi'n eu hychwanegu eich hun."],
  "lt_calendar_done": ["One tidy calendar for every session and every event you run, however busy your week gets.", "Jeden przejrzysty kalendarz dla wszystkich zajęć i wydarzeń, które prowadzisz, choćby tydzień był bardzo pracowity.", "Un singur calendar ordonat pentru fiecare sesiune și fiecare eveniment pe care îl organizezi, oricât de aglomerată ar fi săptămâna.", "ایک صاف ستھرا کیلنڈر ہر سیشن اور ہر ایونٹ کے لیے جو آپ چلاتے ہیں، چاہے آپ کا ہفتہ کتنا ہی مصروف کیوں نہ ہو۔", "ਹਰ ਸੈਸ਼ਨ ਅਤੇ ਹਰ ਸਮਾਗਮ ਲਈ ਇੱਕ ਸਾਫ਼-ਸੁਥਰਾ ਕੈਲੰਡਰ ਜੋ ਤੁਸੀਂ ਚਲਾਉਂਦੇ ਹੋ, ਭਾਵੇਂ ਤੁਹਾਡਾ ਹਫ਼ਤਾ ਕਿੰਨਾ ਵੀ ਰੁੱਝਿਆ ਹੋਵੇ।", "আপনি যে প্রতিটি সেশন ও প্রতিটি ইভেন্ট চালান তার জন্য একটি পরিপাটি ক্যালেন্ডার, সপ্তাহ যতই ব্যস্ত হোক।", "تقويم واحد مرتّب لكل جلسة ولكل فعالية تديرها، مهما بلغ أسبوعك من الازدحام.", "Um calendário arrumado para cada sessão e cada evento que realiza, por mais cheia que a semana fique.", "Un calendario ordenado para cada sesión y cada evento que organizas, por muy ocupada que sea tu semana.", "Un seul calendrier bien rangé pour chaque séance et chaque événement que vous organisez, même quand la semaine est chargée.", "Un calendr taclus ar gyfer pob sesiwn a phob digwyddiad rydych chi'n ei redeg, waeth pa mor brysur yw eich wythnos."],
  "lt_calendar_s0": ["Flip between Month for the overview, Week for booked numbers per day, and Day for the full run-sheet of a single date.", "Przełączaj się między Miesiącem (przegląd), Tygodniem (liczba rezerwacji dziennie) i Dniem (pełny plan jednej daty).", "Comută între Lună pentru imaginea de ansamblu, Săptămână pentru numărul de rezervări pe zi și Zi pentru programul complet al unei singure date.", "مہینہ (مجموعی جائزے کے لیے)، ہفتہ (روزانہ بکنگز کی تعداد کے لیے) اور دن (ایک تاریخ کے مکمل شیڈول کے لیے) کے درمیان بدلتے رہیں۔", "ਮਹੀਨਾ (ਸਮੁੱਚੇ ਝਲਕ ਲਈ), ਹਫ਼ਤਾ (ਰੋਜ਼ ਦੀਆਂ ਬੁਕਿੰਗਾਂ ਦੀ ਗਿਣਤੀ ਲਈ) ਅਤੇ ਦਿਨ (ਇੱਕ ਤਾਰੀਖ ਦੇ ਪੂਰੇ ਸ਼ਡਿਊਲ ਲਈ) ਵਿਚਕਾਰ ਬਦਲੋ।", "মাস (সামগ্রিক চিত্রের জন্য), সপ্তাহ (প্রতিদিনের বুকিং সংখ্যার জন্য) এবং দিন (একটি তারিখের পূর্ণ সূচির জন্য) — এগুলোর মধ্যে বদলে দেখুন।", "بدّل بين «الشهر» للنظرة العامة، و«الأسبوع» لأعداد الحجوزات في كل يوم، و«اليوم» لجدول تاريخ واحد كاملًا.", "Alterne entre Mês para a visão geral, Semana para os números reservados por dia e Dia para o programa completo de uma só data.", "Alterna entre Mes para la vista general, Semana para las cifras de reservas por día y Día para el programa completo de una sola fecha.", "Passez de Mois pour la vue d'ensemble, à Semaine pour le nombre de réservations par jour, puis à Jour pour le programme complet d'une seule date.", "Newidiwch rhwng Mis ar gyfer y trosolwg, Wythnos ar gyfer y niferoedd archebedig bob dydd, a Diwrnod ar gyfer taflen redeg lawn un dyddiad."],
  "lt_calendar_s1": ["Toggle your own events or booking info on and off, and tap any listing in the legend to hide it.", "Włączaj i wyłączaj własne wydarzenia albo informacje o rezerwacjach, a stuknij dowolną ofertę w legendzie, żeby ją ukryć.", "Activează sau dezactivează propriile evenimente sau informațiile despre rezervări și atinge orice ofertă din legendă pentru a o ascunde.", "اپنے ایونٹس یا بکنگ کی معلومات کو آن اور آف کریں، اور لیجنڈ میں کسی بھی لسٹنگ پر ٹیپ کر کے اسے چھپا دیں۔", "ਆਪਣੇ ਸਮਾਗਮ ਜਾਂ ਬੁਕਿੰਗ ਦੀ ਜਾਣਕਾਰੀ ਚਾਲੂ ਅਤੇ ਬੰਦ ਕਰੋ, ਅਤੇ ਲੈਜੈਂਡ ਵਿੱਚ ਕਿਸੇ ਵੀ ਲਿਸਟਿੰਗ ਉੱਤੇ ਟੈਪ ਕਰਕੇ ਉਸ ਨੂੰ ਲੁਕਾਓ।", "আপনার নিজের ইভেন্ট বা বুকিং তথ্য চালু-বন্ধ করুন, আর কোনো লিস্টিং লুকাতে লেজেন্ডে সেটিতে ট্যাপ করুন।", "فعِّل أو عطِّل فعالياتك الخاصة أو معلومات الحجز، واضغط على أي عرض في مفتاح الألوان لإخفائه.", "Ative ou desative os seus próprios eventos ou a informação das reservas e toque em qualquer oferta na legenda para a ocultar.", "Activa o desactiva tus propios eventos o la información de reservas, y toca cualquier oferta en la leyenda para ocultarla.", "Activez ou désactivez vos propres événements ou les infos de réservation, et touchez n'importe quelle offre dans la légende pour la masquer.", "Trowch eich digwyddiadau eich hun neu wybodaeth archebu ymlaen ac i ffwrdd, a thapiwch unrhyw restriad yn y allwedd i'w guddio."],
  "lt_calendar_s2": ["Every booked session lands here on its own. To add your own — a meeting, an INSET day or a closure — you press Add event.", "Każda zarezerwowana sesja trafia tu sama. Aby dodać własne wydarzenie — spotkanie, dzień INSET lub zamknięcie — naciskasz Dodaj wydarzenie.", "Fiecare sesiune rezervată ajunge aici singură. Pentru a adăuga una a ta — o întâlnire, o zi INSET sau o închidere — apeși Adaugă eveniment.", "ہر بک سیشن خود بخود یہاں آ جاتا ہے۔ اپنا ایونٹ شامل کرنے کے لیے — میٹنگ، انسیٹ دن یا بندش — آپ «ایونٹ شامل کریں» دباتے ہیں۔", "ਹਰ ਬੁਕ ਹੋਇਆ ਸੈਸ਼ਨ ਆਪ ਹੀ ਇੱਥੇ ਆ ਜਾਂਦਾ ਹੈ। ਆਪਣਾ ਜੋੜਨ ਲਈ — ਮੀਟਿੰਗ, INSET ਦਿਨ ਜਾਂ ਬੰਦੀ — ਤੁਸੀਂ «ਸਮਾਗਮ ਜੋੜੋ» ਦਬਾਉਂਦੇ ਹੋ।", "প্রতিটি বুক করা সেশন নিজে থেকেই এখানে আসে। নিজের একটি যোগ করতে — মিটিং, INSET দিন বা বন্ধের দিন — আপনি «ইভেন্ট যোগ করুন» চাপেন।", "كل جلسة محجوزة تظهر هنا من تلقاء نفسها. ولإضافة فعاليتك الخاصة — اجتماع أو يوم INSET أو إغلاق — تضغط «إضافة فعالية».", "Cada sessão reservada aparece aqui sozinha. Para acrescentar um evento seu — uma reunião, um dia INSET ou um encerramento — prima Adicionar evento.", "Cada sesión reservada llega aquí sola. Para añadir uno tuyo (una reunión, un día INSET o un cierre) pulsas Añadir evento.", "Chaque séance réservée arrive ici toute seule. Pour ajouter la vôtre — une réunion, une journée INSET ou une fermeture — vous appuyez sur Ajouter un événement.", "Mae pob sesiwn sydd wedi'i harchebu yn glanio yma ar ei phen ei hun. I ychwanegu eich un chi — cyfarfod, diwrnod HMS (INSET) neu gau — pwyswch Ychwanegu digwyddiad."],
  "lt_calendar_s3": ["Give it a title — I'll call this one an INSET day — then pick the date, and set a start and end time, or tick All day.", "Nadaj tytuł — nazwę to dniem INSET — potem wybierz datę i ustaw godzinę rozpoczęcia i zakończenia albo zaznacz Cały dzień.", "Dă-i un titlu — îl voi numi zi INSET — apoi alege data și setează ora de început și de sfârșit sau bifează Toată ziua.", "اسے عنوان دیں — میں اسے انسیٹ دن کہوں گا — پھر تاریخ چنیں، اور شروع اور ختم کا وقت طے کریں، یا «پورا دن» ٹک کریں۔", "ਇਸ ਨੂੰ ਇੱਕ ਸਿਰਲੇਖ ਦਿਓ — ਮੈਂ ਇਸ ਨੂੰ INSET ਦਿਨ ਕਹਾਂਗਾ — ਫਿਰ ਤਾਰੀਖ ਚੁਣੋ, ਅਤੇ ਸ਼ੁਰੂ ਅਤੇ ਅੰਤ ਦਾ ਸਮਾਂ ਤੈਅ ਕਰੋ, ਜਾਂ «ਸਾਰਾ ਦਿਨ» ਟਿੱਕ ਕਰੋ।", "একটি শিরোনাম দিন — আমি এটিকে INSET দিন বলব — তারপর তারিখ বেছে নিন, শুরু ও শেষের সময় ঠিক করুন, অথবা «সারা দিন» টিক দিন।", "أعطِه عنوانًا — سأسمّي هذا «يوم INSET» — ثم اختر التاريخ، وحدّد وقت البدء والانتهاء، أو ضع علامة «طوال اليوم».", "Dê-lhe um título — vou chamar a este um dia INSET — depois escolha a data e defina a hora de início e de fim, ou assinale Dia inteiro.", "Ponle un título (yo lo llamaré día INSET), luego elige la fecha y fija la hora de inicio y fin, o marca Todo el día.", "Donnez-lui un titre — j'appellerai celui-ci une journée INSET — puis choisissez la date et réglez l'heure de début et de fin, ou cochez Toute la journée.", "Rhowch deitl iddo — galwaf hwn yn ddiwrnod HMS (INSET) — yna dewiswch y dyddiad, a gosodwch amser dechrau a gorffen, neu ticiwch Drwy'r dydd."],
  "lt_calendar_s4": ["Choose a category and colour so it's easy to spot at a glance — a staff meeting, INSET day, open day or closure.", "Wybierz kategorię i kolor, żeby łatwo było go wypatrzyć — spotkanie personelu, dzień INSET, dzień otwarty lub zamknięcie.", "Alege o categorie și o culoare ca să-l observi ușor — o ședință de personal, o zi INSET, o zi porților deschise sau o închidere.", "ایک زمرہ اور رنگ چنیں تاکہ وہ ایک نظر میں پہچانا جائے — عملے کی میٹنگ، انسیٹ دن، اوپن ڈے یا بندش۔", "ਇੱਕ ਸ਼੍ਰੇਣੀ ਅਤੇ ਰੰਗ ਚੁਣੋ ਤਾਂ ਜੋ ਇਹ ਇੱਕ ਨਜ਼ਰ ਵਿੱਚ ਪਛਾਣਿਆ ਜਾਵੇ — ਸਟਾਫ਼ ਮੀਟਿੰਗ, INSET ਦਿਨ, ਖੁੱਲ੍ਹਾ ਦਿਨ ਜਾਂ ਬੰਦੀ।", "একটি বিভাগ ও রং বেছে নিন, যাতে এক নজরে চেনা যায় — কর্মী সভা, INSET দিন, ওপেন ডে বা বন্ধের দিন।", "اختر فئة ولونًا ليسهل تمييزه من النظرة الأولى — اجتماع موظفين أو يوم INSET أو يوم مفتوح أو إغلاق.", "Escolha uma categoria e uma cor para o distinguir à primeira vista — uma reunião de equipa, um dia INSET, um dia aberto ou um encerramento.", "Elige una categoría y un color para localizarlo de un vistazo: una reunión de personal, un día INSET, una jornada de puertas abiertas o un cierre.", "Choisissez une catégorie et une couleur pour le repérer d'un coup d'œil — une réunion du personnel, une journée INSET, une journée portes ouvertes ou une fermeture.", "Dewiswch gategori a lliw fel ei bod hi'n hawdd ei weld ar yr olwg gyntaf — cyfarfod staff, diwrnod HMS (INSET), diwrnod agored neu gau."],
  "lt_calendar_s5": ["Turn on a reminder if you'd like one, then press Save, and it drops straight onto the calendar.", "Włącz przypomnienie, jeśli chcesz, potem naciśnij Zapisz, a wydarzenie od razu pojawi się w kalendarzu.", "Activează un memento dacă vrei, apoi apasă Salvează, iar evenimentul apare direct în calendar.", "اگر چاہیں تو یاد دہانی آن کریں، پھر «محفوظ کریں» دبائیں، اور وہ سیدھا کیلنڈر میں آ جاتا ہے۔", "ਜੇ ਚਾਹੋ ਤਾਂ ਯਾਦ-ਦਹਾਨੀ ਚਾਲੂ ਕਰੋ, ਫਿਰ «ਸੰਭਾਲੋ» ਦਬਾਓ, ਅਤੇ ਇਹ ਸਿੱਧਾ ਕੈਲੰਡਰ ਉੱਤੇ ਆ ਜਾਂਦਾ ਹੈ।", "চাইলে একটি অনুস্মারক চালু করুন, তারপর «সেভ করুন» চাপুন, আর এটি সরাসরি ক্যালেন্ডারে বসে যায়।", "فعِّل تذكيرًا إن رغبت، ثم اضغط «حفظ» فيظهر مباشرة على التقويم.", "Ative um lembrete, se quiser, e prima Guardar — e ele aparece logo no calendário.", "Activa un recordatorio si lo deseas y pulsa Guardar: aparecerá directamente en el calendario.", "Activez un rappel si vous le souhaitez, puis appuyez sur Enregistrer, et il s'affiche aussitôt dans le calendrier.", "Trowch nodyn atgoffa ymlaen os hoffech, yna pwyswch Cadw, ac mae'n disgyn yn syth ar y calendr."],
  "lt_ratios_title": ["Ratios and groups", "Proporcje i grupy", "Raporturi și grupe", "تناسب اور گروپس", "ਅਨੁਪਾਤ ਅਤੇ ਗਰੁੱਪ", "অনুপাত ও গ্রুপ", "النِّسب والمجموعات", "Rácios e grupos", "Ratios y grupos", "Ratios et groupes", "Cymarebau a grwpiau"],
  "lt_ratios_intro": ["This is your live cover board — it sorts the day's booked children into age groups from your registers and checks each one against your own ratio targets, so you can tell at a glance whether every group's properly staffed.", "To Twoja tablica pokrycia na żywo — na podstawie rejestrów dzieli zarezerwowane na dany dzień dzieci na grupy wiekowe i sprawdza każdą z nich względem Twoich własnych norm proporcji, żebyś od razu widział, czy każda grupa ma wystarczająco opiekunów.", "Aceasta este tabla ta de acoperire în timp real — sortează copiii rezervați pentru ziua respectivă pe grupe de vârstă, pe baza registrelor, și verifică fiecare grupă față de țintele tale de raport, ca să vezi dintr-o privire dacă fiecare grupă are suficient personal.", "یہ آپ کا لائیو کور بورڈ ہے — یہ رجسٹروں سے دن کے بک کیے گئے بچوں کو عمر کے گروپس میں ترتیب دیتا ہے اور ہر گروپ کو آپ کے اپنے تناسب کے اہداف سے جانچتا ہے، تاکہ آپ ایک نظر میں جان لیں کہ ہر گروپ میں عملہ پورا ہے یا نہیں۔", "ਇਹ ਤੁਹਾਡਾ ਲਾਈਵ ਕਵਰ ਬੋਰਡ ਹੈ — ਇਹ ਰਜਿਸਟਰਾਂ ਤੋਂ ਦਿਨ ਦੇ ਬੁਕ ਕੀਤੇ ਬੱਚਿਆਂ ਨੂੰ ਉਮਰ ਗਰੁੱਪਾਂ ਵਿੱਚ ਛਾਂਟਦਾ ਹੈ ਅਤੇ ਹਰ ਇੱਕ ਨੂੰ ਤੁਹਾਡੇ ਆਪਣੇ ਅਨੁਪਾਤ ਟੀਚਿਆਂ ਨਾਲ ਪਰਖਦਾ ਹੈ, ਤਾਂ ਜੋ ਤੁਸੀਂ ਇੱਕ ਨਜ਼ਰ ਵਿੱਚ ਜਾਣ ਲਵੋ ਕਿ ਹਰ ਗਰੁੱਪ ਵਿੱਚ ਸਟਾਫ਼ ਪੂਰਾ ਹੈ ਜਾਂ ਨਹੀਂ।", "এটি আপনার লাইভ কভার বোর্ড — রেজিস্টার থেকে সেদিনের বুক করা শিশুদের বয়সভিত্তিক গ্রুপে ভাগ করে এবং প্রতিটি গ্রুপকে আপনার নিজের অনুপাত লক্ষ্যের সঙ্গে মিলিয়ে দেখে, যাতে এক নজরে বোঝা যায় প্রতিটি গ্রুপে যথেষ্ট কর্মী আছে কি না।", "هذه لوحة التغطية المباشرة لديك — تفرز أطفال اليوم المحجوزين إلى فئات عمرية من سجلاتك وتقارن كل فئة بأهداف النسب التي وضعتَها، لتعرف من نظرة واحدة إن كانت كل مجموعة مكتملة الكادر.", "Este é o seu painel de cobertura em direto — organiza as crianças reservadas para o dia em grupos etários a partir dos seus registos e verifica cada um face às suas próprias metas de rácio, para ver de relance se cada grupo tem pessoal suficiente.", "Este es tu panel de cobertura en directo: clasifica a los niños reservados del día en grupos de edad a partir de tus registros y comprueba cada uno frente a tus propios objetivos de ratio, para ver de un vistazo si cada grupo tiene personal suficiente.", "C'est votre tableau de couverture en direct — il répartit les enfants réservés du jour en groupes d'âge à partir de vos registres et vérifie chacun par rapport à vos propres objectifs de taux d'encadrement, pour voir d'un coup d'œil si chaque groupe est bien encadré.", "Dyma'ch bwrdd cynnwys byw — mae'n didoli plant archebedig y dydd i grwpiau oedran o'ch cofrestrau ac yn gwirio pob un yn erbyn eich targedau cymhareb eich hun, fel y gallwch weld ar yr olwg gyntaf a oes digon o staff ym mhob grŵp."],
  "lt_ratios_done": ["Scope the board, follow your policy and work the cards, and you'll spot a short group long before the session ever runs.", "Ustaw zakres tablicy, stosuj swoją politykę i pracuj na kartach, a zauważysz niedobór w grupie na długo przed rozpoczęciem zajęć.", "Stabilește sfera tablei, urmează-ți politica și lucrează cu cardurile, iar vei observa o grupă cu personal insuficient cu mult înainte de începerea sesiunii.", "بورڈ کا دائرہ طے کریں، اپنی پالیسی پر چلیں اور کارڈز کے ساتھ کام کریں، تو آپ کسی کم عملے والے گروپ کو سیشن شروع ہونے سے بہت پہلے پکڑ لیں گے۔", "ਬੋਰਡ ਦਾ ਦਾਇਰਾ ਤੈਅ ਕਰੋ, ਆਪਣੀ ਨੀਤੀ ਮੰਨੋ ਅਤੇ ਕਾਰਡਾਂ ਨਾਲ ਕੰਮ ਕਰੋ, ਤਾਂ ਤੁਸੀਂ ਸੈਸ਼ਨ ਸ਼ੁਰੂ ਹੋਣ ਤੋਂ ਬਹੁਤ ਪਹਿਲਾਂ ਘੱਟ ਸਟਾਫ਼ ਵਾਲਾ ਗਰੁੱਪ ਫੜ ਲਵੋਗੇ।", "বোর্ডের পরিধি ঠিক করুন, আপনার নীতি অনুসরণ করুন এবং কার্ডগুলো নিয়ে কাজ করুন, তাহলে সেশন শুরুর অনেক আগেই কম কর্মীর গ্রুপ ধরতে পারবেন।", "حدّد نطاق اللوحة، والتزم بسياستك، واعمل على البطاقات، وستلاحظ أي مجموعة ينقصها الكادر قبل بدء الجلسة بوقت طويل.", "Defina o âmbito do painel, siga a sua política e trabalhe os cartões, e detetará um grupo com falta de pessoal muito antes de a sessão começar.", "Acota el panel, sigue tu política y trabaja las tarjetas, y detectarás un grupo corto de personal mucho antes de que empiece la sesión.", "Délimitez le tableau, suivez votre politique et travaillez les cartes, et vous repérerez un groupe sous-encadré bien avant le début de la séance.", "Cyfyngwch y bwrdd, dilynwch eich polisi a gweithiwch y cardiau, a byddwch yn gweld grŵp sydd â diffyg staff ymhell cyn i'r sesiwn ddechrau."],
  "lt_ratios_s0": ["Start by picking the season, the camp and the day with the arrows or the date picker. The three tiles then give you the headline — how many children are in, whether they're covered, and how many groups are running.", "Zacznij od wyboru sezonu, obozu i dnia strzałkami lub kalendarzem. Trzy kafelki pokazują najważniejsze — ile dzieci jest obecnych, czy mają zapewnioną opiekę i ile grup działa.", "Începe prin a alege sezonul, tabăra și ziua cu săgețile sau cu selectorul de dată. Cele trei casete îți dau ideea principală — câți copii sunt prezenți, dacă sunt acoperiți și câte grupe funcționează.", "پہلے تیروں یا تاریخ چننے والے سے سیزن، کیمپ اور دن چنیں۔ پھر تین ٹائلیں اہم بات بتاتی ہیں — کتنے بچے موجود ہیں، آیا وہ کور ہیں، اور کتنے گروپس چل رہے ہیں۔", "ਸ਼ੁਰੂ ਵਿੱਚ ਤੀਰਾਂ ਜਾਂ ਤਾਰੀਖ ਚੁਣਨ ਵਾਲੇ ਨਾਲ ਸੀਜ਼ਨ, ਕੈਂਪ ਅਤੇ ਦਿਨ ਚੁਣੋ। ਫਿਰ ਤਿੰਨ ਟਾਈਲਾਂ ਮੁੱਖ ਗੱਲ ਦੱਸਦੀਆਂ ਹਨ — ਕਿੰਨੇ ਬੱਚੇ ਹਨ, ਕੀ ਉਹ ਕਵਰ ਹਨ, ਅਤੇ ਕਿੰਨੇ ਗਰੁੱਪ ਚੱਲ ਰਹੇ ਹਨ।", "শুরুতে তীর বা তারিখ বাছাইকারী দিয়ে সিজন, ক্যাম্প ও দিন বেছে নিন। তারপর তিনটি টাইল মূল কথাটা জানায় — কতজন শিশু আছে, তারা কভার হয়েছে কি না, আর কয়টি গ্রুপ চলছে।", "ابدأ باختيار الموسم والمخيم واليوم بالأسهم أو منتقي التاريخ. ثم تعطيك البطاقات الثلاث الخلاصة — كم طفلًا حاضرًا، وهل هم مغطَّون، وكم مجموعة تعمل.", "Comece por escolher a época, o campo e o dia com as setas ou o seletor de data. Os três mosaicos dão-lhe o essencial — quantas crianças estão presentes, se estão cobertas e quantos grupos estão a funcionar.", "Empieza eligiendo la temporada, el campamento y el día con las flechas o el selector de fecha. Las tres tarjetas te dan lo esencial: cuántos niños hay, si están cubiertos y cuántos grupos funcionan.", "Commencez par choisir la saison, le camp et le jour avec les flèches ou le sélecteur de date. Les trois tuiles donnent l'essentiel — combien d'enfants sont présents, s'ils sont couverts et combien de groupes fonctionnent.", "Dechreuwch trwy ddewis y tymor, y gwersyll a'r diwrnod gyda'r saethau neu'r dewisydd dyddiad. Mae'r tri theil yn rhoi'r penawdau i chi — faint o blant sydd i mewn, a ydyn nhw dan ofal, a faint o grwpiau sy'n rhedeg."],
  "lt_ratios_s1": ["This table is here for reference only. The colours, age bands and targets are your own policy — activity camps aren't bound by statutory ratios — and they're edited over in Setup, where every board reads from the one master record.", "Ta tabela służy tylko jako odniesienie. Kolory, przedziały wiekowe i normy są Twoją własną polityką — obozy aktywności nie podlegają ustawowym proporcjom — i edytujesz je w Ustawieniach, gdzie każda tablica czyta z jednego wspólnego rekordu.", "Acest tabel este doar pentru referință. Culorile, intervalele de vârstă și țintele sunt politica ta — taberele de activități nu sunt legate de rapoarte legale — și se editează în Setări, unde fiecare tablă citește din aceeași înregistrare principală.", "یہ جدول صرف حوالے کے لیے ہے۔ رنگ، عمر کے دائرے اور اہداف آپ کی اپنی پالیسی ہیں — سرگرمیوں کے کیمپ قانونی تناسب کے پابند نہیں — اور انہیں سیٹ اپ میں ایڈٹ کیا جاتا ہے، جہاں ہر بورڈ ایک ہی مرکزی ریکارڈ سے پڑھتا ہے۔", "ਇਹ ਸਾਰਣੀ ਸਿਰਫ਼ ਹਵਾਲੇ ਲਈ ਹੈ। ਰੰਗ, ਉਮਰ ਵਰਗ ਅਤੇ ਟੀਚੇ ਤੁਹਾਡੀ ਆਪਣੀ ਨੀਤੀ ਹਨ — ਸਰਗਰਮੀ ਕੈਂਪ ਕਾਨੂੰਨੀ ਅਨੁਪਾਤ ਦੇ ਪਾਬੰਦ ਨਹੀਂ — ਅਤੇ ਇਹ ਸੈੱਟਅੱਪ ਵਿੱਚ ਸੋਧੇ ਜਾਂਦੇ ਹਨ, ਜਿੱਥੇ ਹਰ ਬੋਰਡ ਇੱਕੋ ਮੁੱਖ ਰਿਕਾਰਡ ਤੋਂ ਪੜ੍ਹਦਾ ਹੈ।", "এই টেবিলটি শুধু রেফারেন্সের জন্য। রং, বয়সের সীমা ও লক্ষ্যমাত্রা আপনার নিজের নীতি — কার্যক্রম ক্যাম্প বিধিবদ্ধ অনুপাতে বাধ্য নয় — এবং সেগুলো সেটআপে সম্পাদনা করা হয়, যেখানে প্রতিটি বোর্ড একই মূল রেকর্ড থেকে পড়ে।", "هذا الجدول للمرجعية فقط. الألوان والفئات العمرية والأهداف هي سياستك أنت — فمخيمات الأنشطة غير ملزمة بنسب قانونية — وتُعدَّل في الإعداد، حيث تقرأ كل لوحة من السجل الرئيسي الواحد.", "Esta tabela serve apenas de referência. As cores, faixas etárias e metas são a sua própria política — os campos de atividades não estão sujeitos a rácios legais — e editam-se na Configuração, onde todos os painéis leem do mesmo registo principal.", "Esta tabla es solo de referencia. Los colores, las franjas de edad y los objetivos son tu propia política (los campamentos de actividades no están sujetos a ratios legales) y se editan en Configuración, donde todos los paneles leen del mismo registro maestro.", "Ce tableau sert uniquement de référence. Les couleurs, tranches d'âge et objectifs sont votre propre politique — les camps d'activités ne sont pas tenus par des taux légaux — et ils se modifient dans les Paramètres, où chaque tableau lit le même enregistrement de référence.", "Mae'r tabl hwn er gwybodaeth yn unig. Eich polisi eich hun yw'r lliwiau, y bandiau oedran a'r targedau — nid yw gwersylloedd gweithgareddau wedi'u rhwymo gan gymarebau statudol — ac maen nhw'n cael eu golygu yn y Gosodiadau, lle mae pob bwrdd yn darllen o'r un prif gofnod."],
  "lt_ratios_s2": ["This is the daily workspace. Every booked child drops into a coloured card by age, and each card tells you whether that group's in ratio. You can drag a child between cards to regroup them, and flip to By time to re-check cover for each arrival and pickup window.", "To codzienne miejsce pracy. Każde zarezerwowane dziecko trafia na kolorową kartę według wieku, a karta mówi, czy grupa spełnia normę. Możesz przeciągać dziecko między kartami, żeby zmienić grupy, i przełączyć na Według czasu, aby sprawdzić opiekę dla każdego przyjazdu i odbioru.", "Acesta este spațiul de lucru zilnic. Fiecare copil rezervat ajunge pe un card colorat după vârstă, iar fiecare card îți spune dacă acea grupă respectă raportul. Poți trage un copil între carduri pentru a regrupa și poți comuta la După oră pentru a reverifica acoperirea la fiecare sosire și preluare.", "یہ روزانہ کا کام کرنے کا حصہ ہے۔ ہر بک بچہ عمر کے مطابق رنگین کارڈ میں آ جاتا ہے، اور ہر کارڈ بتاتا ہے کہ گروپ تناسب میں ہے یا نہیں۔ آپ بچے کو کارڈز کے درمیان گھسیٹ کر دوبارہ گروپ کر سکتے ہیں، اور «وقت کے مطابق» پر جا کر ہر آمد اور واپسی کے وقفے کا کور دوبارہ جانچ سکتے ہیں۔", "ਇਹ ਰੋਜ਼ਾਨਾ ਕੰਮ ਦੀ ਥਾਂ ਹੈ। ਹਰ ਬੁਕ ਬੱਚਾ ਉਮਰ ਅਨੁਸਾਰ ਰੰਗੀਨ ਕਾਰਡ ਵਿੱਚ ਆ ਜਾਂਦਾ ਹੈ, ਅਤੇ ਹਰ ਕਾਰਡ ਦੱਸਦਾ ਹੈ ਕਿ ਗਰੁੱਪ ਅਨੁਪਾਤ ਵਿੱਚ ਹੈ ਜਾਂ ਨਹੀਂ। ਤੁਸੀਂ ਬੱਚੇ ਨੂੰ ਕਾਰਡਾਂ ਵਿਚਕਾਰ ਖਿੱਚ ਕੇ ਮੁੜ ਗਰੁੱਪ ਕਰ ਸਕਦੇ ਹੋ, ਅਤੇ «ਸਮੇਂ ਅਨੁਸਾਰ» ਉੱਤੇ ਜਾ ਕੇ ਹਰ ਆਮਦ ਤੇ ਲੈਣ ਦੀ ਖਿੜਕੀ ਲਈ ਕਵਰ ਮੁੜ ਵੇਖ ਸਕਦੇ ਹੋ।", "এটি প্রতিদিনের কাজের জায়গা। প্রতিটি বুক করা শিশু বয়স অনুযায়ী একটি রঙিন কার্ডে বসে, আর প্রতিটি কার্ড বলে গ্রুপটি অনুপাতে আছে কি না। শিশুকে কার্ডের মধ্যে টেনে এনে আবার গ্রুপ করতে পারেন, আর «সময় অনুযায়ী» এ গিয়ে প্রতিটি আগমন ও নেওয়ার সময়ের কভার আবার যাচাই করতে পারেন।", "هذه مساحة العمل اليومية. يقع كل طفل محجوز في بطاقة ملوّنة حسب العمر، وتخبرك كل بطاقة إن كانت المجموعة ضمن النسبة. يمكنك سحب طفل بين البطاقات لإعادة التجميع، والتبديل إلى «حسب الوقت» لإعادة فحص التغطية لكل وصول واستلام.", "Este é o espaço de trabalho diário. Cada criança reservada cai num cartão colorido por idade, e cada cartão diz-lhe se esse grupo está dentro do rácio. Pode arrastar uma criança entre cartões para reagrupar e mudar para Por hora para reverificar a cobertura de cada chegada e recolha.", "Este es el espacio de trabajo diario. Cada niño reservado cae en una tarjeta de color según su edad, y cada tarjeta te dice si ese grupo cumple el ratio. Puedes arrastrar a un niño entre tarjetas para reagrupar y pasar a Por hora para volver a comprobar la cobertura de cada llegada y recogida.", "C'est l'espace de travail quotidien. Chaque enfant réservé se place dans une carte colorée selon son âge, et chaque carte indique si ce groupe respecte le taux. Vous pouvez glisser un enfant d'une carte à l'autre pour regrouper, et passer à Par heure pour revérifier la couverture à chaque arrivée et départ.", "Dyma'r gweithle dyddiol. Mae pob plentyn archebedig yn disgyn i gerdyn lliw yn ôl oedran, ac mae pob cerdyn yn dweud a yw'r grŵp hwnnw o fewn y gymhareb. Gallwch lusgo plentyn rhwng cardiau i ailgrwpio, a newid i Yn ôl amser i ailwirio'r gofal ar gyfer pob cyrraedd a chasglu."],
  "lt_ratios_s3": ["Now let's staff it. Down in Your team you build your roster — pop in a name and their role. We'll add Jamie Okafor as a Sports Coach on the Summer Multi-Sports Camp.", "Teraz obsadźmy ją personelem. Niżej, w Twój zespół, budujesz listę — wpisujesz imię i rolę. Dodamy Jamiego Okafora jako trenera sportowego na Letnim obozie wielosportowym.", "Acum să o dotăm cu personal. Mai jos, în Echipa ta, îți construiești lista — introduci un nume și rolul. Îl vom adăuga pe Jamie Okafor ca antrenor sportiv la Tabăra de vară multisport.", "اب اسے عملے سے پورا کرتے ہیں۔ نیچے «آپ کی ٹیم» میں آپ اپنا روسٹر بناتے ہیں — نام اور کردار ڈال دیں۔ ہم جیمی اوکافور کو سمر ملٹی اسپورٹس کیمپ پر اسپورٹس کوچ کے طور پر شامل کریں گے۔", "ਹੁਣ ਇਸ ਵਿੱਚ ਸਟਾਫ਼ ਲਾਈਏ। ਹੇਠਾਂ «ਤੁਹਾਡੀ ਟੀਮ» ਵਿੱਚ ਤੁਸੀਂ ਆਪਣਾ ਰੋਸਟਰ ਬਣਾਉਂਦੇ ਹੋ — ਇੱਕ ਨਾਂ ਅਤੇ ਉਨ੍ਹਾਂ ਦੀ ਭੂਮਿਕਾ ਪਾਓ। ਅਸੀਂ ਜੈਮੀ ਓਕਾਫ਼ੋਰ ਨੂੰ ਸਮਰ ਮਲਟੀ-ਸਪੋਰਟਸ ਕੈਂਪ ਉੱਤੇ ਸਪੋਰਟਸ ਕੋਚ ਵਜੋਂ ਜੋੜਾਂਗੇ।", "এবার এতে কর্মী বসাই। নিচে «আপনার টিম»-এ আপনি রোস্টার বানান — একটি নাম ও তাদের ভূমিকা দিন। আমরা জেমি ওকাফোরকে সামার মাল্টি-স্পোর্টস ক্যাম্পে স্পোর্টস কোচ হিসেবে যোগ করব।", "الآن لنوفّر له كادرًا. في الأسفل، ضمن «فريقك»، تبني قائمتك — أدخل اسمًا ودورًا. سنضيف جيمي أوكافور مدرّبًا رياضيًا في مخيم الصيف متعدد الرياضات.", "Agora vamos dotá-lo de pessoal. Em baixo, na Sua equipa, constrói o seu quadro — introduza um nome e a função. Vamos adicionar o Jamie Okafor como treinador desportivo no Campo multidesportivo de verão.", "Ahora dotémoslo de personal. Abajo, en Tu equipo, montas tu plantilla: pon un nombre y su rol. Añadiremos a Jamie Okafor como entrenador deportivo en el Campamento multideporte de verano.", "Maintenant, affectons du personnel. Plus bas, dans Votre équipe, vous constituez votre liste — saisissez un nom et son rôle. Nous allons ajouter Jamie Okafor comme éducateur sportif au Camp multisports d'été.", "Nawr gadewch i ni staffio'r bwrdd. I lawr yn Eich tîm, rydych chi'n adeiladu eich rhestr — rhowch enw a'u rôl i mewn. Ychwanegwn Jamie Okafor fel Hyfforddwr Chwaraeon ar y Gwersyll Aml-chwaraeon Haf."],
  "lt_ratios_s4": ["Press Add, and Jamie joins the team, ready to place on the board.", "Naciśnij Dodaj, a Jamie dołącza do zespołu, gotowy do umieszczenia na tablicy.", "Apasă Adaugă, iar Jamie se alătură echipei, gata să fie plasat pe tablă.", "«شامل کریں» دبائیں، اور جیمی ٹیم میں شامل ہو جاتا ہے، بورڈ پر لگنے کے لیے تیار۔", "«ਜੋੜੋ» ਦਬਾਓ, ਅਤੇ ਜੈਮੀ ਟੀਮ ਵਿੱਚ ਸ਼ਾਮਲ ਹੋ ਜਾਂਦਾ ਹੈ, ਬੋਰਡ ਉੱਤੇ ਲਾਉਣ ਲਈ ਤਿਆਰ।", "«যোগ করুন» চাপুন, আর জেমি টিমে যুক্ত হয়ে যায়, বোর্ডে বসানোর জন্য প্রস্তুত।", "اضغط «إضافة» فينضم جيمي إلى الفريق، جاهزًا للوضع على اللوحة.", "Prima Adicionar e o Jamie junta-se à equipa, pronto para ser colocado no painel.", "Pulsa Añadir y Jamie se une al equipo, listo para colocarse en el panel.", "Appuyez sur Ajouter, et Jamie rejoint l'équipe, prêt à être placé sur le tableau.", "Pwyswch Ychwanegu, ac mae Jamie'n ymuno â'r tîm, yn barod i'w osod ar y bwrdd."],
  "lt_ratios_s5": ["Now assign a coach to a group. Open a dropdown in the team roster and pick where they go — we'll drop them in with the Explorers, the eight to ten year olds.", "Teraz przypisz trenera do grupy. Otwórz listę rozwijaną w składzie zespołu i wybierz, dokąd trafia — umieścimy go z Odkrywcami, czyli ośmio- do dziesięciolatkami.", "Acum repartizează un antrenor la o grupă. Deschide un meniu derulant din lista echipei și alege unde merge — îl vom pune cu Exploratorii, copiii de la opt la zece ani.", "اب کسی کوچ کو گروپ میں لگائیں۔ ٹیم روسٹر میں ایک ڈراپ ڈاؤن کھولیں اور چنیں کہ وہ کہاں جائے — ہم اسے ایکسپلورر گروپ کے ساتھ لگائیں گے، آٹھ سے دس سال کے بچے۔", "ਹੁਣ ਕਿਸੇ ਕੋਚ ਨੂੰ ਗਰੁੱਪ ਵਿੱਚ ਲਾਓ। ਟੀਮ ਰੋਸਟਰ ਵਿੱਚ ਇੱਕ ਡ੍ਰੌਪਡਾਊਨ ਖੋਲ੍ਹੋ ਅਤੇ ਚੁਣੋ ਕਿ ਉਹ ਕਿੱਥੇ ਜਾਵੇ — ਅਸੀਂ ਉਸ ਨੂੰ ਐਕਸਪਲੋਰਰਜ਼ ਨਾਲ ਲਾਵਾਂਗੇ, ਅੱਠ ਤੋਂ ਦਸ ਸਾਲ ਦੇ ਬੱਚੇ।", "এবার একজন কোচকে একটি গ্রুপে নিয়োগ করুন। টিম রোস্টারে একটি ড্রপডাউন খুলে বেছে নিন তিনি কোথায় যাবেন — আমরা তাঁকে এক্সপ্লোরারসদের সঙ্গে দেব, আট থেকে দশ বছর বয়সীরা।", "الآن عيّن مدرّبًا لمجموعة. افتح قائمة منسدلة في قائمة الفريق واختر أين يذهب — سنضعه مع «المستكشفين»، الأطفال من ثماني إلى عشر سنوات.", "Agora atribua um treinador a um grupo. Abra uma lista no quadro da equipa e escolha para onde vai — vamos colocá-lo com os Exploradores, as crianças dos oito aos dez anos.", "Ahora asigna un entrenador a un grupo. Abre un desplegable en la plantilla del equipo y elige adónde va: lo pondremos con los Exploradores, los niños de ocho a diez años.", "Affectez maintenant un éducateur à un groupe. Ouvrez une liste déroulante dans l'équipe et choisissez où il va — nous le mettrons avec les Explorateurs, les huit à dix ans.", "Nawr neilltuwch hyfforddwr i grŵp. Agorwch gwymplen yn rhestr y tîm a dewiswch ble maen nhw'n mynd — rhown nhw gyda'r Fforwyr, y plant wyth i ddeg oed."],
  "lt_ratios_s6": ["And that's it — the Explorers card shows them in ratio and the Staff on duty tile ticks up straightaway. There's no Save button to hunt for; every change here saves on its own and is shared with the rest of your team.", "I gotowe — karta Odkrywców pokazuje, że grupa spełnia normę, a kafelek Personel na dyżurze od razu rośnie. Nie ma przycisku Zapisz, którego trzeba szukać; każda zmiana zapisuje się sama i jest widoczna dla reszty zespołu.", "Gata — cardul Exploratorilor arată acum că sunt în raport, iar caseta Personal de serviciu crește imediat. Nu trebuie să cauți niciun buton Salvează; fiecare modificare se salvează singură și este partajată cu restul echipei.", "بس یہی — ایکسپلورر کارڈ انہیں تناسب میں دکھاتا ہے اور «ڈیوٹی پر عملہ» ٹائل فوراً بڑھ جاتی ہے۔ کسی «محفوظ کریں» بٹن کو ڈھونڈنا نہیں پڑتا؛ یہاں ہر تبدیلی خود محفوظ ہو جاتی ہے اور آپ کی باقی ٹیم کے ساتھ شیئر ہو جاتی ہے۔", "ਬੱਸ ਇਹੀ — ਐਕਸਪਲੋਰਰਜ਼ ਕਾਰਡ ਉਨ੍ਹਾਂ ਨੂੰ ਅਨੁਪਾਤ ਵਿੱਚ ਦਿਖਾਉਂਦਾ ਹੈ ਅਤੇ «ਡਿਊਟੀ ਉੱਤੇ ਸਟਾਫ਼» ਟਾਈਲ ਤੁਰੰਤ ਵਧ ਜਾਂਦੀ ਹੈ। «ਸੰਭਾਲੋ» ਬਟਨ ਲੱਭਣ ਦੀ ਲੋੜ ਨਹੀਂ; ਇੱਥੇ ਹਰ ਤਬਦੀਲੀ ਆਪਣੇ-ਆਪ ਸੁਰੱਖਿਅਤ ਹੁੰਦੀ ਹੈ ਅਤੇ ਬਾਕੀ ਟੀਮ ਨਾਲ ਸਾਂਝੀ ਹੋ ਜਾਂਦੀ ਹੈ।", "ব্যস — এক্সপ্লোরারস কার্ডে এখন অনুপাত ঠিক দেখাচ্ছে আর «ডিউটিতে কর্মী» টাইল সঙ্গে সঙ্গে বেড়ে যায়। কোনো «সেভ» বোতাম খুঁজতে হয় না; এখানে প্রতিটি পরিবর্তন নিজে থেকেই সেভ হয় এবং আপনার বাকি টিমের সঙ্গে শেয়ার হয়।", "وهذا كل شيء — تُظهر بطاقة «المستكشفين» أنهم ضمن النسبة، ويرتفع عدّاد «الموظفون المناوبون» فورًا. لا يوجد زر «حفظ» للبحث عنه؛ فكل تغيير هنا يُحفظ تلقائيًا ويُشارَك مع بقية فريقك.", "E é isto — o cartão dos Exploradores mostra-os dentro do rácio e o mosaico Pessoal de serviço sobe logo. Não há botão Guardar para procurar; cada alteração aqui guarda-se sozinha e é partilhada com o resto da equipa.", "Y ya está: la tarjeta de los Exploradores los muestra dentro del ratio y la tarjeta Personal de servicio sube al instante. No hay botón Guardar que buscar; cada cambio aquí se guarda solo y se comparte con el resto de tu equipo.", "Et voilà — la carte des Explorateurs les montre dans le taux et la tuile Personnel de service augmente aussitôt. Pas de bouton Enregistrer à chercher ; chaque modification ici s'enregistre toute seule et est partagée avec le reste de votre équipe.", "A dyna ni — mae cerdyn y Fforwyr yn eu dangos o fewn y gymhareb ac mae'r teil Staff ar ddyletswydd yn cynyddu ar unwaith. Nid oes botwm Cadw i chwilio amdano; mae pob newid yma'n cael ei gadw ar ei ben ei hun ac yn cael ei rannu gyda gweddill eich tîm."],
  "lt_registers_title": ["Registers", "Rejestry", "Registre", "رجسٹر", "ਹਾਜ਼ਰੀ ਰਜਿਸਟਰ", "রেজিস্টার", "سجلات الحضور", "Registos", "Registros", "Registres", "Cofrestrau"],
  "lt_registers_intro": ["This is your daily register — where you sign the children in and out, keep an eye on every allergy and medical flag, count heads for safety, and reach any parent in a tap, all for one camp on one day.", "To Twój codzienny rejestr — tutaj odnotowujesz wejścia i wyjścia dzieci, pilnujesz każdej alergii i uwagi medycznej, liczysz dzieci dla bezpieczeństwa i docierasz do każdego rodzica jednym stuknięciem, wszystko dla jednego obozu w jednym dniu.", "Acesta este registrul tău zilnic — aici îi înregistrezi pe copii la intrare și la ieșire, urmărești fiecare alergie și semnal medical, numeri copiii pentru siguranță și ajungi la orice părinte cu o atingere, totul pentru o tabără într-o zi.", "یہ آپ کا روزانہ کا رجسٹر ہے — جہاں آپ بچوں کی آمد اور روانگی درج کرتے ہیں، ہر الرجی اور طبی نشان پر نظر رکھتے ہیں، حفاظت کے لیے گنتی کرتے ہیں، اور کسی بھی والدین تک ایک ٹیپ میں پہنچتے ہیں، سب ایک دن میں ایک کیمپ کے لیے۔", "ਇਹ ਤੁਹਾਡਾ ਰੋਜ਼ਾਨਾ ਰਜਿਸਟਰ ਹੈ — ਜਿੱਥੇ ਤੁਸੀਂ ਬੱਚਿਆਂ ਦੀ ਆਮਦ ਤੇ ਰਵਾਨਗੀ ਦਰਜ ਕਰਦੇ ਹੋ, ਹਰ ਐਲਰਜੀ ਅਤੇ ਡਾਕਟਰੀ ਨਿਸ਼ਾਨ ਉੱਤੇ ਨਜ਼ਰ ਰੱਖਦੇ ਹੋ, ਸੁਰੱਖਿਆ ਲਈ ਗਿਣਤੀ ਕਰਦੇ ਹੋ, ਅਤੇ ਕਿਸੇ ਵੀ ਮਾਪੇ ਤੱਕ ਇੱਕ ਟੈਪ ਵਿੱਚ ਪਹੁੰਚਦੇ ਹੋ, ਸਭ ਇੱਕ ਦਿਨ ਇੱਕ ਕੈਂਪ ਲਈ।", "এটি আপনার দৈনিক রেজিস্টার — যেখানে আপনি শিশুদের ঢোকা ও বেরোনো নথিভুক্ত করেন, প্রতিটি অ্যালার্জি ও চিকিৎসাগত চিহ্নের দিকে নজর রাখেন, নিরাপত্তার জন্য গুনে দেখেন এবং যেকোনো অভিভাবকের কাছে এক ট্যাপে পৌঁছান, সবই একটি দিনে একটি ক্যাম্পের জন্য।", "هذا هو سجل حضورك اليومي — حيث تسجّل دخول الأطفال وخروجهم، وتتابع كل حساسية وتنبيه طبي، وتعدّ الرؤوس من أجل السلامة، وتصل إلى أي ولي أمر بضغطة واحدة، كل ذلك لمخيم واحد في يوم واحد.", "Este é o seu registo diário — onde regista a entrada e a saída das crianças, vigia cada alergia e alerta médico, conta as crianças por segurança e chega a qualquer pai ou mãe com um toque, tudo para um campo num dia.", "Este es tu registro diario: donde marcas la entrada y la salida de los niños, vigilas cada alergia y aviso médico, cuentas cabezas por seguridad y llegas a cualquier padre o madre con un toque, todo para un campamento en un día.", "C'est votre registre quotidien — où vous enregistrez l'arrivée et le départ des enfants, surveillez chaque allergie et signalement médical, comptez les enfants pour leur sécurité et joignez n'importe quel parent d'une simple pression, le tout pour un camp sur une journée.", "Dyma'ch cofrestr ddyddiol — lle rydych chi'n mewngofnodi ac allgofnodi'r plant, yn cadw llygad ar bob alergedd a baner feddygol, yn cyfrif pennau er diogelwch, ac yn cyrraedd unrhyw riant gydag un tap, y cyfan ar gyfer un gwersyll ar un diwrnod."],
  "lt_registers_done": ["And that's the register sorted — everyone signed in, counted, safeguarded, and their parents just a tap away.", "I rejestr gotowy — wszyscy zapisani, policzeni, bezpieczni, a ich rodzice na wyciągnięcie ręki.", "Și gata registrul — toți înregistrați, numărați, în siguranță, iar părinții lor la o atingere distanță.", "اور رجسٹر مکمل — سب درج، گنے ہوئے، محفوظ، اور ان کے والدین صرف ایک ٹیپ کی دوری پر۔", "ਅਤੇ ਰਜਿਸਟਰ ਪੂਰਾ — ਸਭ ਦਰਜ, ਗਿਣੇ ਹੋਏ, ਸੁਰੱਖਿਅਤ, ਅਤੇ ਉਨ੍ਹਾਂ ਦੇ ਮਾਪੇ ਸਿਰਫ਼ ਇੱਕ ਟੈਪ ਦੂਰ।", "আর রেজিস্টার সম্পূর্ণ — সবাই নথিভুক্ত, গণনা করা, নিরাপদ, এবং তাদের অভিভাবকরা মাত্র এক ট্যাপ দূরে।", "وهكذا اكتمل السجل — الجميع مسجّل ومعدود ومحميّ، وأولياء أمورهم على بُعد ضغطة واحدة.", "E o registo está feito — todos registados, contados, protegidos e os pais a um toque de distância.", "Y el registro queda listo: todos registrados, contados, protegidos y sus padres a un toque de distancia.", "Et voilà le registre — tout le monde pointé, compté, protégé, et les parents à portée d'une simple pression.", "A dyna'r gofrestr wedi'i threfnu — pawb wedi mewngofnodi, wedi'u cyfrif, wedi'u diogelu, a'u rhieni un tap i ffwrdd."],
  "lt_registers_s0": ["Start by choosing the season, the camp and the day up in the blue banner, so the whole register is pointed at the right group before you mark a single child — and if a collection PIN is switched on, you'll see the reminder to check it at pick-up.", "Zacznij od wyboru sezonu, obozu i dnia w niebieskim banerze u góry, żeby cały rejestr dotyczył właściwej grupy, zanim oznaczysz jakiekolwiek dziecko — a jeśli włączony jest PIN odbioru, zobaczysz przypomnienie, by sprawdzić go przy odbiorze.", "Începe prin a alege sezonul, tabăra și ziua în bannerul albastru de sus, ca întregul registru să fie îndreptat spre grupul potrivit înainte de a marca vreun copil — iar dacă PIN-ul de preluare este activat, vei vedea memento-ul de a-l verifica la preluare.", "پہلے اوپر نیلے بینر میں سیزن، کیمپ اور دن چنیں تاکہ کسی بچے کو نشان زد کرنے سے پہلے پورا رجسٹر درست گروپ پر ہو — اور اگر لینے کا پن آن ہو تو آپ کو واپسی کے وقت اسے جانچنے کی یاد دہانی نظر آئے گی۔", "ਸ਼ੁਰੂ ਵਿੱਚ ਉੱਪਰ ਨੀਲੇ ਬੈਨਰ ਵਿੱਚ ਸੀਜ਼ਨ, ਕੈਂਪ ਅਤੇ ਦਿਨ ਚੁਣੋ, ਤਾਂ ਜੋ ਕਿਸੇ ਬੱਚੇ ਨੂੰ ਨਿਸ਼ਾਨ ਲਾਉਣ ਤੋਂ ਪਹਿਲਾਂ ਪੂਰਾ ਰਜਿਸਟਰ ਸਹੀ ਗਰੁੱਪ ਉੱਤੇ ਹੋਵੇ — ਅਤੇ ਜੇ ਲੈਣ ਦਾ ਪਿੰਨ ਚਾਲੂ ਹੈ ਤਾਂ ਤੁਹਾਨੂੰ ਲੈਣ ਵੇਲੇ ਉਸ ਨੂੰ ਜਾਂਚਣ ਦੀ ਯਾਦ-ਦਹਾਨੀ ਦਿਖੇਗੀ।", "শুরুতে ওপরের নীল ব্যানারে সিজন, ক্যাম্প ও দিন বেছে নিন, যাতে কোনো শিশুকে চিহ্নিত করার আগেই পুরো রেজিস্টার সঠিক দলের দিকে থাকে — আর যদি কালেকশন পিন চালু থাকে, নেওয়ার সময় সেটি যাচাইয়ের অনুস্মারক দেখবেন।", "ابدأ باختيار الموسم والمخيم واليوم في اللافتة الزرقاء في الأعلى، ليتجه السجل كله إلى المجموعة الصحيحة قبل أن تُعلِّم أي طفل — وإن كان رمز الاستلام (PIN) مفعَّلًا فسيظهر لك تذكير بفحصه عند الاستلام.", "Comece por escolher a época, o campo e o dia na faixa azul no topo, para que todo o registo aponte para o grupo certo antes de marcar qualquer criança — e, se o PIN de recolha estiver ativo, verá o lembrete para o verificar na recolha.", "Empieza eligiendo la temporada, el campamento y el día en el banner azul de arriba, para que todo el registro apunte al grupo correcto antes de marcar a ningún niño; y si el PIN de recogida está activado, verás el recordatorio para comprobarlo en la recogida.", "Commencez par choisir la saison, le camp et le jour dans la bannière bleue en haut, pour que tout le registre vise le bon groupe avant de pointer le moindre enfant — et si un code PIN de récupération est activé, vous verrez le rappel pour le vérifier à la récupération.", "Dechreuwch trwy ddewis y tymor, y gwersyll a'r diwrnod yn y faner las ar y brig, fel bod y gofrestr gyfan yn cael ei chyfeirio at y grŵp cywir cyn i chi nodi unrhyw blentyn — ac os yw PIN casglu wedi'i droi ymlaen, fe welwch y nodyn atgoffa i'w wirio wrth gasglu."],
  "lt_registers_s1": ["Sort the list youngest-first or by earliest start, search for any child by name, and tap a flag like Allergy or Medical to show only those children with the note typed right there — and Roll call gives you everyone on site now, to count heads against in a fire drill.", "Sortuj listę od najmłodszych lub według najwcześniejszego startu, szukaj dziecka po imieniu i stuknij flagę, np. Alergia lub Medyczne, żeby zobaczyć tylko dzieci z taką adnotacją od razu na liście — a Apel pokazuje wszystkich obecnych teraz na miejscu, żeby porównać liczbę podczas ćwiczeń przeciwpożarowych.", "Sortează lista începând cu cei mai mici sau după cea mai devreme oră de început, caută orice copil după nume și atinge un semnal precum Alergie sau Medical ca să vezi doar copiii cu nota respectivă scrisă chiar acolo — iar Apelul îți dă pe toți cei aflați acum în locație, ca să numeri în caz de exercițiu de incendiu.", "فہرست کو سب سے چھوٹے بچے سے یا سب سے جلدی شروع ہونے کے مطابق ترتیب دیں، نام سے کسی بھی بچے کو تلاش کریں، اور الرجی یا طبی جیسے نشان پر ٹیپ کریں تاکہ صرف وہ بچے نظر آئیں جن کا نوٹ وہیں لکھا ہو — اور «رول کال» آپ کو وہ سب دیتی ہے جو اس وقت موجود ہیں، تاکہ فائر ڈرل میں گنتی ملا سکیں۔", "ਸੂਚੀ ਨੂੰ ਸਭ ਤੋਂ ਛੋਟੇ ਤੋਂ ਜਾਂ ਸਭ ਤੋਂ ਪਹਿਲਾਂ ਸ਼ੁਰੂ ਹੋਣ ਅਨੁਸਾਰ ਤਰਤੀਬ ਦਿਓ, ਨਾਂ ਨਾਲ ਕਿਸੇ ਵੀ ਬੱਚੇ ਨੂੰ ਲੱਭੋ, ਅਤੇ ਐਲਰਜੀ ਜਾਂ ਡਾਕਟਰੀ ਵਰਗੇ ਨਿਸ਼ਾਨ ਉੱਤੇ ਟੈਪ ਕਰੋ ਤਾਂ ਜੋ ਸਿਰਫ਼ ਉਹੀ ਬੱਚੇ ਦਿਸਣ ਜਿਨ੍ਹਾਂ ਦਾ ਨੋਟ ਉੱਥੇ ਲਿਖਿਆ ਹੈ — ਅਤੇ «ਰੋਲ ਕਾਲ» ਉਹ ਸਾਰੇ ਦਿੰਦੀ ਹੈ ਜੋ ਇਸ ਵੇਲੇ ਮੌਜੂਦ ਹਨ, ਤਾਂ ਜੋ ਅੱਗ ਦੀ ਡ੍ਰਿਲ ਵਿੱਚ ਗਿਣਤੀ ਮਿਲਾ ਸਕੋ।", "তালিকা সবচেয়ে ছোট থেকে বা সবচেয়ে আগে শুরু অনুযায়ী সাজান, নাম দিয়ে যেকোনো শিশুকে খুঁজুন, আর অ্যালার্জি বা চিকিৎসাগত মতো চিহ্নে ট্যাপ করে শুধু সেই শিশুদেরই দেখুন যাদের নোট সেখানে লেখা আছে — আর «রোল কল» এখন সাইটে থাকা সবাইকে দেয়, যাতে অগ্নি মহড়ায় গণনা মেলাতে পারেন।", "رتّب القائمة من الأصغر سنًا أو حسب أبكر وقت بدء، وابحث عن أي طفل بالاسم، واضغط على علامة مثل «حساسية» أو «طبي» لترى فقط الأطفال الذين كُتبت ملاحظتهم هناك — ويمنحك «النداء» كل من هم في الموقع الآن لتعدّ الرؤوس في تمرين الإخلاء.", "Ordene a lista do mais novo para o mais velho ou pela hora de início mais cedo, pesquise qualquer criança por nome e toque numa etiqueta como Alergia ou Médico para mostrar apenas as crianças com essa nota escrita ali mesmo — e a Chamada dá-lhe todos os que estão agora no local, para contar numa simulação de incêndio.", "Ordena la lista de menor a mayor edad o por hora de inicio más temprana, busca a cualquier niño por nombre y toca una marca como Alergia o Médico para mostrar solo a los niños con esa nota escrita ahí mismo; y Pasar lista te da todos los que están ahora en el centro, para contar cabezas en un simulacro de incendio.", "Triez la liste du plus jeune au plus âgé ou par heure d'arrivée la plus tôt, recherchez n'importe quel enfant par son nom, et touchez un signalement comme Allergie ou Médical pour n'afficher que les enfants dont la note est écrite juste là — et l'Appel vous donne tous ceux présents sur place, pour compter lors d'un exercice d'incendie.", "Trefnwch y rhestr gan ddechrau gyda'r ieuengaf neu yn ôl y dechrau cynharaf, chwiliwch am unrhyw blentyn yn ôl enw, a thapiwch faner fel Alergedd neu Feddygol i ddangos dim ond y plant sydd â'r nodyn wedi'i deipio yno — ac mae'r Galw'r gofrestr yn rhoi pawb sydd ar y safle nawr i chi, i gyfrif pennau yn ystod ymarfer tân."],
  "lt_registers_s2": ["Every row has one-tap links to log first aid, an incident or medication for that child, or to message their parent, all without ever leaving the register.", "Każdy wiersz ma skróty jednym dotknięciem do zapisania pierwszej pomocy, incydentu lub leku dla tego dziecka albo do wysłania wiadomości jego rodzicowi — bez opuszczania rejestru.", "Fiecare rând are legături dintr-o atingere pentru a înregistra prim ajutor, un incident sau medicație pentru acel copil ori pentru a trimite un mesaj părintelui său, fără să părăsești vreodată registrul.", "ہر قطار میں ایک ٹیپ والے لنک ہیں، جن سے اس بچے کے لیے ابتدائی طبی امداد، واقعہ یا دوا درج کی جا سکتی ہے یا اس کے والدین کو پیغام بھیجا جا سکتا ہے، رجسٹر چھوڑے بغیر۔", "ਹਰ ਕਤਾਰ ਵਿੱਚ ਇੱਕ-ਟੈਪ ਲਿੰਕ ਹਨ, ਜਿਨ੍ਹਾਂ ਨਾਲ ਉਸ ਬੱਚੇ ਲਈ ਮੁੱਢਲੀ ਸਹਾਇਤਾ, ਘਟਨਾ ਜਾਂ ਦਵਾਈ ਦਰਜ ਕੀਤੀ ਜਾ ਸਕਦੀ ਹੈ ਜਾਂ ਉਸ ਦੇ ਮਾਪੇ ਨੂੰ ਸੁਨੇਹਾ ਭੇਜਿਆ ਜਾ ਸਕਦਾ ਹੈ, ਰਜਿਸਟਰ ਛੱਡੇ ਬਿਨਾਂ।", "প্রতিটি সারিতে এক-ট্যাপের লিংক আছে — সেই শিশুর জন্য প্রাথমিক চিকিৎসা, ঘটনা বা ওষুধ নথিভুক্ত করতে অথবা তার অভিভাবককে বার্তা পাঠাতে, রেজিস্টার না ছেড়েই।", "لكل صف روابط بضغطة واحدة لتسجيل إسعاف أولي أو واقعة أو دواء لذلك الطفل، أو لمراسلة ولي أمره، دون مغادرة السجل.", "Cada linha tem atalhos de um toque para registar primeiros socorros, um incidente ou medicação dessa criança, ou para enviar mensagem ao pai ou à mãe, sem sair do registo.", "Cada fila tiene enlaces de un toque para registrar primeros auxilios, un incidente o medicación de ese niño, o para escribir a su padre o madre, sin salir del registro.", "Chaque ligne propose des liens en une pression pour consigner un premier secours, un incident ou un médicament pour cet enfant, ou pour écrire à son parent, sans quitter le registre.", "Mae gan bob rhes ddolenni un-tap i logio cymorth cyntaf, digwyddiad neu feddyginiaeth i'r plentyn hwnnw, neu i anfon neges at ei riant, heb adael y gofrestr byth."],
  "lt_registers_s3": ["To take the register, you press Sign all in, and every booked child is marked present in a single tap — or you work down the rows with In, Collect and Absent one by one.", "Aby sprawdzić obecność, naciskasz Zapisz wszystkich jako obecnych i każde zarezerwowane dziecko jest oznaczone jednym stuknięciem — albo przechodzisz po wierszach, klikając kolejno Wszedł, Odebrany i Nieobecny.", "Pentru a face prezența, apeși Înregistrează pe toți și fiecare copil rezervat este marcat prezent dintr-o singură atingere — sau parcurgi rândurile cu Intrat, Preluat și Absent, pe rând.", "رجسٹر لینے کے لیے آپ «سب کو حاضر کریں» دباتے ہیں اور ہر بک بچہ ایک ہی ٹیپ میں حاضر درج ہو جاتا ہے — یا آپ قطار در قطار «اندر»، «واپس لیا» اور «غیر حاضر» ایک ایک کر کے دباتے ہیں۔", "ਰਜਿਸਟਰ ਲੈਣ ਲਈ ਤੁਸੀਂ «ਸਭ ਨੂੰ ਹਾਜ਼ਰ ਕਰੋ» ਦਬਾਉਂਦੇ ਹੋ ਅਤੇ ਹਰ ਬੁਕ ਬੱਚਾ ਇੱਕੋ ਟੈਪ ਵਿੱਚ ਹਾਜ਼ਰ ਲੱਗ ਜਾਂਦਾ ਹੈ — ਜਾਂ ਤੁਸੀਂ ਕਤਾਰ-ਦਰ-ਕਤਾਰ «ਅੰਦਰ», «ਲੈ ਗਏ» ਅਤੇ «ਗੈਰਹਾਜ਼ਰ» ਇੱਕ-ਇੱਕ ਕਰਕੇ ਦਬਾਉਂਦੇ ਹੋ।", "রেজিস্টার নিতে আপনি «সবাইকে উপস্থিত করুন» চাপেন আর প্রতিটি বুক করা শিশু এক ট্যাপেই উপস্থিত হিসেবে চিহ্নিত হয় — অথবা সারি ধরে ধরে «ভেতরে», «নিয়ে গেছে» ও «অনুপস্থিত» একে একে চাপেন।", "لأخذ الحضور، تضغط «تسجيل الجميع حاضرين» فيُعلَّم كل طفل محجوز حاضرًا بضغطة واحدة — أو تنزل في الصفوف مستخدمًا «دخول» و«استلام» و«غائب» واحدًا تلو الآخر.", "Para registar a presença, prime Registar todos à entrada e cada criança reservada fica presente com um só toque — ou percorre as linhas com Entrada, Recolha e Ausente, uma a uma.", "Para pasar lista, pulsas Registrar a todos y cada niño reservado queda presente de un solo toque, o bajas por las filas con Entrada, Recogida y Ausente, una a una.", "Pour faire l'appel, vous appuyez sur Tout le monde présent et chaque enfant réservé est marqué présent d'un seul geste — ou vous parcourez les lignes avec Arrivé, Récupéré et Absent, un par un.", "I gymryd y gofrestr, pwyswch Mewngofnodi pawb ac mae pob plentyn archebedig yn cael ei nodi'n bresennol gydag un tap — neu gweithiwch i lawr y rhesi gyda I mewn, Casglu ac Absennol fesul un."],
  "lt_registers_s4": ["You can reorder the list to suit the moment — tap Earliest start to line everyone up by drop-off time, or youngest-first to keep the little ones together.", "Możesz zmieniać kolejność listy, jak Ci wygodnie — stuknij Najwcześniejszy start, żeby ustawić wszystkich według godziny przywiezienia, albo od najmłodszych, żeby maluchy były razem.", "Poți reordona lista după nevoie — atinge Cea mai devreme oră de început ca să-i aliniezi pe toți după ora de aducere, sau cei mai mici primii, ca să-i ții pe cei mici împreună.", "آپ موقع کے مطابق فہرست کی ترتیب بدل سکتے ہیں — «سب سے جلدی شروع» پر ٹیپ کریں تاکہ سب بچے چھوڑنے کے وقت کے حساب سے لگ جائیں، یا سب سے چھوٹے پہلے تاکہ چھوٹے بچے اکٹھے رہیں۔", "ਤੁਸੀਂ ਮੌਕੇ ਮੁਤਾਬਕ ਸੂਚੀ ਦੀ ਤਰਤੀਬ ਬਦਲ ਸਕਦੇ ਹੋ — «ਸਭ ਤੋਂ ਪਹਿਲਾ ਸ਼ੁਰੂ» ਉੱਤੇ ਟੈਪ ਕਰੋ ਤਾਂ ਜੋ ਸਾਰੇ ਛੱਡਣ ਦੇ ਸਮੇਂ ਅਨੁਸਾਰ ਲੱਗ ਜਾਣ, ਜਾਂ ਸਭ ਤੋਂ ਛੋਟੇ ਪਹਿਲਾਂ ਤਾਂ ਜੋ ਨਿੱਕੇ ਬੱਚੇ ਇਕੱਠੇ ਰਹਿਣ।", "মুহূর্ত অনুযায়ী তালিকার ক্রম বদলাতে পারেন — «সবচেয়ে আগের শুরু» ট্যাপ করলে সবাই ড্রপ-অফের সময় অনুযায়ী সাজে, অথবা ছোটদের আগে সাজালে ছোট্ট শিশুরা একসঙ্গে থাকে।", "يمكنك إعادة ترتيب القائمة بما يناسب اللحظة — اضغط «أبكر بدء» لتصفّ الجميع حسب وقت التوصيل، أو الأصغر سنًا أولًا لتُبقي الصغار معًا.", "Pode reordenar a lista conforme o momento — toque em Início mais cedo para alinhar todos pela hora de entrega, ou no mais novo primeiro para manter os pequenos juntos.", "Puedes reordenar la lista según el momento: toca Inicio más temprano para ordenar a todos por hora de llegada, o de menor a mayor edad para mantener juntos a los pequeños.", "Vous pouvez réordonner la liste selon le moment — touchez Arrivée la plus tôt pour aligner tout le monde selon l'heure de dépôt, ou du plus jeune au plus âgé pour garder les petits ensemble.", "Gallwch aildrefnu'r rhestr i siwtio'r foment — tapiwch Dechrau cynharaf i osod pawb yn ôl amser gollwng, neu'r ieuengaf yn gyntaf i gadw'r rhai bach gyda'i gilydd."],
  "lt_registers_s5": ["On trips and free-play you'll physically count heads on top of the register — pop the number in here, and the tally flags the moment you're short.", "Na wycieczkach i podczas wolnej zabawy liczysz dzieci fizycznie dodatkowo do rejestru — wpisz tutaj liczbę, a licznik od razu ostrzeże, gdy kogoś zabraknie.", "În excursii și în timpul jocului liber vei număra copiii și fizic, pe lângă registru — introdu numărul aici, iar totalul semnalează imediat când lipsește cineva.", "سیر و تفریح اور آزاد کھیل کے دوران آپ رجسٹر کے علاوہ جسمانی طور پر بھی گنتی کرتے ہیں — تعداد یہاں ڈالیں، اور گنتی اسی لمحے خبردار کر دیتی ہے جب کوئی کم ہو۔", "ਯਾਤਰਾਵਾਂ ਅਤੇ ਖੁੱਲ੍ਹੀ ਖੇਡ ਦੌਰਾਨ ਤੁਸੀਂ ਰਜਿਸਟਰ ਤੋਂ ਇਲਾਵਾ ਆਪ ਵੀ ਗਿਣਤੀ ਕਰਦੇ ਹੋ — ਗਿਣਤੀ ਇੱਥੇ ਪਾਓ, ਅਤੇ ਜਿਵੇਂ ਹੀ ਕੋਈ ਘੱਟ ਹੋਵੇ, ਗਿਣਤੀ ਤੁਰੰਤ ਚੇਤਾਵਨੀ ਦੇ ਦਿੰਦੀ ਹੈ।", "ট্রিপ ও মুক্ত খেলার সময় রেজিস্টারের ওপরে আপনি নিজেও শিশুদের গুনে দেখেন — সংখ্যাটি এখানে দিন, আর কেউ কম পড়লেই গণনা সঙ্গে সঙ্গে সতর্ক করে।", "في الرحلات واللعب الحر ستعدّ الأطفال فعليًا فوق السجل — أدخل العدد هنا، وينبّهك العدّاد في اللحظة التي ينقص فيها أحد.", "Nas visitas e no brincar livre, conta as crianças fisicamente além do registo — introduza o número aqui e o total avisa no instante em que faltar alguém.", "En las excursiones y el juego libre contarás físicamente a los niños además del registro: pon el número aquí y el recuento avisa en el momento en que falte alguien.", "Lors des sorties et des jeux libres, vous comptez physiquement les enfants en plus du registre — saisissez le nombre ici, et le décompte vous alerte dès qu'il en manque un.", "Ar deithiau a chwarae rhydd byddwch chi'n cyfrif pennau'n gorfforol ar ben y gofrestr — rhowch y rhif i mewn yma, ac mae'r cyfanswm yn rhoi gwybod y foment y byddwch chi'n brin."],
  "lt_registers_s6": ["Then you press Log to record that count, stamped with your name and the time — and that's your register taken: everyone signed in, counted and safeguarded.", "Potem naciskasz Zapisz, żeby zapisać tę liczbę z Twoim imieniem i godziną — i rejestr gotowy: wszyscy zapisani, policzeni i bezpieczni.", "Apoi apeși Înregistrează pentru a salva numărătoarea, cu numele tău și ora — și registrul este făcut: toți înregistrați, numărați și în siguranță.", "پھر آپ «درج کریں» دباتے ہیں تاکہ وہ گنتی آپ کے نام اور وقت کے ساتھ محفوظ ہو جائے — اور آپ کا رجسٹر مکمل: سب درج، گنے ہوئے اور محفوظ۔", "ਫਿਰ ਤੁਸੀਂ «ਦਰਜ ਕਰੋ» ਦਬਾਉਂਦੇ ਹੋ ਤਾਂ ਜੋ ਉਹ ਗਿਣਤੀ ਤੁਹਾਡੇ ਨਾਂ ਅਤੇ ਸਮੇਂ ਨਾਲ ਦਰਜ ਹੋ ਜਾਵੇ — ਅਤੇ ਤੁਹਾਡਾ ਰਜਿਸਟਰ ਪੂਰਾ: ਸਭ ਦਰਜ, ਗਿਣੇ ਹੋਏ ਅਤੇ ਸੁਰੱਖਿਅਤ।", "তারপর আপনি «লগ করুন» চাপেন, যাতে সেই গণনা আপনার নাম ও সময়সহ নথিভুক্ত হয় — আর আপনার রেজিস্টার সম্পূর্ণ: সবাই নথিভুক্ত, গণনা করা ও নিরাপদ।", "ثم تضغط «تسجيل» لحفظ ذلك العدد مع اسمك والوقت — وبذلك يكتمل سجلك: الجميع مسجّل ومعدود ومحميّ.", "Depois prime Registar para guardar essa contagem, com o seu nome e a hora — e o seu registo está feito: todos registados, contados e protegidos.", "Luego pulsas Registrar para guardar ese recuento, con tu nombre y la hora, y tu registro está hecho: todos registrados, contados y protegidos.", "Puis vous appuyez sur Consigner pour enregistrer ce décompte, avec votre nom et l'heure — et votre registre est fait : tout le monde pointé, compté et protégé.", "Yna pwyswch Logio i gofnodi'r cyfrif hwnnw, wedi'i stampio â'ch enw a'r amser — a dyna'ch cofrestr wedi'i chymryd: pawb wedi mewngofnodi, wedi'u cyfrif a'u diogelu."],
  "lt_incidents_title": ["Log concern", "Zgłoś obawę", "Înregistrează o preocupare", "تشویش درج کریں", "ਚਿੰਤਾ ਦਰਜ ਕਰੋ", "উদ্বেগ লগ করুন", "تسجيل مخاوف", "Registar preocupação", "Registrar una preocupación", "Consigner une préoccupation", "Logio pryder"],
  "lt_incidents_intro": ["This is your one place for recording concerns about a child — everyday behaviour notes you can share with the parent, and confidential safeguarding matters that go straight to your DSL.", "To jedno miejsce do zapisywania obaw dotyczących dziecka — codziennych uwag o zachowaniu, które możesz pokazać rodzicowi, oraz poufnych spraw ochrony dzieci, które trafiają prosto do Twojego DSL.", "Acesta este locul unic în care înregistrezi preocupările legate de un copil — notele obișnuite despre comportament pe care le poți împărtăși cu părintele și chestiunile confidențiale de protecție a copilului care merg direct la DSL-ul tău.", "یہ بچے کے بارے میں تشویش درج کرنے کی آپ کی واحد جگہ ہے — روزمرہ رویے کے نوٹس جو آپ والدین کے ساتھ شیئر کر سکتے ہیں، اور رازدارانہ تحفظِ اطفال کے معاملات جو سیدھے آپ کے ڈی ایس ایل (DSL) کے پاس جاتے ہیں۔", "ਇਹ ਕਿਸੇ ਬੱਚੇ ਬਾਰੇ ਚਿੰਤਾਵਾਂ ਦਰਜ ਕਰਨ ਲਈ ਤੁਹਾਡੀ ਇੱਕੋ ਥਾਂ ਹੈ — ਰੋਜ਼ਾਨਾ ਵਿਹਾਰ ਦੇ ਨੋਟ ਜੋ ਤੁਸੀਂ ਮਾਪਿਆਂ ਨਾਲ ਸਾਂਝੇ ਕਰ ਸਕਦੇ ਹੋ, ਅਤੇ ਗੁਪਤ ਸੁਰੱਖਿਆ ਮਾਮਲੇ ਜੋ ਸਿੱਧੇ ਤੁਹਾਡੇ DSL ਕੋਲ ਜਾਂਦੇ ਹਨ।", "এটি কোনো শিশুর বিষয়ে উদ্বেগ নথিভুক্ত করার আপনার একমাত্র জায়গা — প্রতিদিনের আচরণের নোট যা অভিভাবকের সঙ্গে শেয়ার করা যায়, এবং গোপনীয় সুরক্ষা বিষয় যা সরাসরি আপনার DSL-এর কাছে যায়।", "هذا هو مكانك الوحيد لتسجيل المخاوف بشأن طفل — ملاحظات السلوك اليومية التي يمكنك مشاركتها مع ولي الأمر، وقضايا حماية الطفل السرية التي تذهب مباشرة إلى مسؤول الحماية المعيَّن (DSL).", "Este é o seu único lugar para registar preocupações sobre uma criança — notas de comportamento do dia a dia que pode partilhar com os pais e assuntos confidenciais de proteção de menores que vão diretamente para o seu DSL.", "Este es tu único lugar para registrar preocupaciones sobre un niño: notas de comportamiento cotidianas que puedes compartir con los padres y asuntos confidenciales de protección infantil que van directos a tu DSL.", "C'est votre unique endroit pour consigner les préoccupations concernant un enfant — des notes de comportement courantes que vous pouvez partager avec le parent, et des questions confidentielles de protection de l'enfance qui vont directement à votre DSL.", "Dyma'ch unig le i gofnodi pryderon am blentyn — nodiadau ymddygiad bob dydd y gallwch eu rhannu â'r rhiant, a materion diogelu cyfrinachol sy'n mynd yn syth at eich DSL."],
  "lt_incidents_done": ["Behaviour on one side, safeguarding on the other, and every concern kept safely on the child's record.", "Zachowanie po jednej stronie, ochrona dzieci po drugiej, a każda obawa bezpiecznie zapisana w karcie dziecka.", "Comportamentul de o parte, protecția copilului de cealaltă, iar fiecare preocupare păstrată în siguranță în fișa copilului.", "ایک طرف رویہ، دوسری طرف تحفظِ اطفال، اور ہر تشویش بچے کے ریکارڈ میں محفوظ۔", "ਇੱਕ ਪਾਸੇ ਵਿਹਾਰ, ਦੂਜੇ ਪਾਸੇ ਬਾਲ ਸੁਰੱਖਿਆ, ਅਤੇ ਹਰ ਚਿੰਤਾ ਬੱਚੇ ਦੇ ਰਿਕਾਰਡ ਵਿੱਚ ਸੁਰੱਖਿਅਤ।", "একদিকে আচরণ, অন্যদিকে সুরক্ষা, আর প্রতিটি উদ্বেগ শিশুর রেকর্ডে নিরাপদে সংরক্ষিত।", "السلوك في جهة، وحماية الطفل في الجهة الأخرى، وكل مخاوف محفوظة بأمان في سجل الطفل.", "O comportamento de um lado, a proteção de menores do outro, e cada preocupação guardada com segurança no registo da criança.", "El comportamiento a un lado, la protección infantil al otro, y cada preocupación guardada de forma segura en el expediente del niño.", "Le comportement d'un côté, la protection de l'enfance de l'autre, et chaque préoccupation conservée en sécurité dans le dossier de l'enfant.", "Ymddygiad ar un ochr, diogelu ar yr ochr arall, a phob pryder wedi'i gadw'n ddiogel ar gofnod y plentyn."],
  "lt_incidents_s0": ["Your first choice is simply which kind of concern this is — a routine behaviour note the parent can see, or a confidential safeguarding matter that's routed straight to your DSL.", "Pierwszy wybór to po prostu rodzaj obawy — rutynowa uwaga o zachowaniu, którą rodzic może zobaczyć, albo poufna sprawa ochrony dzieci, kierowana prosto do Twojego DSL.", "Prima alegere este pur și simplu ce fel de preocupare este — o notă obișnuită despre comportament pe care părintele o poate vedea sau o chestiune confidențială de protecție a copilului, direcționată direct către DSL-ul tău.", "آپ کا پہلا انتخاب بس یہ ہے کہ تشویش کس قسم کی ہے — معمول کے رویے کا نوٹ جو والدین دیکھ سکتے ہیں، یا رازدارانہ تحفظِ اطفال کا معاملہ جو سیدھا آپ کے ڈی ایس ایل کو جاتا ہے۔", "ਤੁਹਾਡੀ ਪਹਿਲੀ ਚੋਣ ਸਿਰਫ਼ ਇਹ ਹੈ ਕਿ ਚਿੰਤਾ ਕਿਸ ਕਿਸਮ ਦੀ ਹੈ — ਮਾਮੂਲੀ ਵਿਹਾਰ ਦਾ ਨੋਟ ਜੋ ਮਾਪੇ ਵੇਖ ਸਕਦੇ ਹਨ, ਜਾਂ ਗੁਪਤ ਸੁਰੱਖਿਆ ਮਾਮਲਾ ਜੋ ਸਿੱਧਾ ਤੁਹਾਡੇ DSL ਕੋਲ ਜਾਂਦਾ ਹੈ।", "আপনার প্রথম পছন্দ শুধু এটাই যে উদ্বেগটি কোন ধরনের — নিয়মিত আচরণের নোট যা অভিভাবক দেখতে পান, অথবা গোপনীয় সুরক্ষা বিষয় যা সরাসরি আপনার DSL-এর কাছে যায়।", "اختيارك الأول هو ببساطة نوع المخاوف — ملاحظة سلوك اعتيادية يمكن لولي الأمر الاطلاع عليها، أو مسألة حماية طفل سرية تُوجَّه مباشرة إلى مسؤول الحماية (DSL).", "A primeira escolha é simplesmente que tipo de preocupação é — uma nota de comportamento de rotina que os pais podem ver, ou um assunto confidencial de proteção de menores encaminhado diretamente para o seu DSL.", "Tu primera elección es simplemente de qué tipo de preocupación se trata: una nota de comportamiento rutinaria que los padres pueden ver o un asunto confidencial de protección infantil que se deriva directamente a tu DSL.", "Votre premier choix est simplement le type de préoccupation — une note de comportement courante que le parent peut voir, ou une question confidentielle de protection de l'enfance acheminée directement à votre DSL.", "Eich dewis cyntaf yw pa fath o bryder yw hwn — nodyn ymddygiad arferol y gall y rhiant ei weld, neu fater diogelu cyfrinachol sy'n cael ei gyfeirio'n syth at eich DSL."],
  "lt_incidents_s1": ["The stat tiles give you an at-a-glance feel for how many concerns are on the go and whether parents have been told, before you open a fresh record.", "Kafelki ze statystykami pokazują na pierwszy rzut oka, ile obaw jest w toku i czy rodzice zostali poinformowani, zanim otworzysz nowy zapis.", "Casetele cu statistici îți oferă o imagine de ansamblu asupra câte preocupări sunt în desfășurare și dacă părinții au fost informați, înainte să deschizi o înregistrare nouă.", "اعداد و شمار کی ٹائلیں ایک نظر میں بتاتی ہیں کہ کتنی تشویشیں جاری ہیں اور آیا والدین کو بتایا گیا ہے، نیا ریکارڈ کھولنے سے پہلے۔", "ਅੰਕੜਿਆਂ ਦੀਆਂ ਟਾਈਲਾਂ ਇੱਕ ਨਜ਼ਰ ਵਿੱਚ ਦੱਸਦੀਆਂ ਹਨ ਕਿ ਕਿੰਨੀਆਂ ਚਿੰਤਾਵਾਂ ਚੱਲ ਰਹੀਆਂ ਹਨ ਅਤੇ ਕੀ ਮਾਪਿਆਂ ਨੂੰ ਦੱਸਿਆ ਗਿਆ ਹੈ, ਨਵਾਂ ਰਿਕਾਰਡ ਖੋਲ੍ਹਣ ਤੋਂ ਪਹਿਲਾਂ।", "পরিসংখ্যানের টাইলগুলো এক নজরে বোঝায় কতগুলো উদ্বেগ চলমান এবং অভিভাবকদের জানানো হয়েছে কি না, নতুন রেকর্ড খোলার আগেই।", "تمنحك بطاقات الإحصاءات فكرة سريعة عن عدد المخاوف الجارية وهل أُبلغ أولياء الأمور، قبل أن تفتح سجلًا جديدًا.", "Os mosaicos de estatísticas dão-lhe uma ideia rápida de quantas preocupações estão em curso e se os pais foram informados, antes de abrir um novo registo.", "Las tarjetas de estadísticas te dan una idea rápida de cuántas preocupaciones hay en curso y si se ha informado a los padres, antes de abrir un nuevo registro.", "Les tuiles de statistiques vous donnent d'un coup d'œil le nombre de préoccupations en cours et si les parents ont été informés, avant d'ouvrir un nouveau dossier.", "Mae'r teils ystadegau'n rhoi darlun cyflym i chi o faint o bryderon sydd ar y gweill ac a yw rhieni wedi cael gwybod, cyn i chi agor cofnod newydd."],
  "lt_incidents_s2": ["To add one, you press Log a behaviour concern, and this three-step form opens — who and when, what happened, then how serious it was.", "Aby dodać zapis, naciskasz Zgłoś obawę dotyczącą zachowania i otwiera się trzyetapowy formularz — kto i kiedy, co się stało, a potem jak poważne to było.", "Pentru a adăuga una, apeși Înregistrează o preocupare de comportament și se deschide acest formular în trei pași — cine și când, ce s-a întâmplat, apoi cât de grav a fost.", "اضافہ کرنے کے لیے آپ «رویے کی تشویش درج کریں» دباتے ہیں، اور یہ تین مرحلوں کا فارم کھلتا ہے — کون اور کب، کیا ہوا، پھر کتنا سنگین تھا۔", "ਇੱਕ ਜੋੜਨ ਲਈ ਤੁਸੀਂ «ਵਿਹਾਰ ਬਾਰੇ ਚਿੰਤਾ ਦਰਜ ਕਰੋ» ਦਬਾਉਂਦੇ ਹੋ, ਅਤੇ ਇਹ ਤਿੰਨ ਪੜਾਵਾਂ ਵਾਲਾ ਫਾਰਮ ਖੁੱਲ੍ਹਦਾ ਹੈ — ਕੌਣ ਤੇ ਕਦੋਂ, ਕੀ ਹੋਇਆ, ਫਿਰ ਕਿੰਨਾ ਗੰਭੀਰ ਸੀ।", "একটি যোগ করতে আপনি «আচরণ নিয়ে উদ্বেগ লগ করুন» চাপেন, আর তিন ধাপের এই ফর্মটি খোলে — কে ও কখন, কী ঘটেছে, তারপর কতটা গুরুতর ছিল।", "لإضافة سجل، تضغط «تسجيل مخاوف سلوكية» فيُفتح هذا النموذج ذو الخطوات الثلاث — من ومتى، ماذا حدث، ثم مدى خطورته.", "Para acrescentar um, prime Registar preocupação de comportamento e abre-se este formulário de três passos — quem e quando, o que aconteceu e depois quão grave foi.", "Para añadir una, pulsas Registrar una preocupación de comportamiento y se abre este formulario de tres pasos: quién y cuándo, qué pasó y después qué gravedad tuvo.", "Pour en ajouter une, vous appuyez sur Consigner une préoccupation de comportement et ce formulaire en trois étapes s'ouvre — qui et quand, ce qui s'est passé, puis la gravité.", "I ychwanegu un, pwyswch Logio pryder ymddygiad ac mae'r ffurflen tri cham hon yn agor — pwy a phryd, beth ddigwyddodd, yna pa mor ddifrifol oedd hi."],
  "lt_incidents_s3": ["First, who and when. You search for the booked child so the record links to their account, then note where it happened — here, the main sports hall this afternoon at holiday camp.", "Najpierw kto i kiedy. Wyszukujesz zarezerwowane dziecko, żeby zapis był powiązany z jego kontem, a potem zaznaczasz, gdzie to się stało — tu w głównej sali sportowej dzisiaj po południu na obozie wakacyjnym.", "Mai întâi, cine și când. Cauți copilul rezervat, ca înregistrarea să fie legată de contul lui, apoi notezi unde s-a întâmplat — aici, în sala principală de sport, în această după-amiază, la tabăra de vacanță.", "پہلے کون اور کب۔ آپ بک بچے کو تلاش کرتے ہیں تاکہ ریکارڈ اس کے اکاؤنٹ سے جڑ جائے، پھر لکھتے ہیں کہ یہ کہاں ہوا — یہاں، آج دوپہر کے بعد چھٹیوں کے کیمپ میں مرکزی اسپورٹس ہال میں۔", "ਪਹਿਲਾਂ ਕੌਣ ਤੇ ਕਦੋਂ। ਤੁਸੀਂ ਬੁਕ ਬੱਚੇ ਨੂੰ ਲੱਭਦੇ ਹੋ ਤਾਂ ਜੋ ਰਿਕਾਰਡ ਉਸ ਦੇ ਖਾਤੇ ਨਾਲ ਜੁੜ ਜਾਵੇ, ਫਿਰ ਲਿਖਦੇ ਹੋ ਕਿ ਇਹ ਕਿੱਥੇ ਹੋਇਆ — ਇੱਥੇ ਅੱਜ ਦੁਪਹਿਰ ਬਾਅਦ ਛੁੱਟੀਆਂ ਦੇ ਕੈਂਪ ਵਿੱਚ ਮੁੱਖ ਸਪੋਰਟਸ ਹਾਲ ਵਿੱਚ।", "প্রথমে কে ও কখন। আপনি বুক করা শিশুকে খুঁজে নেন, যাতে রেকর্ডটি তার অ্যাকাউন্টের সঙ্গে যুক্ত হয়, তারপর লেখেন এটি কোথায় ঘটেছে — এখানে, আজ বিকেলে ছুটির ক্যাম্পে প্রধান স্পোর্টস হলে।", "أولًا من ومتى. تبحث عن الطفل المحجوز ليرتبط السجل بحسابه، ثم تدوّن مكان الحدث — هنا، قاعة الرياضة الرئيسية بعد ظهر اليوم في مخيم العطلة.", "Primeiro, quem e quando. Pesquisa a criança reservada para que o registo fique ligado à sua conta e depois indica onde aconteceu — aqui, no pavilhão desportivo principal, esta tarde, no campo de férias.", "Primero, quién y cuándo. Buscas al niño reservado para que el registro se vincule a su cuenta y luego anotas dónde ocurrió: aquí, en el pabellón deportivo principal esta tarde, en el campamento de vacaciones.", "D'abord, qui et quand. Vous recherchez l'enfant réservé pour que le dossier soit lié à son compte, puis vous notez où cela s'est passé — ici, dans la grande salle de sport cet après-midi, au camp de vacances.", "Yn gyntaf, pwy a phryd. Rydych chi'n chwilio am y plentyn archebedig fel bod y cofnod yn cysylltu â'i gyfrif, yna'n nodi lle digwyddodd — yma, y brif neuadd chwaraeon y prynhawn yma yn y gwersyll gwyliau."],
  "lt_incidents_s4": ["Next, what happened, in plain factual words. Add the type and any witnesses, then tick the actions you took — a verbal reminder, a restorative chat, and a word with the parent at collection.", "Potem co się stało — prostymi, rzeczowymi słowami. Dodaj rodzaj i świadków, a potem zaznacz podjęte działania — słowne upomnienie, rozmowę naprawczą i rozmowę z rodzicem przy odbiorze.", "Apoi, ce s-a întâmplat, în cuvinte simple și factuale. Adaugă tipul și martorii, apoi bifează acțiunile pe care le-ai întreprins — o reamintire verbală, o discuție reparatorie și o discuție cu părintele la preluare.", "پھر کیا ہوا، سادہ اور حقائق پر مبنی الفاظ میں۔ نوعیت اور گواہ شامل کریں، پھر جو اقدامات کیے انہیں ٹک کریں — زبانی یاد دہانی، اصلاحی گفتگو، اور واپسی کے وقت والدین سے بات۔", "ਫਿਰ ਕੀ ਹੋਇਆ, ਸਾਦੇ ਤੱਥਾਂ ਵਾਲੇ ਸ਼ਬਦਾਂ ਵਿੱਚ। ਕਿਸਮ ਅਤੇ ਗਵਾਹ ਜੋੜੋ, ਫਿਰ ਜੋ ਕਾਰਵਾਈਆਂ ਕੀਤੀਆਂ ਉਨ੍ਹਾਂ ਨੂੰ ਟਿੱਕ ਕਰੋ — ਜ਼ੁਬਾਨੀ ਯਾਦ-ਦਹਾਨੀ, ਸੁਧਾਰਾਤਮਕ ਗੱਲਬਾਤ, ਅਤੇ ਲੈਣ ਵੇਲੇ ਮਾਪੇ ਨਾਲ ਗੱਲ।", "তারপর কী ঘটেছে, সহজ ও তথ্যভিত্তিক ভাষায়। ধরন ও সাক্ষী যোগ করুন, তারপর যে পদক্ষেপ নিয়েছেন তাতে টিক দিন — মৌখিক মনে করিয়ে দেওয়া, সংশোধনমূলক আলাপ এবং নেওয়ার সময় অভিভাবকের সঙ্গে কথা।", "بعد ذلك ما حدث، بكلمات بسيطة ووقائعية. أضِف النوع والشهود، ثم ضع علامة على الإجراءات التي اتخذتها — تنبيه شفهي، وحديث إصلاحي، وكلمة مع ولي الأمر عند الاستلام.", "Depois, o que aconteceu, em palavras simples e factuais. Acrescente o tipo e as testemunhas e assinale as ações que tomou — um lembrete verbal, uma conversa restaurativa e uma palavra com o pai ou a mãe na recolha.", "Luego, qué pasó, con palabras sencillas y objetivas. Añade el tipo y los testigos y marca las acciones que tomaste: un recordatorio verbal, una charla restaurativa y unas palabras con el padre o la madre en la recogida.", "Ensuite, ce qui s'est passé, en termes simples et factuels. Ajoutez le type et les témoins, puis cochez les mesures prises — un rappel verbal, un échange réparateur et un mot avec le parent à la récupération.", "Nesaf, beth ddigwyddodd, mewn geiriau plaen a ffeithiol. Ychwanegwch y math ac unrhyw dystion, yna ticiwch y camau a gymeroch — atgoffa ar lafar, sgwrs adferol, a gair â'r rhiant wrth gasglu."],
  "lt_incidents_s5": ["Now how serious it was and who sees it. This one is Moderate, and you choose to share it with the parent so it lands in their area, with a quick follow-up note to keep everyone on the same page.", "Teraz jak poważne to było i kto to widzi. Tu jest Umiarkowane i postanawiasz udostępnić je rodzicowi, żeby trafiło do jego panelu, z krótką notatką uzupełniającą, aby wszyscy byli na bieżąco.", "Acum, cât de grav a fost și cine o vede. Aceasta este Moderată și alegi să o împărtășești cu părintele, ca să ajungă în zona lui, cu o scurtă notă de urmărire ca toți să fie la curent.", "اب یہ کتنا سنگین تھا اور اسے کون دیکھے۔ یہ «درمیانہ» ہے، اور آپ اسے والدین کے ساتھ شیئر کرنے کا انتخاب کرتے ہیں تاکہ وہ ان کے حصے میں پہنچ جائے، اور ایک مختصر فالو اپ نوٹ کے ساتھ تاکہ سب کو خبر رہے۔", "ਹੁਣ ਇਹ ਕਿੰਨਾ ਗੰਭੀਰ ਸੀ ਅਤੇ ਇਸ ਨੂੰ ਕੌਣ ਵੇਖੇ। ਇਹ «ਦਰਮਿਆਨਾ» ਹੈ, ਅਤੇ ਤੁਸੀਂ ਇਸ ਨੂੰ ਮਾਪਿਆਂ ਨਾਲ ਸਾਂਝਾ ਕਰਨਾ ਚੁਣਦੇ ਹੋ ਤਾਂ ਜੋ ਇਹ ਉਨ੍ਹਾਂ ਦੇ ਖੇਤਰ ਵਿੱਚ ਪਹੁੰਚੇ, ਇੱਕ ਛੋਟੇ ਫਾਲੋ-ਅੱਪ ਨੋਟ ਨਾਲ ਤਾਂ ਜੋ ਸਭ ਨੂੰ ਪਤਾ ਰਹੇ।", "এবার এটি কতটা গুরুতর ছিল আর কে এটি দেখবে। এটি «মাঝারি», এবং আপনি এটি অভিভাবকের সঙ্গে শেয়ার করতে বেছে নেন যাতে তা তাঁদের এলাকায় পৌঁছায়, একটি ছোট ফলো-আপ নোটসহ যাতে সবাই একই বিষয় জানে।", "الآن مدى خطورة الأمر ومن يراه. هذه «متوسطة»، وتختار مشاركتها مع ولي الأمر لتصل إلى منطقته، مع ملاحظة متابعة قصيرة ليبقى الجميع على اطلاع.", "Agora, quão grave foi e quem vê. Esta é Moderada e escolhe partilhá-la com os pais para que chegue à sua área, com uma nota de acompanhamento rápida para manter todos a par.", "Ahora, qué gravedad tuvo y quién lo ve. Esta es Moderada y eliges compartirla con los padres para que llegue a su zona, con una breve nota de seguimiento para que todos estén al tanto.", "Maintenant, la gravité et qui le voit. Celle-ci est Modérée, et vous choisissez de la partager avec le parent pour qu'elle arrive dans son espace, avec une courte note de suivi pour que tout le monde soit au courant.", "Nawr pa mor ddifrifol oedd hi a phwy sy'n ei gweld. Cymedrol yw hon, ac rydych chi'n dewis ei rhannu gyda'r rhiant fel ei bod yn glanio yn ei ardal, gyda nodyn dilynol cyflym i gadw pawb ar yr un dudalen."],
  "lt_incidents_s6": ["Pressing Save record files it under the child. For a booked child the parent is emailed and notified automatically, with a timestamp, so nothing slips through.", "Naciśnięcie Zapisz wpis zapisuje go w karcie dziecka. W przypadku zarezerwowanego dziecka rodzic jest automatycznie powiadamiany e-mailem z godziną, więc nic nie umknie.", "Apăsarea pe Salvează înregistrarea o depune în fișa copilului. Pentru un copil rezervat, părintele primește automat e-mail și notificare, cu ora, ca nimic să nu scape.", "«ریکارڈ محفوظ کریں» دبانے سے یہ بچے کے ریکارڈ میں درج ہو جاتا ہے۔ بک بچے کے لیے والدین کو خود بخود ای میل اور اطلاع وقت کے ساتھ جاتی ہے، تاکہ کچھ چھوٹ نہ جائے۔", "«ਰਿਕਾਰਡ ਸੰਭਾਲੋ» ਦਬਾਉਣ ਨਾਲ ਇਹ ਬੱਚੇ ਦੇ ਰਿਕਾਰਡ ਵਿੱਚ ਦਰਜ ਹੋ ਜਾਂਦਾ ਹੈ। ਬੁਕ ਬੱਚੇ ਲਈ ਮਾਪਿਆਂ ਨੂੰ ਆਪਣੇ-ਆਪ ਸਮੇਂ ਸਮੇਤ ਈਮੇਲ ਤੇ ਸੂਚਨਾ ਜਾਂਦੀ ਹੈ, ਤਾਂ ਜੋ ਕੁਝ ਵੀ ਰਹਿ ਨਾ ਜਾਵੇ।", "«রেকর্ড সেভ করুন» চাপলে এটি শিশুর ফাইলে জমা হয়। বুক করা শিশুর ক্ষেত্রে অভিভাবককে সময়সহ স্বয়ংক্রিয়ভাবে ইমেইল ও বিজ্ঞপ্তি পাঠানো হয়, যাতে কিছুই বাদ না পড়ে।", "الضغط على «حفظ السجل» يضعه في ملف الطفل. وبالنسبة لطفل محجوز، يُرسَل إلى ولي الأمر بريد وإشعار تلقائيًا مع ختم الوقت، فلا يفوت شيء.", "Prima Guardar registo e fica arquivado na ficha da criança. Para uma criança reservada, o pai ou a mãe recebe automaticamente e-mail e notificação, com a hora, para que nada escape.", "Al pulsar Guardar registro, queda archivado en el expediente del niño. Si es un niño reservado, el padre o la madre recibe automáticamente un correo y una notificación, con la hora, para que no se escape nada.", "Appuyer sur Enregistrer le dossier le classe dans le dossier de l'enfant. Pour un enfant réservé, le parent reçoit automatiquement un e-mail et une notification, avec l'heure, pour que rien ne passe entre les mailles.", "Mae pwyso Cadw cofnod yn ei ffeilio o dan y plentyn. Ar gyfer plentyn archebedig mae'r rhiant yn cael e-bost a hysbysiad yn awtomatig, gyda stamp amser, fel nad oes dim yn llithro drwy'r rhwyd."],
  "lt_accidents_title": ["First aid", "Pierwsza pomoc", "Prim ajutor", "ابتدائی طبی امداد", "ਮੁੱਢਲੀ ਸਹਾਇਤਾ", "প্রাথমিক চিকিৎসা", "الإسعافات الأولية", "Primeiros socorros", "Primeros auxilios", "Premiers secours", "Cymorth cyntaf"],
  "lt_accidents_intro": ["This is your first aid log — record every bump and graze on the day, note the first aid you gave, and the parent is told automatically with a timestamp.", "To Twój dziennik pierwszej pomocy — zapisujesz każdy guz i otarcie tego dnia, notujesz udzieloną pierwszą pomoc, a rodzic jest automatycznie informowany z godziną.", "Acesta este jurnalul tău de prim ajutor — înregistrezi fiecare lovitură și zgârietură din ziua respectivă, notezi primul ajutor acordat, iar părintele este informat automat, cu ora.", "یہ آپ کا ابتدائی طبی امداد کا لاگ ہے — دن بھر ہر ٹکر اور خراش درج کریں، دی گئی ابتدائی امداد لکھیں، اور والدین کو وقت کے ساتھ خود بخود اطلاع مل جاتی ہے۔", "ਇਹ ਤੁਹਾਡਾ ਮੁੱਢਲੀ ਸਹਾਇਤਾ ਦਾ ਲਾਗ ਹੈ — ਦਿਨ ਦੀ ਹਰ ਸੱਟ ਅਤੇ ਖਰੋਂਚ ਦਰਜ ਕਰੋ, ਦਿੱਤੀ ਗਈ ਮੁੱਢਲੀ ਸਹਾਇਤਾ ਲਿਖੋ, ਅਤੇ ਮਾਪਿਆਂ ਨੂੰ ਸਮੇਂ ਸਮੇਤ ਆਪਣੇ-ਆਪ ਦੱਸ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ।", "এটি আপনার প্রাথমিক চিকিৎসার লগ — দিনের প্রতিটি আঘাত ও ছিলে যাওয়া নথিভুক্ত করুন, কী প্রাথমিক চিকিৎসা দিয়েছেন তা লিখুন, আর অভিভাবককে সময়সহ স্বয়ংক্রিয়ভাবে জানানো হয়।", "هذا هو سجل الإسعافات الأولية لديك — سجّل كل ارتطام وخدش في يومه، ودوّن الإسعاف الذي قدّمته، ويُبلَّغ ولي الأمر تلقائيًا مع ختم الوقت.", "Este é o seu registo de primeiros socorros — registe cada pancada e arranhão no próprio dia, anote os primeiros socorros prestados e os pais são informados automaticamente, com a hora.", "Este es tu registro de primeros auxilios: anota cada golpe y rasguño en el día, apunta los primeros auxilios que diste y el padre o la madre recibe el aviso automáticamente, con la hora.", "C'est votre journal de premiers secours — consignez chaque bosse et égratignure le jour même, notez les premiers soins donnés, et le parent est prévenu automatiquement, avec l'heure.", "Dyma'ch log cymorth cyntaf — cofnodwch bob cnoc a chrafiad ar y dydd, nodwch y cymorth cyntaf a roesoch, a chaiff y rhiant wybod yn awtomatig, gyda stamp amser."],
  "lt_accidents_done": ["And that's the whole loop — logged on the day, the parent told and able to acknowledge, with a tidy record kept behind every one.", "I to cały cykl — zapisane tego samego dnia, rodzic poinformowany i może potwierdzić, a za każdym wpisem uporządkowana dokumentacja.", "Și iată întregul circuit — înregistrat în aceeași zi, părintele informat și în măsură să confirme, cu o evidență ordonată în spatele fiecărui caz.", "اور یہ پورا دائرہ مکمل — اسی دن درج، والدین کو اطلاع اور وہ تسلیم کر سکتے ہیں، اور ہر ایک کے پیچھے صاف ستھرا ریکارڈ۔", "ਅਤੇ ਇਹ ਪੂਰਾ ਚੱਕਰ ਹੈ — ਉਸੇ ਦਿਨ ਦਰਜ, ਮਾਪਿਆਂ ਨੂੰ ਸੂਚਨਾ ਅਤੇ ਉਹ ਮੰਨ ਸਕਦੇ ਹਨ, ਅਤੇ ਹਰ ਇੱਕ ਪਿੱਛੇ ਸਾਫ਼-ਸੁਥਰਾ ਰਿਕਾਰਡ।", "আর এই হলো পুরো চক্র — সেদিনই নথিভুক্ত, অভিভাবককে জানানো ও তিনি স্বীকার করতে পারেন, এবং প্রতিটির পেছনে পরিপাটি রেকর্ড।", "وهذه هي الدورة كاملة — تُسجَّل في يومها، ويُبلَّغ ولي الأمر ويستطيع الإقرار بالاطلاع، مع سجل منظّم خلف كل حالة.", "E aí está o ciclo completo — registado no próprio dia, o pai ou a mãe informado e com possibilidade de confirmar, com um registo arrumado por trás de cada um.", "Y ahí tienes todo el ciclo: registrado en el día, el padre o la madre informado y en condiciones de confirmar, con un registro ordenado detrás de cada uno.", "Et voilà toute la boucle — consigné le jour même, le parent informé et en mesure d'accuser réception, avec un dossier soigné derrière chacun.", "A dyna'r ddolen gyfan — wedi'i logio ar y dydd, y rhiant wedi cael gwybod ac yn gallu cydnabod, gyda chofnod taclus y tu ôl i bob un."],
  "lt_accidents_s0": ["Your safety pulse at a glance — how many first aid records this month, how many were serious, how many parents you've told, and the running total.", "Twój puls bezpieczeństwa w skrócie — ile zapisów pierwszej pomocy w tym miesiącu, ile było poważnych, ilu rodziców poinformowałeś i łączna liczba.", "Pulsul siguranței tale dintr-o privire — câte înregistrări de prim ajutor luna aceasta, câte au fost grave, câți părinți ai informat și totalul cumulat.", "آپ کی حفاظت کی نبض ایک نظر میں — اس مہینے ابتدائی طبی امداد کے کتنے ریکارڈ، کتنے سنگین تھے، آپ نے کتنے والدین کو بتایا، اور مجموعی تعداد۔", "ਤੁਹਾਡੀ ਸੁਰੱਖਿਆ ਦੀ ਨਬਜ਼ ਇੱਕ ਨਜ਼ਰ ਵਿੱਚ — ਇਸ ਮਹੀਨੇ ਮੁੱਢਲੀ ਸਹਾਇਤਾ ਦੇ ਕਿੰਨੇ ਰਿਕਾਰਡ, ਕਿੰਨੇ ਗੰਭੀਰ ਸਨ, ਤੁਸੀਂ ਕਿੰਨੇ ਮਾਪਿਆਂ ਨੂੰ ਦੱਸਿਆ, ਅਤੇ ਕੁੱਲ ਗਿਣਤੀ।", "আপনার নিরাপত্তার নাড়ি এক নজরে — এ মাসে প্রাথমিক চিকিৎসার কয়টি রেকর্ড, কয়টি গুরুতর ছিল, কতজন অভিভাবককে জানিয়েছেন, এবং মোট সংখ্যা।", "نبض السلامة لديك في لمحة — كم سجل إسعاف أولي هذا الشهر، وكم منها خطير، وكم ولي أمر أبلغتَ، والإجمالي التراكمي.", "O pulso da sua segurança de relance — quantos registos de primeiros socorros este mês, quantos foram graves, quantos pais informou e o total acumulado.", "El pulso de tu seguridad de un vistazo: cuántos registros de primeros auxilios este mes, cuántos fueron graves, a cuántos padres has avisado y el total acumulado.", "Le pouls de votre sécurité en un coup d'œil — combien de dossiers de premiers secours ce mois-ci, combien étaient graves, combien de parents vous avez prévenus, et le total cumulé.", "Pwls eich diogelwch ar yr olwg gyntaf — faint o gofnodion cymorth cyntaf y mis hwn, faint oedd yn ddifrifol, faint o rieni rydych chi wedi'u hysbysu, a'r cyfanswm cronnol."],
  "lt_accidents_s1": ["This is the whole first aid loop on one page — every bump and graze logged on the day, kept for your records, and sent straight to the parent.", "To cały cykl pierwszej pomocy na jednej stronie — każdy guz i otarcie zapisane tego samego dnia, zachowane w dokumentacji i wysłane prosto do rodzica.", "Aceasta este întreaga buclă de prim ajutor pe o singură pagină — fiecare lovitură și zgârietură înregistrată în ziua respectivă, păstrată pentru evidențele tale și trimisă direct părintelui.", "یہ ابتدائی طبی امداد کا پورا دائرہ ایک صفحے پر ہے — ہر ٹکر اور خراش اسی دن درج، آپ کے ریکارڈ کے لیے محفوظ، اور سیدھی والدین کو بھیجی گئی۔", "ਇਹ ਮੁੱਢਲੀ ਸਹਾਇਤਾ ਦਾ ਪੂਰਾ ਚੱਕਰ ਇੱਕ ਪੰਨੇ ਉੱਤੇ ਹੈ — ਹਰ ਸੱਟ ਅਤੇ ਖਰੋਂਚ ਉਸੇ ਦਿਨ ਦਰਜ, ਤੁਹਾਡੇ ਰਿਕਾਰਡ ਲਈ ਸੰਭਾਲੀ ਗਈ, ਅਤੇ ਸਿੱਧੀ ਮਾਪਿਆਂ ਨੂੰ ਭੇਜੀ ਗਈ।", "এটি একটি পেজে পুরো প্রাথমিক চিকিৎসা চক্র — প্রতিটি আঘাত ও ছিলে যাওয়া সেদিনই নথিভুক্ত, আপনার রেকর্ডের জন্য সংরক্ষিত, এবং সরাসরি অভিভাবককে পাঠানো।", "هذه دورة الإسعافات الأولية كاملة في صفحة واحدة — كل ارتطام وخدش يُسجَّل في يومه، ويُحفَظ لسجلاتك، ويُرسَل مباشرة إلى ولي الأمر.", "Este é o ciclo completo de primeiros socorros numa só página — cada pancada e arranhão registado no próprio dia, guardado para os seus registos e enviado diretamente aos pais.", "Este es todo el ciclo de primeros auxilios en una sola página: cada golpe y rasguño anotado en el día, conservado para tus registros y enviado directamente a los padres.", "Voici toute la boucle des premiers secours sur une seule page — chaque bosse et égratignure consignée le jour même, conservée pour vos dossiers et envoyée directement au parent.", "Dyma'r ddolen cymorth cyntaf gyfan ar un dudalen — pob cnoc a chrafiad wedi'i logio ar y dydd, wedi'i gadw ar gyfer eich cofnodion a'i anfon yn syth at y rhiant."],
  "lt_accidents_s2": ["To add one, you press Log first aid, and this quick three-step form opens. Let me fill one in so you can watch it come together.", "Aby dodać wpis, naciskasz Zapisz pierwszą pomoc i otwiera się ten szybki trzyetapowy formularz. Wypełnię jeden, żebyś zobaczył, jak to przebiega.", "Pentru a adăuga una, apeși Înregistrează prim ajutor și se deschide acest formular rapid în trei pași. Voi completa unul ca să vezi cum prinde formă.", "اضافہ کرنے کے لیے آپ «ابتدائی طبی امداد درج کریں» دباتے ہیں، اور یہ تیز تین مرحلوں کا فارم کھلتا ہے۔ میں ایک بھر دیتا ہوں تاکہ آپ دیکھ سکیں کہ یہ کیسے بنتا ہے۔", "ਇੱਕ ਜੋੜਨ ਲਈ ਤੁਸੀਂ «ਮੁੱਢਲੀ ਸਹਾਇਤਾ ਦਰਜ ਕਰੋ» ਦਬਾਉਂਦੇ ਹੋ, ਅਤੇ ਇਹ ਤੇਜ਼ ਤਿੰਨ-ਪੜਾਅ ਫਾਰਮ ਖੁੱਲ੍ਹਦਾ ਹੈ। ਮੈਂ ਇੱਕ ਭਰ ਦਿੰਦਾ ਹਾਂ ਤਾਂ ਜੋ ਤੁਸੀਂ ਵੇਖ ਸਕੋ ਕਿ ਇਹ ਕਿਵੇਂ ਬਣਦਾ ਹੈ।", "একটি যোগ করতে আপনি «প্রাথমিক চিকিৎসা লগ করুন» চাপেন, আর এই দ্রুত তিন ধাপের ফর্মটি খোলে। আমি একটি পূরণ করে দেখাই, যাতে আপনি দেখতে পান এটি কীভাবে গড়ে ওঠে।", "لإضافة سجل، تضغط «تسجيل إسعاف أولي» فيُفتح هذا النموذج السريع ذو الخطوات الثلاث. سأملأ واحدًا لتشاهده يتشكّل.", "Para acrescentar um, prime Registar primeiros socorros e abre-se este formulário rápido de três passos. Vou preencher um para ver como fica.", "Para añadir uno, pulsas Registrar primeros auxilios y se abre este formulario rápido de tres pasos. Voy a rellenar uno para que veas cómo se va formando.", "Pour en ajouter un, vous appuyez sur Consigner un premier secours et ce formulaire rapide en trois étapes s'ouvre. J'en remplis un pour que vous le voyiez prendre forme.", "I ychwanegu un, pwyswch Logio cymorth cyntaf ac mae'r ffurflen tri cham gyflym hon yn agor. Gadewch i mi lenwi un i chi gael gwylio'n dod at ei gilydd."],
  "lt_accidents_s3": ["First, who and when. We pick Freya from the holiday camp register — you can only log against a booked child, as that's how it reaches the parent — then note it was the main hall, just after half two.", "Najpierw kto i kiedy. Wybieramy Freyę z rejestru obozu wakacyjnego — wpis można założyć tylko dla zarezerwowanego dziecka, bo tak dociera do rodzica — potem zaznaczamy, że to była główna sala, tuż po wpół do trzeciej.", "Mai întâi, cine și când. O alegem pe Freya din registrul taberei de vacanță — poți înregistra doar pentru un copil rezervat, pentru că așa ajunge la părinte — apoi notăm că a fost în sala principală, imediat după două și jumătate.", "پہلے کون اور کب۔ ہم چھٹیوں کے کیمپ کے رجسٹر سے فریا کو چنتے ہیں — آپ صرف بک بچے کے خلاف درج کر سکتے ہیں، کیونکہ اسی طرح یہ والدین تک پہنچتا ہے — پھر لکھتے ہیں کہ یہ مرکزی ہال میں تھا، ڈھائی بجے کے فوراً بعد۔", "ਪਹਿਲਾਂ ਕੌਣ ਤੇ ਕਦੋਂ। ਅਸੀਂ ਛੁੱਟੀਆਂ ਦੇ ਕੈਂਪ ਦੇ ਰਜਿਸਟਰ ਵਿੱਚੋਂ ਫ੍ਰੇਯਾ ਨੂੰ ਚੁਣਦੇ ਹਾਂ — ਤੁਸੀਂ ਸਿਰਫ਼ ਬੁਕ ਬੱਚੇ ਦੇ ਨਾਂ ਉੱਤੇ ਦਰਜ ਕਰ ਸਕਦੇ ਹੋ, ਕਿਉਂਕਿ ਇਸੇ ਤਰ੍ਹਾਂ ਇਹ ਮਾਪਿਆਂ ਤੱਕ ਪਹੁੰਚਦਾ ਹੈ — ਫਿਰ ਲਿਖਦੇ ਹਾਂ ਕਿ ਇਹ ਮੁੱਖ ਹਾਲ ਵਿੱਚ ਸੀ, ਢਾਈ ਵਜੇ ਤੋਂ ਠੀਕ ਬਾਅਦ।", "প্রথমে কে ও কখন। আমরা ছুটির ক্যাম্পের রেজিস্টার থেকে ফ্রেয়াকে বেছে নিই — আপনি শুধু বুক করা শিশুর নামেই লগ করতে পারেন, কারণ এভাবেই তা অভিভাবকের কাছে পৌঁছায় — তারপর লিখি এটি প্রধান হলে ছিল, আড়াইটার ঠিক পরে।", "أولًا من ومتى. نختار فريا من سجل مخيم العطلة — لا يمكنك التسجيل إلا لطفل محجوز، فبهذه الطريقة يصل الإشعار إلى ولي الأمر — ثم ندوّن أنه حدث في القاعة الرئيسية بعد الثانية والنصف مباشرة.", "Primeiro, quem e quando. Escolhemos a Freya do registo do campo de férias — só se pode registar para uma criança reservada, porque é assim que chega aos pais — e depois anotamos que foi no pavilhão principal, logo depois das duas e meia.", "Primero, quién y cuándo. Elegimos a Freya del registro del campamento de vacaciones (solo puedes anotar a un niño reservado, porque así le llega al padre o la madre) y luego anotamos que fue en el salón principal, justo después de las dos y media.", "D'abord, qui et quand. Nous choisissons Freya dans le registre du camp de vacances — on ne peut consigner que pour un enfant réservé, car c'est ainsi que cela parvient au parent — puis nous notons que c'était dans la grande salle, juste après deux heures et demie.", "Yn gyntaf, pwy a phryd. Rydyn ni'n dewis Freya o gofrestr y gwersyll gwyliau — dim ond yn erbyn plentyn archebedig y gallwch chi logio, gan mai dyna sut mae'n cyrraedd y rhiant — yna nodi mai'r brif neuadd oedd hi, ychydig ar ôl hanner awr wedi dau."],
  "lt_accidents_s4": ["Next, what happened, in plain and factual words. We write up the sports-day tumble, tag the injury as a grazed knee, and note Liberty as the first aider on shift.", "Potem co się stało, prostymi i rzeczowymi słowami. Opisujemy upadek podczas dnia sportu, oznaczamy uraz jako otarte kolano i wpisujemy Liberty jako pierwszą pomoc na dyżurze.", "Apoi, ce s-a întâmplat, în cuvinte simple și factuale. Scriem căderea din ziua sportului, etichetăm rana ca genunchi zdrelit și o notăm pe Liberty ca persoana de prim ajutor de serviciu.", "پھر کیا ہوا، سادہ اور حقائق پر مبنی الفاظ میں۔ ہم اسپورٹس ڈے میں گرنے کا احوال لکھتے ہیں، چوٹ کو چھلا ہوا گھٹنا ٹیگ کرتے ہیں، اور لبرٹی کو ڈیوٹی پر ابتدائی امداد دینے والی کے طور پر درج کرتے ہیں۔", "ਫਿਰ ਕੀ ਹੋਇਆ, ਸਾਦੇ ਤੱਥਾਂ ਵਾਲੇ ਸ਼ਬਦਾਂ ਵਿੱਚ। ਅਸੀਂ ਸਪੋਰਟਸ ਡੇ ਵਿੱਚ ਡਿੱਗਣ ਦਾ ਵੇਰਵਾ ਲਿਖਦੇ ਹਾਂ, ਸੱਟ ਨੂੰ ਛਿੱਲਿਆ ਗੋਡਾ ਟੈਗ ਕਰਦੇ ਹਾਂ, ਅਤੇ ਲਿਬਰਟੀ ਨੂੰ ਡਿਊਟੀ ਉੱਤੇ ਮੁੱਢਲੀ ਸਹਾਇਤਾ ਦੇਣ ਵਾਲੀ ਵਜੋਂ ਦਰਜ ਕਰਦੇ ਹਾਂ।", "তারপর কী ঘটেছে, সহজ ও তথ্যভিত্তিক ভাষায়। আমরা স্পোর্টস ডের পড়ে যাওয়ার বিবরণ লিখি, আঘাতটিকে ছিলে যাওয়া হাঁটু ট্যাগ করি, এবং লিবার্টিকে ডিউটিতে থাকা প্রাথমিক চিকিৎসাকারী হিসেবে লিখি।", "بعد ذلك ما حدث، بكلمات بسيطة ووقائعية. ندوّن سقطة يوم الرياضة، ونصنّف الإصابة «ركبة مخدوشة»، ونسجّل ليبرتي مسعِفةً مناوبة.", "Depois, o que aconteceu, em palavras simples e factuais. Descrevemos a queda no dia do desporto, etiquetamos a lesão como joelho esfolado e anotamos a Liberty como a socorrista de serviço.", "Luego, qué pasó, con palabras sencillas y objetivas. Redactamos el tropiezo en el día del deporte, etiquetamos la lesión como rodilla raspada y anotamos a Liberty como la socorrista de turno.", "Ensuite, ce qui s'est passé, en termes simples et factuels. Nous rédigeons la chute lors de la journée sportive, étiquetons la blessure comme genou écorché et notons Liberty comme secouriste de service.", "Nesaf, beth ddigwyddodd, mewn geiriau plaen a ffeithiol. Rydyn ni'n ysgrifennu'r codwm ar y diwrnod chwaraeon, yn tagio'r anaf fel pen-glin wedi'i grafu, ac yn nodi Liberty fel y cymorthwr cyntaf ar shifft."],
  "lt_accidents_s5": ["Because we've said grazed knee, it offers the right first aid to tick — we choose cleaned with water and covered with a plaster, and it's added to the record.", "Ponieważ wpisaliśmy otarte kolano, system podpowiada właściwą pierwszą pomoc do zaznaczenia — wybieramy przemyte wodą i zakryte plastrem, a to trafia do zapisu.", "Pentru că am spus genunchi zdrelit, ne oferă primul ajutor potrivit de bifat — alegem spălat cu apă și acoperit cu plasture, iar acesta se adaugă în înregistrare.", "چونکہ ہم نے چھلا ہوا گھٹنا کہا ہے، یہ مناسب ابتدائی امداد ٹک کرنے کے لیے پیش کرتا ہے — ہم «پانی سے صاف کیا اور پٹی لگائی» چنتے ہیں، اور یہ ریکارڈ میں شامل ہو جاتا ہے۔", "ਕਿਉਂਕਿ ਅਸੀਂ ਛਿੱਲਿਆ ਗੋਡਾ ਕਿਹਾ ਹੈ, ਇਹ ਟਿੱਕ ਕਰਨ ਲਈ ਸਹੀ ਮੁੱਢਲੀ ਸਹਾਇਤਾ ਪੇਸ਼ ਕਰਦਾ ਹੈ — ਅਸੀਂ «ਪਾਣੀ ਨਾਲ ਸਾਫ਼ ਕੀਤਾ ਅਤੇ ਪੱਟੀ ਲਾਈ» ਚੁਣਦੇ ਹਾਂ, ਅਤੇ ਇਹ ਰਿਕਾਰਡ ਵਿੱਚ ਜੁੜ ਜਾਂਦਾ ਹੈ।", "যেহেতু আমরা ছিলে যাওয়া হাঁটু বলেছি, এটি টিক দেওয়ার জন্য সঠিক প্রাথমিক চিকিৎসা দেখায় — আমরা «জল দিয়ে পরিষ্কার করে ব্যান্ডেজ দেওয়া হয়েছে» বেছে নিই, আর তা রেকর্ডে যুক্ত হয়।", "ولأننا ذكرنا «ركبة مخدوشة»، يعرض لنا الإسعاف المناسب لنضع عليه علامة — نختار «نُظِّفت بالماء وغُطِّيت بلاصق»، فيُضاف إلى السجل.", "Como indicámos joelho esfolado, oferece os primeiros socorros adequados para assinalar — escolhemos limpo com água e coberto com penso, e fica adicionado ao registo.", "Como hemos indicado rodilla raspada, ofrece los primeros auxilios adecuados para marcar: elegimos limpiada con agua y cubierta con una tirita, y se añade al registro.", "Comme nous avons indiqué genou écorché, il propose les bons premiers soins à cocher — nous choisissons nettoyé à l'eau et recouvert d'un pansement, et cela s'ajoute au dossier.", "Gan ein bod wedi dweud pen-glin wedi'i grafu, mae'n cynnig y cymorth cyntaf cywir i'w dicio — dewiswn wedi'i lanhau â dŵr a'i orchuddio â phlastr, ac fe'i hychwanegir at y cofnod."],
  "lt_accidents_s6": ["Last, how serious — this one's minor. We tick that we've had a quick word with the parent at pickup too, and jot a follow-up so nothing's forgotten.", "Na koniec jak poważne — to drobne. Zaznaczamy, że krótko porozmawialiśmy też z rodzicem przy odbiorze, i notujemy działanie następcze, żeby nic nie umknęło.", "În final, cât de grav — acesta este minor. Bifăm că am avut o scurtă discuție și cu părintele la preluare și notăm o acțiune de urmărire, ca să nu uităm nimic.", "آخر میں کتنا سنگین — یہ معمولی ہے۔ ہم ٹک کرتے ہیں کہ واپسی کے وقت والدین سے مختصر بات بھی ہوئی، اور ایک فالو اپ لکھ لیتے ہیں تاکہ کچھ بھولا نہ جائے۔", "ਅਖੀਰ ਵਿੱਚ ਕਿੰਨਾ ਗੰਭੀਰ — ਇਹ ਮਾਮੂਲੀ ਹੈ। ਅਸੀਂ ਟਿੱਕ ਕਰਦੇ ਹਾਂ ਕਿ ਲੈਣ ਵੇਲੇ ਮਾਪਿਆਂ ਨਾਲ ਵੀ ਛੋਟੀ ਗੱਲ ਹੋਈ, ਅਤੇ ਇੱਕ ਫਾਲੋ-ਅੱਪ ਲਿਖ ਲੈਂਦੇ ਹਾਂ ਤਾਂ ਜੋ ਕੁਝ ਭੁੱਲਿਆ ਨਾ ਜਾਵੇ।", "সবশেষে কতটা গুরুতর — এটি সামান্য। আমরা টিক দিই যে নেওয়ার সময় অভিভাবকের সঙ্গেও সংক্ষেপে কথা হয়েছে, আর একটি ফলো-আপ লিখে রাখি যাতে কিছু ভুলে না যাই।", "وأخيرًا مدى الخطورة — هذه بسيطة. نضع علامة على أننا تحدثنا بإيجاز مع ولي الأمر عند الاستلام أيضًا، ونكتب متابعة لئلا يُنسى شيء.", "Por fim, quão grave — esta é ligeira. Assinalamos que também falámos rapidamente com o pai ou a mãe na recolha e registamos um acompanhamento para que nada se esqueça.", "Por último, qué gravedad: esta es leve. Marcamos que también hemos hablado brevemente con el padre o la madre en la recogida y anotamos un seguimiento para que no se olvide nada.", "Enfin, la gravité — celle-ci est bénigne. Nous cochons que nous avons aussi eu un bref échange avec le parent à la récupération, et notons un suivi pour que rien ne soit oublié.", "Yn olaf, pa mor ddifrifol — mân yw hon. Rydyn ni'n ticio ein bod wedi cael gair cyflym â'r rhiant wrth gasglu hefyd, ac yn nodi gweithred ddilynol rhag anghofio dim."],
  "lt_accidents_s7": ["And that's it — press Save record and it's logged for good, with the parent emailed and notified in their own area, timestamped, ready to acknowledge.", "I gotowe — naciskasz Zapisz wpis i jest zapisany na stałe, a rodzic dostaje e-mail i powiadomienie w swoim panelu, z godziną, gotowe do potwierdzenia.", "Și gata — apeși Salvează înregistrarea și este consemnat definitiv, iar părintele primește e-mail și notificare în zona lui, cu ora, gata de confirmat.", "بس یہی — «ریکارڈ محفوظ کریں» دبائیں اور یہ ہمیشہ کے لیے درج ہو جاتا ہے، والدین کو ای میل اور ان کے اپنے حصے میں اطلاع وقت کے ساتھ ملتی ہے، تسلیم کرنے کے لیے تیار۔", "ਬੱਸ ਇਹੀ — «ਰਿਕਾਰਡ ਸੰਭਾਲੋ» ਦਬਾਓ ਅਤੇ ਇਹ ਪੱਕੇ ਤੌਰ ਉੱਤੇ ਦਰਜ ਹੋ ਜਾਂਦਾ ਹੈ, ਮਾਪਿਆਂ ਨੂੰ ਈਮੇਲ ਅਤੇ ਉਨ੍ਹਾਂ ਦੇ ਆਪਣੇ ਖੇਤਰ ਵਿੱਚ ਸੂਚਨਾ ਸਮੇਂ ਸਮੇਤ ਮਿਲਦੀ ਹੈ, ਮੰਨਣ ਲਈ ਤਿਆਰ।", "ব্যস — «রেকর্ড সেভ করুন» চাপুন আর এটি চিরতরে নথিভুক্ত হয়, অভিভাবক সময়সহ ইমেইল ও নিজের এলাকায় বিজ্ঞপ্তি পান, স্বীকার করার জন্য প্রস্তুত।", "وهذا كل شيء — اضغط «حفظ السجل» فيُسجَّل نهائيًا، ويصل ولي الأمر بريد وإشعار في منطقته مع ختم الوقت، جاهزًا للإقرار.", "E está feito — prima Guardar registo e fica registado em definitivo, com o pai ou a mãe a receber e-mail e notificação na sua área, com a hora, prontos para confirmar.", "Y ya está: pulsas Guardar registro y queda anotado definitivamente, con el padre o la madre recibiendo un correo y una notificación en su zona, con la hora, listos para confirmar.", "Et voilà — appuyez sur Enregistrer le dossier et il est consigné définitivement, le parent reçoit un e-mail et une notification dans son espace, avec l'heure, prêt à accuser réception.", "A dyna ni — pwyswch Cadw cofnod ac mae wedi'i logio am byth, gyda'r rhiant yn cael e-bost a hysbysiad yn ei ardal ei hun, gyda stamp amser, yn barod i gydnabod."],
  "lt_medication_title": ["Medication", "Leki", "Medicamente", "ادویات", "ਦਵਾਈਆਂ", "ওষুধ", "الأدوية", "Medicação", "Medicación", "Médicaments", "Meddyginiaeth"],
  "lt_medication_intro": ["This is where you keep every child's medicine safe and above board — a card for each child's medicine, the parent's written consent, and every single dose that's been given, all in one place.", "Tutaj trzymasz leki każdego dziecka w bezpieczeństwie i zgodnie z zasadami — karta dla leku każdego dziecka, pisemna zgoda rodzica i każda podana dawka, wszystko w jednym miejscu.", "Aici păstrezi medicamentele fiecărui copil în siguranță și în regulă — un card pentru fiecare medicament, consimțământul scris al părintelui și fiecare doză administrată, totul într-un singur loc.", "یہاں آپ ہر بچے کی دوا کو محفوظ اور قاعدے کے مطابق رکھتے ہیں — ہر بچے کی دوا کا ایک کارڈ، والدین کی تحریری رضامندی، اور دی گئی ہر ایک خوراک، سب ایک جگہ۔", "ਇੱਥੇ ਤੁਸੀਂ ਹਰ ਬੱਚੇ ਦੀ ਦਵਾਈ ਨੂੰ ਸੁਰੱਖਿਅਤ ਅਤੇ ਨਿਯਮਾਂ ਅਨੁਸਾਰ ਰੱਖਦੇ ਹੋ — ਹਰ ਬੱਚੇ ਦੀ ਦਵਾਈ ਲਈ ਇੱਕ ਕਾਰਡ, ਮਾਪਿਆਂ ਦੀ ਲਿਖਤੀ ਸਹਿਮਤੀ, ਅਤੇ ਦਿੱਤੀ ਗਈ ਹਰ ਖੁਰਾਕ, ਸਭ ਇੱਕ ਥਾਂ।", "এখানে আপনি প্রতিটি শিশুর ওষুধ নিরাপদ ও নিয়মমাফিক রাখেন — প্রতিটি শিশুর ওষুধের জন্য একটি কার্ড, অভিভাবকের লিখিত সম্মতি, এবং দেওয়া প্রতিটি ডোজ, সবকিছু এক জায়গায়।", "هنا تحفظ دواء كل طفل بأمان ووفق الأصول — بطاقة لدواء كل طفل، وموافقة ولي الأمر الخطية، وكل جرعة أُعطيت، كل ذلك في مكان واحد.", "É aqui que mantém os medicamentos de cada criança seguros e em ordem — um cartão para o medicamento de cada criança, o consentimento escrito dos pais e cada dose administrada, tudo num só lugar.", "Aquí mantienes los medicamentos de cada niño seguros y en regla: una ficha por cada medicamento, el consentimiento escrito de los padres y cada dosis administrada, todo en un solo lugar.", "C'est ici que vous gardez les médicaments de chaque enfant en sécurité et en règle — une fiche par médicament, le consentement écrit du parent et chaque dose administrée, le tout au même endroit.", "Dyma lle rydych chi'n cadw meddyginiaeth pob plentyn yn ddiogel ac yn gywir — cerdyn ar gyfer meddyginiaeth pob plentyn, caniatâd ysgrifenedig y rhiant, a phob dos a roddwyd, y cyfan mewn un lle."],
  "lt_medication_done": ["That's the full loop — consent captured, every dose logged with who gave it, and the parent kept in the picture, all held safely for safeguarding.", "To cały cykl — zgoda zebrana, każda dawka zapisana z informacją, kto ją podał, a rodzic na bieżąco, wszystko bezpiecznie przechowane dla potrzeb ochrony dzieci.", "Aceasta este întreaga buclă — consimțământ obținut, fiecare doză înregistrată cu cine a administrat-o, iar părintele ținut la curent, totul păstrat în siguranță pentru protecția copilului.", "یہ پورا دائرہ ہے — رضامندی حاصل، ہر خوراک کے ساتھ درج کہ کس نے دی، اور والدین کو باخبر رکھا گیا، سب کچھ تحفظِ اطفال کے لیے محفوظ۔", "ਇਹ ਪੂਰਾ ਚੱਕਰ ਹੈ — ਸਹਿਮਤੀ ਲਈ ਗਈ, ਹਰ ਖੁਰਾਕ ਦਰਜ ਕਿ ਕਿਸ ਨੇ ਦਿੱਤੀ, ਅਤੇ ਮਾਪਿਆਂ ਨੂੰ ਜਾਣੂ ਰੱਖਿਆ ਗਿਆ, ਸਭ ਕੁਝ ਬਾਲ ਸੁਰੱਖਿਆ ਲਈ ਸੁਰੱਖਿਅਤ ਰੱਖਿਆ ਗਿਆ।", "এটি পুরো চক্র — সম্মতি নেওয়া হয়েছে, প্রতিটি ডোজ কে দিয়েছেন তাসহ নথিভুক্ত, এবং অভিভাবক অবগত, সবকিছু সুরক্ষার জন্য নিরাপদে রাখা।", "هذه هي الدورة كاملة — أُخذت الموافقة، وسُجِّلت كل جرعة مع اسم من أعطاها، وبقي ولي الأمر على اطلاع، وكل ذلك محفوظ بأمان لأغراض حماية الطفل.", "É o ciclo completo — consentimento obtido, cada dose registada com quem a deu e o pai ou a mãe a par de tudo, guardado em segurança para a proteção de menores.", "Este es el ciclo completo: consentimiento obtenido, cada dosis registrada con quién la dio y los padres al tanto, todo guardado de forma segura para la protección infantil.", "Voilà toute la boucle — consentement recueilli, chaque dose consignée avec la personne qui l'a donnée, et le parent tenu informé, le tout conservé en sécurité pour la protection de l'enfance.", "Dyna'r ddolen gyfan — caniatâd wedi'i gasglu, pob dos wedi'i logio gyda phwy a'i rhoddodd, a'r rhiant yn cael gwybod, y cyfan wedi'i gadw'n ddiogel at ddibenion diogelu."],
  "lt_medication_s0": ["Four tiles give you the day's safety picture at a glance — how many medicines are on file, how many have the parent's consent, how many still need it, and how many doses have gone in today. Below them you can filter Active or Archived and search by child or medicine.", "Cztery kafelki pokazują dzienny obraz bezpieczeństwa — ile leków jest w kartotece, ile ma zgodę rodzica, ile jej jeszcze wymaga i ile dawek podano dzisiaj. Pod nimi możesz filtrować Aktywne lub Zarchiwizowane i szukać po dziecku lub leku.", "Patru casete îți dau imaginea zilnică a siguranței dintr-o privire — câte medicamente sunt în dosar, câte au consimțământul părintelui, câte îl mai cer și câte doze s-au administrat azi. Sub ele poți filtra Active sau Arhivate și căuta după copil sau medicament.", "چار ٹائلیں دن کی حفاظتی تصویر ایک نظر میں دیتی ہیں — فائل میں کتنی دوائیں ہیں، کتنی پر والدین کی رضامندی ہے، کتنی کو ابھی چاہیے، اور آج کتنی خوراکیں دی گئیں۔ ان کے نیچے آپ فعال یا محفوظ شدہ کو فلٹر کر سکتے ہیں اور بچے یا دوا کے نام سے تلاش کر سکتے ہیں۔", "ਚਾਰ ਟਾਈਲਾਂ ਦਿਨ ਦੀ ਸੁਰੱਖਿਆ ਦੀ ਤਸਵੀਰ ਇੱਕ ਨਜ਼ਰ ਵਿੱਚ ਦਿੰਦੀਆਂ ਹਨ — ਫਾਈਲ ਵਿੱਚ ਕਿੰਨੀਆਂ ਦਵਾਈਆਂ ਹਨ, ਕਿੰਨੀਆਂ ਉੱਤੇ ਮਾਪਿਆਂ ਦੀ ਸਹਿਮਤੀ ਹੈ, ਕਿੰਨੀਆਂ ਨੂੰ ਅਜੇ ਚਾਹੀਦੀ ਹੈ, ਅਤੇ ਅੱਜ ਕਿੰਨੀਆਂ ਖੁਰਾਕਾਂ ਦਿੱਤੀਆਂ ਗਈਆਂ। ਇਨ੍ਹਾਂ ਦੇ ਹੇਠਾਂ ਤੁਸੀਂ ਸਰਗਰਮ ਜਾਂ ਪੁਰਾਲੇਖ ਫਿਲਟਰ ਕਰ ਸਕਦੇ ਹੋ ਅਤੇ ਬੱਚੇ ਜਾਂ ਦਵਾਈ ਨਾਲ ਖੋਜ ਸਕਦੇ ਹੋ।", "চারটি টাইল দিনের নিরাপত্তার ছবি এক নজরে দেয় — ফাইলে কতগুলো ওষুধ আছে, কতগুলোতে অভিভাবকের সম্মতি আছে, কতগুলোর এখনও লাগবে, আর আজ কতটি ডোজ দেওয়া হয়েছে। এগুলোর নিচে সক্রিয় বা সংরক্ষাগারভুক্ত ফিল্টার করতে এবং শিশু বা ওষুধ দিয়ে খুঁজতে পারেন।", "تمنحك أربع بطاقات صورة السلامة لليوم في لمحة — كم دواءً مسجّلًا، وكم منها لديه موافقة ولي الأمر، وكم لا يزال بحاجة إليها، وكم جرعة أُعطيت اليوم. وتحتها يمكنك التصفية بين «النشطة» و«المؤرشفة» والبحث باسم الطفل أو الدواء.", "Quatro mosaicos dão-lhe o retrato da segurança do dia de relance — quantos medicamentos estão registados, quantos têm o consentimento dos pais, quantos ainda precisam dele e quantas doses foram dadas hoje. Por baixo pode filtrar Ativos ou Arquivados e pesquisar por criança ou medicamento.", "Cuatro tarjetas te dan la imagen de seguridad del día de un vistazo: cuántos medicamentos hay registrados, cuántos tienen el consentimiento de los padres, cuántos aún lo necesitan y cuántas dosis se han dado hoy. Debajo puedes filtrar Activos o Archivados y buscar por niño o medicamento.", "Quatre tuiles donnent l'image de la sécurité du jour d'un coup d'œil — combien de médicaments sont au dossier, combien ont le consentement du parent, combien l'attendent encore et combien de doses ont été données aujourd'hui. En dessous, vous pouvez filtrer Actifs ou Archivés et rechercher par enfant ou médicament.", "Mae pedwar teil yn rhoi darlun diogelwch y dydd i chi ar yr olwg gyntaf — faint o feddyginiaethau sydd ar ffeil, faint sydd â chaniatâd y rhiant, faint sydd ei angen o hyd, a faint o ddosau a roddwyd heddiw. O danynt gallwch hidlo Gweithredol neu Archif a chwilio yn ôl plentyn neu feddyginiaeth."],
  "lt_medication_s1": ["On any medicine that already has consent, you just tap Yes or No to log a dose against today and the current time, and the parent is told automatically. If you need to back-date it or add a note, open 'with time and notes' for the full form.", "Przy każdym leku, który ma już zgodę, wystarczy stuknąć Tak lub Nie, żeby zapisać dawkę na dziś i bieżącą godzinę, a rodzic dostaje powiadomienie automatycznie. Jeśli trzeba wpisać wsteczną datę lub dodać notatkę, otwórz „z godziną i notatkami”, żeby zobaczyć pełny formularz.", "Pe orice medicament care are deja consimțământ, atingi Da sau Nu pentru a înregistra o doză la data de azi și ora curentă, iar părintele este informat automat. Dacă trebuie să o datezi retroactiv sau să adaugi o notă, deschide «cu oră și note» pentru formularul complet.", "جس دوا کی رضامندی پہلے سے موجود ہو اس پر آپ صرف «ہاں» یا «نہیں» ٹیپ کر کے آج اور موجودہ وقت کی خوراک درج کرتے ہیں، اور والدین کو خود بخود اطلاع مل جاتی ہے۔ اگر پچھلی تاریخ ڈالنی ہو یا نوٹ لکھنا ہو تو مکمل فارم کے لیے «وقت اور نوٹس کے ساتھ» کھولیں۔", "ਜਿਸ ਦਵਾਈ ਦੀ ਸਹਿਮਤੀ ਪਹਿਲਾਂ ਹੀ ਹੈ, ਉਸ ਉੱਤੇ ਤੁਸੀਂ ਸਿਰਫ਼ «ਹਾਂ» ਜਾਂ «ਨਹੀਂ» ਟੈਪ ਕਰਕੇ ਅੱਜ ਅਤੇ ਮੌਜੂਦਾ ਸਮੇਂ ਦੀ ਖੁਰਾਕ ਦਰਜ ਕਰਦੇ ਹੋ, ਅਤੇ ਮਾਪਿਆਂ ਨੂੰ ਆਪਣੇ-ਆਪ ਸੂਚਨਾ ਮਿਲ ਜਾਂਦੀ ਹੈ। ਜੇ ਪਿਛਲੀ ਤਾਰੀਖ ਪਾਉਣੀ ਹੋਵੇ ਜਾਂ ਨੋਟ ਲਿਖਣਾ ਹੋਵੇ ਤਾਂ ਪੂਰੇ ਫਾਰਮ ਲਈ «ਸਮੇਂ ਅਤੇ ਨੋਟਾਂ ਸਮੇਤ» ਖੋਲ੍ਹੋ।", "যে ওষুধের সম্মতি আগে থেকেই আছে, তাতে শুধু «হ্যাঁ» বা «না» ট্যাপ করে আজকের ও বর্তমান সময়ের ডোজ নথিভুক্ত করেন, আর অভিভাবককে স্বয়ংক্রিয়ভাবে জানানো হয়। পেছনের তারিখ দিতে বা নোট যোগ করতে চাইলে পূর্ণ ফর্মের জন্য «সময় ও নোটসহ» খুলুন।", "على أي دواء لديه موافقة بالفعل، يكفي أن تضغط «نعم» أو «لا» لتسجيل جرعة بتاريخ اليوم والوقت الحالي، ويُبلَّغ ولي الأمر تلقائيًا. وإن احتجت إلى تسجيلها بتاريخ سابق أو إضافة ملاحظة فافتح «مع الوقت والملاحظات» للنموذج الكامل.", "Em qualquer medicamento que já tenha consentimento, basta tocar em Sim ou Não para registar uma dose com a data de hoje e a hora atual, e os pais são informados automaticamente. Se precisar de pôr uma data anterior ou acrescentar uma nota, abra «com hora e notas» para o formulário completo.", "En cualquier medicamento que ya tenga consentimiento, basta tocar Sí o No para registrar una dosis con la fecha de hoy y la hora actual, y los padres reciben el aviso automáticamente. Si necesitas poner una fecha anterior o añadir una nota, abre «con hora y notas» para el formulario completo.", "Sur tout médicament déjà couvert par un consentement, il suffit de toucher Oui ou Non pour consigner une dose à la date d'aujourd'hui et à l'heure actuelle, et le parent est prévenu automatiquement. Si vous devez antidater ou ajouter une note, ouvrez « avec l'heure et des notes » pour le formulaire complet.", "Ar unrhyw feddyginiaeth sydd eisoes â chaniatâd, dim ond tapio Ie neu Na sydd ei angen i logio dos yn erbyn heddiw a'r amser presennol, ac mae'r rhiant yn cael gwybod yn awtomatig. Os oes angen i chi ôl-ddyddio neu ychwanegu nodyn, agorwch «gydag amser a nodiadau» ar gyfer y ffurflen lawn."],
  "lt_medication_s2": ["Let's add a new one. You press the '＋ Administer a medication' button, and this three-step form opens up.", "Dodajmy nowy lek. Naciskasz przycisk „＋ Podaj lek” i otwiera się ten trzyetapowy formularz.", "Să adăugăm unul nou. Apeși butonul «＋ Administrează un medicament» și se deschide acest formular în trei pași.", "آئیے ایک نئی دوا شامل کرتے ہیں۔ آپ «＋ دوا دیں» کا بٹن دباتے ہیں، اور یہ تین مرحلوں کا فارم کھل جاتا ہے۔", "ਆਓ ਇੱਕ ਨਵੀਂ ਦਵਾਈ ਜੋੜੀਏ। ਤੁਸੀਂ «＋ ਦਵਾਈ ਦਿਓ» ਬਟਨ ਦਬਾਉਂਦੇ ਹੋ, ਅਤੇ ਇਹ ਤਿੰਨ-ਪੜਾਅ ਫਾਰਮ ਖੁੱਲ੍ਹ ਜਾਂਦਾ ਹੈ।", "চলুন নতুন একটি ওষুধ যোগ করি। আপনি «＋ ওষুধ দিন» বোতাম চাপেন, আর এই তিন ধাপের ফর্মটি খুলে যায়।", "لنُضِف دواءً جديدًا. تضغط على زر «＋ إعطاء دواء» فيُفتح هذا النموذج ذو الخطوات الثلاث.", "Vamos adicionar um novo. Prime o botão «＋ Administrar um medicamento» e abre-se este formulário de três passos.", "Vamos a añadir uno nuevo. Pulsas el botón «＋ Administrar un medicamento» y se abre este formulario de tres pasos.", "Ajoutons-en un nouveau. Vous appuyez sur le bouton « ＋ Administrer un médicament » et ce formulaire en trois étapes s'ouvre.", "Gadewch i ni ychwanegu un newydd. Pwyswch y botwm «＋ Rhoi meddyginiaeth» ac mae'r ffurflen tri cham hon yn agor."],
  "lt_medication_s3": ["First you pick the booked child. We'll type Ava Okafor and choose her from the list — she has to have a booking so the medicine links to her account and reaches her parent.", "Najpierw wybierasz zarezerwowane dziecko. Wpiszemy Ava Okafor i wybierzemy ją z listy — musi mieć rezerwację, żeby lek był powiązany z jej kontem i docierał do jej rodzica.", "Mai întâi alegi copilul rezervat. Vom tasta Ava Okafor și o vom alege din listă — trebuie să aibă rezervare, ca medicamentul să fie legat de contul ei și să ajungă la părintele ei.", "پہلے آپ بک بچے کو چنتے ہیں۔ ہم ایوا اوکافور ٹائپ کر کے فہرست سے اسے چنیں گے — اس کی بکنگ ہونا ضروری ہے تاکہ دوا اس کے اکاؤنٹ سے جڑے اور اس کے والدین تک پہنچے۔", "ਪਹਿਲਾਂ ਤੁਸੀਂ ਬੁਕ ਬੱਚੇ ਨੂੰ ਚੁਣਦੇ ਹੋ। ਅਸੀਂ ਆਵਾ ਓਕਾਫ਼ੋਰ ਟਾਈਪ ਕਰਕੇ ਸੂਚੀ ਵਿੱਚੋਂ ਉਸ ਨੂੰ ਚੁਣਾਂਗੇ — ਉਸ ਦੀ ਬੁਕਿੰਗ ਹੋਣੀ ਜ਼ਰੂਰੀ ਹੈ ਤਾਂ ਜੋ ਦਵਾਈ ਉਸ ਦੇ ਖਾਤੇ ਨਾਲ ਜੁੜੇ ਅਤੇ ਉਸ ਦੇ ਮਾਪਿਆਂ ਤੱਕ ਪਹੁੰਚੇ।", "প্রথমে আপনি বুক করা শিশুকে বেছে নেন। আমরা আভা ওকাফোর টাইপ করে তালিকা থেকে তাকে বেছে নেব — তার বুকিং থাকতে হবে, যাতে ওষুধটি তার অ্যাকাউন্টের সঙ্গে যুক্ত হয় এবং তার অভিভাবকের কাছে পৌঁছায়।", "أولًا تختار الطفل المحجوز. سنكتب «آفا أوكافور» ونختارها من القائمة — يجب أن يكون لديها حجز ليرتبط الدواء بحسابها ويصل إلى ولي أمرها.", "Primeiro escolhe a criança reservada. Vamos escrever Ava Okafor e escolhê-la na lista — tem de ter uma reserva para que o medicamento fique ligado à conta dela e chegue aos pais.", "Primero eliges al niño reservado. Escribiremos Ava Okafor y la elegiremos de la lista: tiene que tener una reserva para que el medicamento quede vinculado a su cuenta y llegue a sus padres.", "D'abord, vous choisissez l'enfant réservé. Nous allons taper Ava Okafor et la sélectionner dans la liste — elle doit avoir une réservation pour que le médicament soit lié à son compte et parvienne à son parent.", "Yn gyntaf rydych chi'n dewis y plentyn archebedig. Teipiwn Ava Okafor a'i dewis o'r rhestr — rhaid iddi fod â archeb fel bod y feddyginiaeth yn cysylltu â'i chyfrif ac yn cyrraedd ei rhiant."],
  "lt_medication_s4": ["Now the medicine itself — Ventolin, a dose of one puff, and what it's for, asthma. Then we press Next to move on to when staff should give it.", "Teraz sam lek — Ventolin, dawka jedno psiknięcie i na co — astma. Potem naciskamy Dalej, żeby przejść do tego, kiedy personel ma go podać.", "Acum medicamentul în sine — Ventolin, o doză de o pulverizare și pentru ce este — astm. Apoi apăsăm Înainte ca să trecem la momentul în care personalul ar trebui să-l administreze.", "اب دوا خود — وینٹولن، ایک پف کی خوراک، اور کس لیے ہے، دمہ۔ پھر ہم «آگے» دباتے ہیں تاکہ یہ طے ہو کہ عملہ اسے کب دے۔", "ਹੁਣ ਦਵਾਈ ਆਪ — ਵੈਂਟੋਲਿਨ, ਇੱਕ ਪਫ਼ ਦੀ ਖੁਰਾਕ, ਅਤੇ ਇਹ ਕਿਸ ਲਈ ਹੈ, ਦਮਾ। ਫਿਰ ਅਸੀਂ «ਅੱਗੇ» ਦਬਾਉਂਦੇ ਹਾਂ ਤਾਂ ਜੋ ਇਹ ਤੈਅ ਹੋਵੇ ਕਿ ਸਟਾਫ਼ ਇਹ ਕਦੋਂ ਦੇਵੇ।", "এবার ওষুধটি নিজেই — ভেন্টোলিন, এক পাফের ডোজ, আর এটি কীসের জন্য, হাঁপানি। তারপর «পরবর্তী» চাপি, যাতে কর্মীরা কখন দেবেন তা ঠিক হয়।", "الآن الدواء نفسه — فينتولين، جرعة نفخة واحدة، وسببه الربو. ثم نضغط «التالي» لننتقل إلى وقت إعطاء الموظفين له.", "Agora o medicamento em si — Ventolin, uma dose de uma inalação, e para que serve, asma. Depois prime-se Seguinte para passar a quando a equipa o deve dar.", "Ahora el medicamento en sí: Ventolin, una dosis de una inhalación y para qué sirve, asma. Luego pulsamos Siguiente para pasar a cuándo debe dárselo el personal.", "Maintenant le médicament lui-même — Ventolin, une dose d'une bouffée, et à quoi il sert, l'asthme. Puis nous appuyons sur Suivant pour passer au moment où le personnel doit le donner.", "Nawr y feddyginiaeth ei hun — Ventolin, dos o un pwff, a'r hyn y mae ar ei gyfer, asthma. Yna pwyswn Nesaf i symud ymlaen at pryd y dylai staff ei roi."],
  "lt_medication_s5": ["Step two is when and how. We'll choose 'On every booked day' so it's only offered on the days Ava is booked into the summer holiday camp, note where it's stored, and add the instructions for staff. Then Next.", "Krok drugi to kiedy i jak. Wybierzemy „W każdy zarezerwowany dzień”, żeby lek był oferowany tylko w dni, gdy Ava jest zapisana na letni obóz wakacyjny, zaznaczymy, gdzie jest przechowywany, i dodamy instrukcje dla personelu. Potem Dalej.", "Pasul doi este când și cum. Vom alege «În fiecare zi rezervată», ca să fie oferit doar în zilele în care Ava este înscrisă la tabăra de vară, vom nota unde este păstrat și vom adăuga instrucțiunile pentru personal. Apoi Înainte.", "دوسرا مرحلہ کب اور کیسے کا ہے۔ ہم «ہر بک دن» چنیں گے تاکہ یہ صرف ان دنوں دی جائے جب ایوا گرمیوں کی چھٹیوں کے کیمپ میں بک ہو، یہ بھی لکھیں گے کہ کہاں رکھی ہے، اور عملے کے لیے ہدایات شامل کریں گے۔ پھر «آگے»۔", "ਦੂਜਾ ਪੜਾਅ ਕਦੋਂ ਅਤੇ ਕਿਵੇਂ ਹੈ। ਅਸੀਂ «ਹਰ ਬੁਕ ਦਿਨ» ਚੁਣਾਂਗੇ ਤਾਂ ਜੋ ਇਹ ਸਿਰਫ਼ ਉਨ੍ਹਾਂ ਦਿਨਾਂ ਵਿੱਚ ਦਿੱਤੀ ਜਾਵੇ ਜਦੋਂ ਆਵਾ ਗਰਮੀਆਂ ਦੀਆਂ ਛੁੱਟੀਆਂ ਦੇ ਕੈਂਪ ਵਿੱਚ ਬੁਕ ਹੈ, ਲਿਖਾਂਗੇ ਕਿ ਇਹ ਕਿੱਥੇ ਰੱਖੀ ਹੈ, ਅਤੇ ਸਟਾਫ਼ ਲਈ ਹਦਾਇਤਾਂ ਜੋੜਾਂਗੇ। ਫਿਰ «ਅੱਗੇ»।", "দ্বিতীয় ধাপ কখন ও কীভাবে। আমরা «প্রতিটি বুক করা দিনে» বেছে নেব, যাতে এটি কেবল সেই দিনগুলোতেই দেওয়া হয় যেদিন আভা গ্রীষ্মকালীন ছুটির ক্যাম্পে বুক করা, কোথায় রাখা আছে তা লিখব, এবং কর্মীদের জন্য নির্দেশনা যোগ করব। তারপর «পরবর্তী»।", "الخطوة الثانية هي متى وكيف. سنختار «في كل يوم محجوز» ليُعرَض الدواء فقط في الأيام التي تكون فيها آفا محجوزة في مخيم عطلة الصيف، ونذكر مكان حفظه، ونضيف تعليمات الموظفين. ثم «التالي».", "O passo dois é quando e como. Escolhemos «Em todos os dias reservados», para que só seja oferecido nos dias em que a Ava está inscrita no campo de férias de verão, anotamos onde está guardado e acrescentamos as instruções para a equipa. Depois Seguinte.", "El paso dos es cuándo y cómo. Elegiremos «En cada día reservado» para que solo se ofrezca los días en que Ava está inscrita en el campamento de vacaciones de verano, anotaremos dónde se guarda y añadiremos las instrucciones para el personal. Luego Siguiente.", "L'étape deux, c'est quand et comment. Nous choisirons « Chaque jour réservé » pour qu'il ne soit proposé que les jours où Ava est inscrite au camp de vacances d'été, noterons où il est conservé et ajouterons les instructions pour le personnel. Puis Suivant.", "Cam dau yw pryd a sut. Dewiswn «Ar bob diwrnod archebedig» fel ei fod yn cael ei gynnig ar y dyddiau y mae Ava wedi'i harchebu ar y gwersyll gwyliau haf yn unig, nodi lle mae'n cael ei gadw, ac ychwanegu'r cyfarwyddiadau i staff. Yna Nesaf."],
  "lt_medication_s6": ["The last step is consent. We tick that the parent has given written consent — without it, no dose can ever be recorded — and that the medicine is held on site.", "Ostatni krok to zgoda. Zaznaczamy, że rodzic wyraził pisemną zgodę — bez niej żadna dawka nie może zostać zapisana — i że lek jest przechowywany na miejscu.", "Ultimul pas este consimțământul. Bifăm că părintele a dat consimțământ scris — fără el nu se poate înregistra nicio doză — și că medicamentul este păstrat în locație.", "آخری مرحلہ رضامندی کا ہے۔ ہم ٹک کرتے ہیں کہ والدین نے تحریری رضامندی دی ہے — اس کے بغیر کوئی خوراک درج نہیں ہو سکتی — اور یہ کہ دوا مقام پر رکھی گئی ہے۔", "ਆਖਰੀ ਪੜਾਅ ਸਹਿਮਤੀ ਦਾ ਹੈ। ਅਸੀਂ ਟਿੱਕ ਕਰਦੇ ਹਾਂ ਕਿ ਮਾਪਿਆਂ ਨੇ ਲਿਖਤੀ ਸਹਿਮਤੀ ਦਿੱਤੀ ਹੈ — ਇਸ ਤੋਂ ਬਿਨਾਂ ਕੋਈ ਖੁਰਾਕ ਦਰਜ ਨਹੀਂ ਹੋ ਸਕਦੀ — ਅਤੇ ਇਹ ਕਿ ਦਵਾਈ ਥਾਂ ਉੱਤੇ ਰੱਖੀ ਗਈ ਹੈ।", "শেষ ধাপ সম্মতি। আমরা টিক দিই যে অভিভাবক লিখিত সম্মতি দিয়েছেন — এটি ছাড়া কোনো ডোজ নথিভুক্ত করা যাবে না — এবং ওষুধটি সাইটে রাখা আছে।", "الخطوة الأخيرة هي الموافقة. نضع علامة على أن ولي الأمر أعطى موافقة خطية — فبدونها لا يمكن تسجيل أي جرعة — وعلى أن الدواء محفوظ في الموقع.", "O último passo é o consentimento. Assinalamos que o pai ou a mãe deu consentimento escrito — sem ele, nenhuma dose pode ser registada — e que o medicamento está guardado no local.", "El último paso es el consentimiento. Marcamos que el padre o la madre ha dado su consentimiento por escrito (sin él no se puede registrar ninguna dosis) y que el medicamento se guarda en el centro.", "La dernière étape est le consentement. Nous cochons que le parent a donné son consentement écrit — sans lui, aucune dose ne peut jamais être consignée — et que le médicament est conservé sur place.", "Y cam olaf yw caniatâd. Rydyn ni'n ticio bod y rhiant wedi rhoi caniatâd ysgrifenedig — hebddo, ni ellir cofnodi unrhyw ddos byth — a bod y feddyginiaeth yn cael ei chadw ar y safle."],
  "lt_medication_s7": ["Finally, pressing 'Save medication' creates the record — Ava's Ventolin now appears on the list with consent on file, ready for staff to log each dose safely.", "Na koniec naciśnięcie „Zapisz lek” tworzy zapis — Ventolin Avy pojawia się teraz na liście ze zgodą w aktach, gotowy, by personel bezpiecznie zapisywał każdą dawkę.", "În final, apăsarea pe «Salvează medicamentul» creează înregistrarea — Ventolinul Avei apare acum în listă, cu consimțământul în dosar, gata ca personalul să înregistreze în siguranță fiecare doză.", "آخر میں «دوا محفوظ کریں» دبانے سے ریکارڈ بن جاتا ہے — ایوا کا وینٹولن اب فہرست میں رضامندی کے ساتھ فائل پر نظر آتا ہے، عملے کے لیے ہر خوراک محفوظ طریقے سے درج کرنے کو تیار۔", "ਅਖੀਰ ਵਿੱਚ «ਦਵਾਈ ਸੰਭਾਲੋ» ਦਬਾਉਣ ਨਾਲ ਰਿਕਾਰਡ ਬਣ ਜਾਂਦਾ ਹੈ — ਆਵਾ ਦਾ ਵੈਂਟੋਲਿਨ ਹੁਣ ਸੂਚੀ ਵਿੱਚ ਸਹਿਮਤੀ ਫਾਈਲ ਸਮੇਤ ਦਿਸਦਾ ਹੈ, ਸਟਾਫ਼ ਵੱਲੋਂ ਹਰ ਖੁਰਾਕ ਸੁਰੱਖਿਅਤ ਦਰਜ ਕਰਨ ਲਈ ਤਿਆਰ।", "সবশেষে «ওষুধ সেভ করুন» চাপলে রেকর্ড তৈরি হয় — আভার ভেন্টোলিন এখন তালিকায় সম্মতিসহ ফাইলে দেখা যায়, কর্মীদের প্রতিটি ডোজ নিরাপদে নথিভুক্ত করার জন্য প্রস্তুত।", "وأخيرًا، الضغط على «حفظ الدواء» ينشئ السجل — يظهر فينتولين آفا الآن في القائمة مع الموافقة في الملف، جاهزًا ليسجّل الموظفون كل جرعة بأمان.", "Por fim, premir «Guardar medicamento» cria o registo — o Ventolin da Ava aparece agora na lista com o consentimento arquivado, pronto para a equipa registar cada dose em segurança.", "Por último, al pulsar «Guardar medicamento» se crea el registro: el Ventolin de Ava aparece ahora en la lista con el consentimiento archivado, listo para que el personal registre cada dosis con seguridad.", "Enfin, appuyer sur « Enregistrer le médicament » crée la fiche — le Ventolin d'Ava apparaît maintenant dans la liste avec le consentement au dossier, prêt pour que le personnel consigne chaque dose en toute sécurité.", "Yn olaf, mae pwyso «Cadw meddyginiaeth» yn creu'r cofnod — mae Ventolin Ava nawr yn ymddangos ar y rhestr gyda chaniatâd ar ffeil, yn barod i staff logio pob dos yn ddiogel."],
  "lt_moments_title": ["Moments", "Chwile", "Momente", "لمحات", "ਪਲ", "মুহূর্ত", "لحظات", "Momentos", "Momentos", "Moments", "Eiliadau"],
  "lt_moments_intro": ["Moments is where you share each child's day with their parents — the activities, little milestones and photos that land live in the family's own app.", "Chwile to miejsce, gdzie dzielisz się z rodzicami dniem każdego dziecka — zajęciami, małymi kamieniami milowymi i zdjęciami, które trafiają na żywo do aplikacji rodziny.", "Momente este locul unde împarți cu părinții ziua fiecărui copil — activitățile, micile reușite și fotografiile care ajung în direct în aplicația familiei.", "لمحات وہ جگہ ہے جہاں آپ ہر بچے کا دن اس کے والدین کے ساتھ شیئر کرتے ہیں — سرگرمیاں، چھوٹی کامیابیاں اور تصاویر جو خاندان کی اپنی ایپ میں براہِ راست پہنچتی ہیں۔", "ਪਲ ਉਹ ਥਾਂ ਹੈ ਜਿੱਥੇ ਤੁਸੀਂ ਹਰ ਬੱਚੇ ਦਾ ਦਿਨ ਉਸ ਦੇ ਮਾਪਿਆਂ ਨਾਲ ਸਾਂਝਾ ਕਰਦੇ ਹੋ — ਸਰਗਰਮੀਆਂ, ਨਿੱਕੀਆਂ ਪ੍ਰਾਪਤੀਆਂ ਅਤੇ ਤਸਵੀਰਾਂ ਜੋ ਪਰਿਵਾਰ ਦੀ ਆਪਣੀ ਐਪ ਵਿੱਚ ਸਿੱਧੀਆਂ ਪਹੁੰਚਦੀਆਂ ਹਨ।", "মুহূর্ত হলো সেই জায়গা যেখানে আপনি প্রতিটি শিশুর দিন তার অভিভাবকদের সঙ্গে শেয়ার করেন — কার্যক্রম, ছোট ছোট অর্জন এবং ছবি, যা সরাসরি পরিবারের নিজস্ব অ্যাপে পৌঁছে যায়।", "«لحظات» هي المكان الذي تشارك فيه يوم كل طفل مع أولياء أمره — الأنشطة والإنجازات الصغيرة والصور التي تصل مباشرة إلى تطبيق العائلة.", "Momentos é onde partilha o dia de cada criança com os pais — as atividades, os pequenos marcos e as fotografias que chegam em direto à aplicação da família.", "Momentos es donde compartes el día de cada niño con sus padres: las actividades, los pequeños hitos y las fotos que llegan en directo a la app de la familia.", "Moments est l'endroit où vous partagez la journée de chaque enfant avec ses parents — les activités, les petites étapes et les photos qui arrivent en direct dans l'application de la famille.", "Eiliadau yw lle rydych chi'n rhannu diwrnod pob plentyn gyda'u rhieni — y gweithgareddau, y cerrig milltir bach a'r lluniau sy'n glanio'n fyw yn ap y teulu eu hunain."],
  "lt_moments_done": ["And that's Moments — a lovely, safe way to keep parents right in the heart of their child's day.", "I to cały Chwile — piękny, bezpieczny sposób, by rodzice byli w samym sercu dnia swojego dziecka.", "Și gata cu Momentele — un mod frumos și sigur de a-i ține pe părinți chiar în inima zilei copilului lor.", "بس یہ تھا لمحات — والدین کو ان کے بچے کے دن کے عین مرکز میں رکھنے کا ایک خوبصورت اور محفوظ طریقہ۔", "ਬੱਸ ਇਹੀ ਹੈ ਪਲ — ਮਾਪਿਆਂ ਨੂੰ ਉਨ੍ਹਾਂ ਦੇ ਬੱਚੇ ਦੇ ਦਿਨ ਦੇ ਐਨ ਕੇਂਦਰ ਵਿੱਚ ਰੱਖਣ ਦਾ ਇੱਕ ਸੋਹਣਾ ਅਤੇ ਸੁਰੱਖਿਅਤ ਤਰੀਕਾ।", "মুহূর্ত এখানেই শেষ — অভিভাবকদের তাদের সন্তানের দিনের ঠিক কেন্দ্রে রাখার একটি সুন্দর ও নিরাপদ উপায়।", "وهذه هي «لحظات» — طريقة جميلة وآمنة لإبقاء أولياء الأمور في صميم يوم طفلهم.", "E é isto, os Momentos — uma forma bonita e segura de manter os pais no coração do dia do filho.", "Y eso es Momentos: una forma bonita y segura de mantener a los padres en el corazón del día de su hijo.", "Et voilà Moments — une belle façon, en toute sécurité, de garder les parents au cœur de la journée de leur enfant.", "A dyna Eiliadau — ffordd hyfryd a diogel o gadw rhieni yng nghanol diwrnod eu plentyn."],
  "lt_moments_s0": ["This is Moments — where you share each child's day with their parents. The activities, the little milestones and the photos all land live in the family's own app.", "To są Chwile — miejsce, gdzie dzielisz się z rodzicami dniem każdego dziecka. Zajęcia, małe kamienie milowe i zdjęcia trafiają na żywo do aplikacji rodziny.", "Acestea sunt Momentele — locul unde împarți cu părinții ziua fiecărui copil. Activitățile, micile reușite și fotografiile ajung în direct în aplicația familiei.", "یہ لمحات ہیں — جہاں آپ ہر بچے کا دن اس کے والدین کے ساتھ شیئر کرتے ہیں۔ سرگرمیاں، چھوٹی کامیابیاں اور تصاویر سب خاندان کی اپنی ایپ میں براہِ راست پہنچتی ہیں۔", "ਇਹ ਪਲ ਹਨ — ਜਿੱਥੇ ਤੁਸੀਂ ਹਰ ਬੱਚੇ ਦਾ ਦਿਨ ਉਸ ਦੇ ਮਾਪਿਆਂ ਨਾਲ ਸਾਂਝਾ ਕਰਦੇ ਹੋ। ਸਰਗਰਮੀਆਂ, ਨਿੱਕੀਆਂ ਪ੍ਰਾਪਤੀਆਂ ਅਤੇ ਤਸਵੀਰਾਂ ਸਭ ਪਰਿਵਾਰ ਦੀ ਆਪਣੀ ਐਪ ਵਿੱਚ ਸਿੱਧੀਆਂ ਪਹੁੰਚਦੀਆਂ ਹਨ।", "এটি মুহূর্ত — যেখানে আপনি প্রতিটি শিশুর দিন তার অভিভাবকদের সঙ্গে শেয়ার করেন। কার্যক্রম, ছোট ছোট অর্জন এবং ছবি সবই সরাসরি পরিবারের নিজস্ব অ্যাপে পৌঁছে যায়।", "هذه هي «لحظات» — حيث تشارك يوم كل طفل مع أولياء أمره. الأنشطة والإنجازات الصغيرة والصور كلها تصل مباشرة إلى تطبيق العائلة.", "Estes são os Momentos — onde partilha o dia de cada criança com os pais. As atividades, os pequenos marcos e as fotografias chegam em direto à aplicação da família.", "Esto es Momentos: donde compartes el día de cada niño con sus padres. Las actividades, los pequeños hitos y las fotos llegan en directo a la app de la familia.", "Voici Moments — l'endroit où vous partagez la journée de chaque enfant avec ses parents. Les activités, les petites étapes et les photos arrivent en direct dans l'application de la famille.", "Dyma Eiliadau — lle rydych chi'n rhannu diwrnod pob plentyn gyda'u rhieni. Mae'r gweithgareddau, y cerrig milltir bach a'r lluniau i gyd yn glanio'n fyw yn ap y teulu eu hunain."],
  "lt_moments_s1": ["Parents only ever see the moments their own child is in, and every photo files itself into the gallery automatically, ready to filter by child, by listing or by date.", "Rodzice widzą tylko te chwile, w których jest ich własne dziecko, a każde zdjęcie samo trafia do galerii, gotowe do filtrowania według dziecka, oferty lub daty.", "Părinții văd doar momentele în care apare propriul copil, iar fiecare fotografie se clasează singură în galerie, gata de filtrat după copil, ofertă sau dată.", "والدین صرف وہی لمحات دیکھتے ہیں جن میں ان کا اپنا بچہ ہو، اور ہر تصویر خود بخود گیلری میں محفوظ ہو جاتی ہے، بچے، لسٹنگ یا تاریخ کے مطابق فلٹر کرنے کو تیار۔", "ਮਾਪੇ ਸਿਰਫ਼ ਉਹੀ ਪਲ ਵੇਖਦੇ ਹਨ ਜਿਨ੍ਹਾਂ ਵਿੱਚ ਉਨ੍ਹਾਂ ਦਾ ਆਪਣਾ ਬੱਚਾ ਹੋਵੇ, ਅਤੇ ਹਰ ਤਸਵੀਰ ਆਪਣੇ-ਆਪ ਗੈਲਰੀ ਵਿੱਚ ਸੰਭਾਲੀ ਜਾਂਦੀ ਹੈ, ਬੱਚੇ, ਲਿਸਟਿੰਗ ਜਾਂ ਤਾਰੀਖ ਅਨੁਸਾਰ ਫਿਲਟਰ ਕਰਨ ਲਈ ਤਿਆਰ।", "অভিভাবকরা শুধু সেই মুহূর্তগুলোই দেখেন যেগুলোতে তাদের নিজের সন্তান আছে, আর প্রতিটি ছবি নিজে থেকেই গ্যালারিতে জমা হয়, শিশু, লিস্টিং বা তারিখ অনুযায়ী ফিল্টার করার জন্য প্রস্তুত।", "لا يرى أولياء الأمور سوى اللحظات التي يظهر فيها طفلهم، وتُحفَظ كل صورة في المعرض تلقائيًا، جاهزة للتصفية حسب الطفل أو العرض أو التاريخ.", "Os pais só veem os momentos em que o seu próprio filho aparece, e cada fotografia arquiva-se sozinha na galeria, pronta para filtrar por criança, oferta ou data.", "Los padres solo ven los momentos en los que aparece su propio hijo, y cada foto se archiva sola en la galería, lista para filtrar por niño, oferta o fecha.", "Les parents ne voient que les moments où figure leur propre enfant, et chaque photo se classe toute seule dans la galerie, prête à être filtrée par enfant, par offre ou par date.", "Dim ond yr eiliadau y mae eu plentyn eu hunain ynddynt y mae rhieni byth yn eu gweld, ac mae pob llun yn ffeilio ei hun yn yr oriel yn awtomatig, yn barod i'w hidlo yn ôl plentyn, rhestriad neu ddyddiad."],
  "lt_moments_s2": ["To add one, you press Share a moment, and this form opens.", "Aby dodać chwilę, naciskasz Udostępnij chwilę i otwiera się ten formularz.", "Pentru a adăuga una, apeși Partajează un moment și se deschide acest formular.", "ایک لمحہ شامل کرنے کے لیے آپ «لمحہ شیئر کریں» دباتے ہیں، اور یہ فارم کھل جاتا ہے۔", "ਇੱਕ ਪਲ ਜੋੜਨ ਲਈ ਤੁਸੀਂ «ਪਲ ਸਾਂਝਾ ਕਰੋ» ਦਬਾਉਂਦੇ ਹੋ, ਅਤੇ ਇਹ ਫਾਰਮ ਖੁੱਲ੍ਹ ਜਾਂਦਾ ਹੈ।", "একটি মুহূর্ত যোগ করতে আপনি «মুহূর্ত শেয়ার করুন» চাপেন, আর এই ফর্মটি খুলে যায়।", "لإضافة لحظة، تضغط «مشاركة لحظة» فيُفتح هذا النموذج.", "Para acrescentar um, prime Partilhar um momento e este formulário abre-se.", "Para añadir uno, pulsas Compartir un momento y se abre este formulario.", "Pour en ajouter un, vous appuyez sur Partager un moment et ce formulaire s'ouvre.", "I ychwanegu un, pwyswch Rhannu eiliad ac mae'r ffurflen hon yn agor."],
  "lt_moments_s3": ["First you pick the camp or club, and its booked children come through automatically. Then set the date — I'll pop it to the tenth of August.", "Najpierw wybierasz obóz lub kółko, a zapisane dzieci pojawiają się automatycznie. Potem ustaw datę — wpiszę dziesiąty sierpnia.", "Mai întâi alegi tabăra sau clubul, iar copiii rezervați apar automat. Apoi setează data — o voi pune pe 10 august.", "پہلے آپ کیمپ یا کلب چنتے ہیں، اور اس کے بک بچے خود بخود آ جاتے ہیں۔ پھر تاریخ طے کریں — میں اسے دس اگست پر رکھتا ہوں۔", "ਪਹਿਲਾਂ ਤੁਸੀਂ ਕੈਂਪ ਜਾਂ ਕਲੱਬ ਚੁਣਦੇ ਹੋ, ਅਤੇ ਉਸ ਦੇ ਬੁਕ ਬੱਚੇ ਆਪਣੇ-ਆਪ ਆ ਜਾਂਦੇ ਹਨ। ਫਿਰ ਤਾਰੀਖ ਤੈਅ ਕਰੋ — ਮੈਂ ਇਸ ਨੂੰ ਦਸ ਅਗਸਤ ਉੱਤੇ ਰੱਖਦਾ ਹਾਂ।", "প্রথমে আপনি ক্যাম্প বা ক্লাব বেছে নেন, আর তার বুক করা শিশুরা নিজে থেকেই চলে আসে। তারপর তারিখ ঠিক করুন — আমি এটি দশই আগস্ট করছি।", "أولًا تختار المخيم أو النادي، فيظهر أطفاله المحجوزون تلقائيًا. ثم حدّد التاريخ — سأضعه على العاشر من أغسطس.", "Primeiro escolhe o campo ou o clube e as crianças reservadas aparecem automaticamente. Depois defina a data — vou pô-la a 10 de agosto.", "Primero eliges el campamento o club, y sus niños reservados aparecen automáticamente. Luego fija la fecha: la pondré el diez de agosto.", "D'abord, vous choisissez le camp ou le club, et ses enfants réservés apparaissent automatiquement. Ensuite, réglez la date — je la mets au dix août.", "Yn gyntaf rydych chi'n dewis y gwersyll neu'r clwb, ac mae ei blant archebedig yn ymddangos yn awtomatig. Yna gosodwch y dyddiad — rhoddaf ef ar y degfed o Awst."],
  "lt_moments_s4": ["Next, choose whether it's a child photo or a photo of their work. A photo of their work has no faces, so it needs no consent — I'll pick that one.", "Potem wybierz, czy to zdjęcie dziecka, czy zdjęcie jego pracy. Zdjęcie pracy nie pokazuje twarzy, więc nie wymaga zgody — wybiorę właśnie takie.", "Apoi alege dacă este o fotografie cu copilul sau o fotografie cu lucrarea lui. O fotografie cu lucrarea nu are chipuri, deci nu necesită consimțământ — o voi alege pe aceasta.", "پھر چنیں کہ یہ بچے کی تصویر ہے یا اس کے کام کی تصویر۔ کام کی تصویر میں چہرے نہیں ہوتے، اس لیے رضامندی کی ضرورت نہیں — میں وہی چنتا ہوں۔", "ਫਿਰ ਚੁਣੋ ਕਿ ਇਹ ਬੱਚੇ ਦੀ ਤਸਵੀਰ ਹੈ ਜਾਂ ਉਸ ਦੇ ਕੰਮ ਦੀ। ਕੰਮ ਦੀ ਤਸਵੀਰ ਵਿੱਚ ਚਿਹਰੇ ਨਹੀਂ ਹੁੰਦੇ, ਇਸ ਲਈ ਸਹਿਮਤੀ ਦੀ ਲੋੜ ਨਹੀਂ — ਮੈਂ ਉਹੀ ਚੁਣਦਾ ਹਾਂ।", "তারপর বেছে নিন এটি শিশুর ছবি নাকি তার কাজের ছবি। কাজের ছবিতে মুখ থাকে না, তাই সম্মতির দরকার হয় না — আমি সেটিই বেছে নিচ্ছি।", "ثم اختر هل هي صورة للطفل أم صورة لعمله. صورة العمل لا تحتوي على وجوه، فلا تحتاج إلى موافقة — سأختار هذه.", "Depois escolha se é uma fotografia da criança ou do seu trabalho. Uma fotografia do trabalho não tem rostos, por isso não precisa de consentimento — vou escolher essa.", "Luego elige si es una foto del niño o de su trabajo. Una foto de su trabajo no tiene caras, así que no necesita consentimiento: elegiré esa.", "Choisissez ensuite s'il s'agit d'une photo de l'enfant ou de son travail. Une photo de son travail ne montre aucun visage, donc elle ne nécessite pas de consentement — je choisis celle-là.", "Nesaf, dewiswch ai llun o'r plentyn ydyw neu lun o'u gwaith. Nid oes wynebau mewn llun o'u gwaith, felly nid oes angen caniatâd — dewisaf yr un hwnnw."],
  "lt_moments_s5": ["Tag the activity so parents know what they got up to — let's say arts and crafts.", "Oznacz aktywność, żeby rodzice wiedzieli, co robiły dzieci — powiedzmy prace plastyczne.", "Etichetează activitatea ca părinții să știe ce au făcut — să zicem arte și meșteșuguri.", "سرگرمی کو ٹیگ کریں تاکہ والدین جان سکیں کہ بچوں نے کیا کیا — مثلاً آرٹس اینڈ کرافٹس۔", "ਸਰਗਰਮੀ ਨੂੰ ਟੈਗ ਕਰੋ ਤਾਂ ਜੋ ਮਾਪਿਆਂ ਨੂੰ ਪਤਾ ਲੱਗੇ ਕਿ ਬੱਚਿਆਂ ਨੇ ਕੀ ਕੀਤਾ — ਮੰਨ ਲਓ ਕਲਾ ਤੇ ਦਸਤਕਾਰੀ।", "কার্যক্রমটি ট্যাগ করুন যাতে অভিভাবকরা জানতে পারেন বাচ্চারা কী করেছে — ধরুন আঁকা ও হাতের কাজ।", "ضع وسمًا للنشاط ليعرف أولياء الأمور ما فعلوه — لنقل الفنون والأشغال اليدوية.", "Etiquete a atividade para que os pais saibam o que fizeram — digamos artes e ofícios.", "Etiqueta la actividad para que los padres sepan qué hicieron: digamos manualidades.", "Étiquetez l'activité pour que les parents sachent ce qu'ils ont fait — disons arts et loisirs créatifs.", "Tagiwch y gweithgaredd fel bod rhieni'n gwybod beth a wnaethon nhw — dyweder celf a chrefft."],
  "lt_moments_s6": ["Now jot down a quick highlight, or tap Write for me to draft it for you. I'll add a little note about their rocket.", "Teraz zanotuj krótkie wyróżnienie albo stuknij Napisz za mnie, żeby przygotować je za Ciebie. Dodam krótką uwagę o ich rakiecie.", "Acum notează un scurt moment de vârf sau atinge Scrie pentru mine ca să-l redactezi automat. Voi adăuga o mică notă despre racheta lor.", "اب ایک مختصر نمایاں بات لکھیں، یا «میرے لیے لکھیں» پر ٹیپ کریں تاکہ وہ آپ کے لیے مسودہ بنا دے۔ میں ان کے راکٹ کے بارے میں ایک چھوٹا سا نوٹ شامل کرتا ہوں۔", "ਹੁਣ ਇੱਕ ਛੋਟੀ ਖ਼ਾਸ ਗੱਲ ਲਿਖੋ, ਜਾਂ «ਮੇਰੇ ਲਈ ਲਿਖੋ» ਉੱਤੇ ਟੈਪ ਕਰੋ ਤਾਂ ਜੋ ਇਹ ਤੁਹਾਡੇ ਲਈ ਖਰੜਾ ਬਣਾ ਦੇਵੇ। ਮੈਂ ਉਨ੍ਹਾਂ ਦੇ ਰਾਕੇਟ ਬਾਰੇ ਇੱਕ ਨਿੱਕਾ ਨੋਟ ਜੋੜਦਾ ਹਾਂ।", "এবার একটি ছোট্ট উল্লেখযোগ্য কথা লিখুন, অথবা «আমার জন্য লিখুন»-এ ট্যাপ করুন যাতে এটি আপনার জন্য খসড়া করে দেয়। আমি তাদের রকেট নিয়ে একটি ছোট্ট নোট যোগ করছি।", "الآن دوّن ملخّصًا قصيرًا، أو اضغط «اكتب لي» ليصيغه لك. سأضيف ملاحظة صغيرة عن صاروخهم.", "Agora anote um breve destaque ou toque em Escrever por mim para que o rascunhe por si. Vou acrescentar uma pequena nota sobre o foguetão deles.", "Ahora anota un breve destacado o toca Escríbelo por mí para que lo redacte por ti. Añadiré una pequeña nota sobre su cohete.", "Notez maintenant un bref point fort, ou touchez Écrire pour moi pour qu'il le rédige à votre place. J'ajoute une petite note sur leur fusée.", "Nawr nodwch uchafbwynt cyflym, neu tapiwch Ysgrifennu i mi i'w ddrafftio i chi. Ychwanegaf nodyn bach am eu roced."],
  "lt_moments_s7": ["And that's it. Pressing Post moment shares it, notifies the tagged children's parents with a direct link, and files the photo in your gallery.", "I gotowe. Naciśnięcie Opublikuj chwilę udostępnia ją, powiadamia rodziców oznaczonych dzieci bezpośrednim linkiem i zapisuje zdjęcie w Twojej galerii.", "Și gata. Apăsarea pe Postează momentul îl partajează, îi notifică pe părinții copiilor etichetați cu un link direct și arhivează fotografia în galeria ta.", "بس یہی۔ «لمحہ پوسٹ کریں» دبانے سے یہ شیئر ہو جاتا ہے، ٹیگ کیے گئے بچوں کے والدین کو براہِ راست لنک کے ساتھ اطلاع جاتی ہے، اور تصویر آپ کی گیلری میں محفوظ ہو جاتی ہے۔", "ਬੱਸ ਇਹੀ। «ਪਲ ਪੋਸਟ ਕਰੋ» ਦਬਾਉਣ ਨਾਲ ਇਹ ਸਾਂਝਾ ਹੋ ਜਾਂਦਾ ਹੈ, ਟੈਗ ਕੀਤੇ ਬੱਚਿਆਂ ਦੇ ਮਾਪਿਆਂ ਨੂੰ ਸਿੱਧੇ ਲਿੰਕ ਨਾਲ ਸੂਚਨਾ ਜਾਂਦੀ ਹੈ, ਅਤੇ ਤਸਵੀਰ ਤੁਹਾਡੀ ਗੈਲਰੀ ਵਿੱਚ ਸੰਭਾਲੀ ਜਾਂਦੀ ਹੈ।", "ব্যস। «মুহূর্ত পোস্ট করুন» চাপলে তা শেয়ার হয়, ট্যাগ করা শিশুদের অভিভাবকদের সরাসরি লিংকসহ বিজ্ঞপ্তি যায়, আর ছবিটি আপনার গ্যালারিতে জমা হয়।", "وهذا كل شيء. الضغط على «نشر اللحظة» يشاركها، ويُخطِر أولياء أمور الأطفال الموسومين برابط مباشر، ويحفظ الصورة في معرضك.", "E está feito. Premir Publicar momento partilha-o, notifica os pais das crianças identificadas com uma ligação direta e arquiva a fotografia na sua galeria.", "Y ya está. Al pulsar Publicar momento se comparte, se avisa a los padres de los niños etiquetados con un enlace directo y se archiva la foto en tu galería.", "Et voilà. Appuyer sur Publier le moment le partage, prévient les parents des enfants identifiés avec un lien direct et classe la photo dans votre galerie.", "A dyna ni. Mae pwyso Postio eiliad yn ei rhannu, yn hysbysu rhieni'r plant sydd wedi'u tagio gyda dolen uniongyrchol, ac yn ffeilio'r llun yn eich oriel."],
  "lt_documents_title": ["Documents", "Dokumenty", "Documente", "دستاویزات", "ਦਸਤਾਵੇਜ਼", "নথি", "المستندات", "Documentos", "Documentos", "Documents", "Dogfennau"],
  "lt_documents_intro": ["This is your document store — one tidy place for the policies, risk assessments, insurance and certificates your setting needs, so the right paperwork is always a click away.", "To Twoje archiwum dokumentów — jedno uporządkowane miejsce na polityki, oceny ryzyka, ubezpieczenia i certyfikaty potrzebne Twojej placówce, żeby właściwe papiery były zawsze pod ręką.", "Acesta este depozitul tău de documente — un loc ordonat pentru politici, evaluări de risc, asigurări și certificate de care are nevoie locația ta, ca actele potrivite să fie mereu la un clic distanță.", "یہ آپ کا دستاویزات کا ذخیرہ ہے — پالیسیوں، خطرے کے جائزوں، انشورنس اور سرٹیفکیٹس کے لیے ایک صاف ستھری جگہ جن کی آپ کے ادارے کو ضرورت ہے، تاکہ درست کاغذات ہمیشہ ایک کلک پر ہوں۔", "ਇਹ ਤੁਹਾਡਾ ਦਸਤਾਵੇਜ਼ ਭੰਡਾਰ ਹੈ — ਨੀਤੀਆਂ, ਜੋਖਮ ਮੁਲਾਂਕਣਾਂ, ਬੀਮੇ ਅਤੇ ਸਰਟੀਫਿਕੇਟਾਂ ਲਈ ਇੱਕ ਸਾਫ਼-ਸੁਥਰੀ ਥਾਂ ਜਿਨ੍ਹਾਂ ਦੀ ਤੁਹਾਡੀ ਸੰਸਥਾ ਨੂੰ ਲੋੜ ਹੈ, ਤਾਂ ਜੋ ਸਹੀ ਕਾਗਜ਼ਾਤ ਹਮੇਸ਼ਾ ਇੱਕ ਕਲਿੱਕ ਦੂਰ ਹੋਣ।", "এটি আপনার নথি ভান্ডার — নীতিমালা, ঝুঁকি মূল্যায়ন, বিমা ও সনদের জন্য একটি পরিপাটি জায়গা যা আপনার প্রতিষ্ঠানের দরকার, যাতে সঠিক কাগজপত্র সবসময় এক ক্লিক দূরে থাকে।", "هذا هو مخزن مستنداتك — مكان واحد مرتّب للسياسات وتقييمات المخاطر والتأمين والشهادات التي يحتاجها مكانك، لتكون الأوراق المناسبة دائمًا على بُعد نقرة.", "Este é o seu arquivo de documentos — um lugar arrumado para as políticas, avaliações de risco, seguros e certificados de que o seu espaço precisa, para que a papelada certa esteja sempre a um clique.", "Este es tu almacén de documentos: un lugar ordenado para las políticas, evaluaciones de riesgos, seguros y certificados que necesita tu centro, de modo que el papeleo adecuado esté siempre a un clic.", "C'est votre espace de documents — un endroit bien rangé pour les politiques, évaluations des risques, assurances et certificats dont votre structure a besoin, afin que les bons papiers soient toujours à un clic.", "Dyma'ch storfa ddogfennau — un lle taclus ar gyfer y polisïau, yr asesiadau risg, yr yswiriant a'r tystysgrifau sydd eu hangen ar eich lleoliad, fel bod y gwaith papur cywir bob amser un clic i ffwrdd."],
  "lt_documents_done": ["And that's Documents — add a file or a link, tag it with a category, and it's saved to the shared list for your whole team to open any time.", "I to wszystko o Dokumentach — dodaj plik lub link, oznacz go kategorią, a zapisze się na wspólnej liście, którą Twój zespół może otworzyć w każdej chwili.", "Și gata cu Documentele — adaugi un fișier sau un link, îl etichetezi cu o categorie, iar se salvează în lista comună pe care întreaga echipă o poate deschide oricând.", "بس یہ تھا دستاویزات — فائل یا لنک شامل کریں، اسے زمرے سے ٹیگ کریں، اور وہ مشترکہ فہرست میں محفوظ ہو جاتا ہے جسے آپ کی پوری ٹیم کسی بھی وقت کھول سکتی ہے۔", "ਬੱਸ ਇਹੀ ਹੈ ਦਸਤਾਵੇਜ਼ — ਇੱਕ ਫਾਈਲ ਜਾਂ ਲਿੰਕ ਜੋੜੋ, ਇਸ ਨੂੰ ਸ਼੍ਰੇਣੀ ਨਾਲ ਟੈਗ ਕਰੋ, ਅਤੇ ਇਹ ਸਾਂਝੀ ਸੂਚੀ ਵਿੱਚ ਸੰਭਾਲਿਆ ਜਾਂਦਾ ਹੈ ਜਿਸ ਨੂੰ ਤੁਹਾਡੀ ਪੂਰੀ ਟੀਮ ਕਦੇ ਵੀ ਖੋਲ੍ਹ ਸਕਦੀ ਹੈ।", "নথি এখানেই শেষ — একটি ফাইল বা লিংক যোগ করুন, বিভাগ দিয়ে ট্যাগ করুন, আর এটি ভাগ করা তালিকায় সংরক্ষিত হয়, যা আপনার পুরো টিম যেকোনো সময় খুলতে পারে।", "وهذه هي «المستندات» — أضِف ملفًا أو رابطًا، ضع له فئة، فيُحفَظ في القائمة المشتركة ليفتحه فريقك كله في أي وقت.", "E é isto, os Documentos — adicione um ficheiro ou uma ligação, etiquete-o com uma categoria e fica guardado na lista partilhada para toda a equipa abrir quando quiser.", "Y eso es Documentos: añade un archivo o un enlace, etiquétalo con una categoría y se guarda en la lista compartida para que todo tu equipo lo abra cuando quiera.", "Et voilà Documents — ajoutez un fichier ou un lien, étiquetez-le avec une catégorie, et il est enregistré dans la liste partagée que toute votre équipe peut ouvrir à tout moment.", "A dyna Ddogfennau — ychwanegwch ffeil neu ddolen, tagiwch hi â chategori, ac mae'n cael ei chadw yn y rhestr a rennir i'ch tîm cyfan ei hagor unrhyw bryd."],
  "lt_documents_s0": ["This is your Documents page — one simple, shared place for all your setting's paperwork, with every file just a click from open.", "To Twoja strona Dokumentów — jedno proste, wspólne miejsce na całą dokumentację Twojej placówki, a każdy plik jest oddalony o jedno kliknięcie od otwarcia.", "Aceasta este pagina ta de Documente — un loc simplu și comun pentru toate actele locației tale, cu fiecare fișier la un clic distanță de deschidere.", "یہ آپ کا دستاویزات کا صفحہ ہے — آپ کے ادارے کے تمام کاغذات کے لیے ایک سادہ مشترکہ جگہ، جہاں ہر فائل کھولنے سے صرف ایک کلک دور ہے۔", "ਇਹ ਤੁਹਾਡਾ ਦਸਤਾਵੇਜ਼ ਪੰਨਾ ਹੈ — ਤੁਹਾਡੀ ਸੰਸਥਾ ਦੇ ਸਾਰੇ ਕਾਗਜ਼ਾਤ ਲਈ ਇੱਕ ਸਾਦੀ ਸਾਂਝੀ ਥਾਂ, ਜਿੱਥੇ ਹਰ ਫਾਈਲ ਖੋਲ੍ਹਣ ਤੋਂ ਸਿਰਫ਼ ਇੱਕ ਕਲਿੱਕ ਦੂਰ ਹੈ।", "এটি আপনার নথি পেজ — আপনার প্রতিষ্ঠানের সব কাগজপত্রের জন্য একটি সহজ, ভাগ করা জায়গা, যেখানে প্রতিটি ফাইল খুলতে মাত্র এক ক্লিক।", "هذه صفحة المستندات لديك — مكان واحد بسيط ومشترك لكل أوراق مكانك، وكل ملف على بُعد نقرة من فتحه.", "Esta é a sua página de Documentos — um só lugar simples e partilhado para toda a papelada do seu espaço, com cada ficheiro a um clique de abrir.", "Esta es tu página de Documentos: un lugar sencillo y compartido para todo el papeleo de tu centro, con cada archivo a un clic de abrirse.", "Voici votre page Documents — un endroit simple et partagé pour toute la paperasse de votre structure, chaque fichier étant à un clic de l'ouverture.", "Dyma'ch tudalen Dogfennau — un lle syml a rennir ar gyfer holl waith papur eich lleoliad, gyda phob ffeil un clic o fod ar agor."],
  "lt_documents_s1": ["Whether it's your after-school football club, a summer holiday camp or a weekly gymnastics class, the policies, risk assessments, insurance and certificates all live here in one running list.", "Czy to kółko piłkarskie po szkole, letni obóz wakacyjny czy cotygodniowe zajęcia gimnastyczne — polityki, oceny ryzyka, ubezpieczenia i certyfikaty mieszkają tu w jednej bieżącej liście.", "Fie că este clubul tău de fotbal după școală, o tabără de vară sau o oră săptămânală de gimnastică, politicile, evaluările de risc, asigurările și certificatele se află aici într-o singură listă continuă.", "چاہے وہ اسکول کے بعد کا فٹبال کلب ہو، گرمیوں کی چھٹیوں کا کیمپ ہو یا ہفتہ وار جمناسٹکس کلاس، پالیسیاں، خطرے کے جائزے، انشورنس اور سرٹیفکیٹس سب یہاں ایک جاری فہرست میں رہتے ہیں۔", "ਭਾਵੇਂ ਇਹ ਸਕੂਲ ਤੋਂ ਬਾਅਦ ਦਾ ਫੁੱਟਬਾਲ ਕਲੱਬ ਹੋਵੇ, ਗਰਮੀਆਂ ਦੀਆਂ ਛੁੱਟੀਆਂ ਦਾ ਕੈਂਪ ਜਾਂ ਹਫ਼ਤਾਵਾਰੀ ਜਿਮਨਾਸਟਿਕ ਕਲਾਸ, ਨੀਤੀਆਂ, ਜੋਖਮ ਮੁਲਾਂਕਣ, ਬੀਮਾ ਅਤੇ ਸਰਟੀਫਿਕੇਟ ਸਭ ਇੱਥੇ ਇੱਕ ਚੱਲਦੀ ਸੂਚੀ ਵਿੱਚ ਰਹਿੰਦੇ ਹਨ।", "তা স্কুলের পরের ফুটবল ক্লাব হোক, গ্রীষ্মের ছুটির ক্যাম্প হোক বা সাপ্তাহিক জিমন্যাস্টিকস ক্লাস, নীতিমালা, ঝুঁকি মূল্যায়ন, বিমা ও সনদ সবই এখানে একটি চলমান তালিকায় থাকে।", "سواء كان نادي كرة قدم بعد المدرسة أو مخيم عطلة صيفية أو حصة جمباز أسبوعية، فإن السياسات وتقييمات المخاطر والتأمين والشهادات تجتمع هنا في قائمة واحدة متواصلة.", "Seja o seu clube de futebol pós-escolar, um campo de férias de verão ou uma aula semanal de ginástica, as políticas, avaliações de risco, seguros e certificados vivem aqui numa única lista contínua.", "Ya sea tu club de fútbol extraescolar, un campamento de vacaciones de verano o una clase semanal de gimnasia, las políticas, evaluaciones de riesgos, seguros y certificados viven aquí en una única lista continua.", "Qu'il s'agisse de votre club de football après l'école, d'un camp de vacances d'été ou d'un cours hebdomadaire de gymnastique, les politiques, évaluations des risques, assurances et certificats vivent ici dans une seule liste continue.", "Boed yn glwb pêl-droed ar ôl ysgol, yn wersyll gwyliau haf neu'n ddosbarth gymnasteg wythnosol, mae'r polisïau, yr asesiadau risg, yr yswiriant a'r tystysgrifau i gyd yn byw yma mewn un rhestr barhaus."],
  "lt_documents_s2": ["Only company, freelancer or franchise accounts see this Add a document button and the delete cross. Everyone else on your team just reads and opens.", "Tylko konta firmowe, freelancerów i franczyz widzą przycisk Dodaj dokument i krzyżyk usuwania. Wszyscy pozostali w Twoim zespole tylko czytają i otwierają.", "Doar conturile de companie, freelancer sau franciză văd acest buton Adaugă un document și crucea de ștergere. Toți ceilalți din echipa ta doar citesc și deschid.", "صرف کمپنی، فری لانسر یا فرنچائز اکاؤنٹس کو یہ «دستاویز شامل کریں» بٹن اور حذف کا کراس نظر آتا ہے۔ آپ کی ٹیم کے باقی سب صرف پڑھتے اور کھولتے ہیں۔", "ਸਿਰਫ਼ ਕੰਪਨੀ, ਫ੍ਰੀਲਾਂਸਰ ਜਾਂ ਫ੍ਰੈਂਚਾਈਜ਼ ਖਾਤਿਆਂ ਨੂੰ ਇਹ «ਦਸਤਾਵੇਜ਼ ਜੋੜੋ» ਬਟਨ ਅਤੇ ਮਿਟਾਉਣ ਵਾਲਾ ਕਰਾਸ ਦਿਸਦਾ ਹੈ। ਤੁਹਾਡੀ ਟੀਮ ਦੇ ਬਾਕੀ ਸਭ ਸਿਰਫ਼ ਪੜ੍ਹਦੇ ਅਤੇ ਖੋਲ੍ਹਦੇ ਹਨ।", "শুধু কোম্পানি, ফ্রিল্যান্সার বা ফ্র্যাঞ্চাইজ অ্যাকাউন্টগুলোই এই «নথি যোগ করুন» বোতাম ও মুছে ফেলার ক্রস দেখতে পায়। আপনার টিমের বাকি সবাই শুধু পড়ে ও খোলে।", "لا يرى هذا الزر «إضافة مستند» وعلامة الحذف سوى حسابات الشركات والمستقلين والامتياز التجاري. أما بقية فريقك فيقرؤون ويفتحون فقط.", "Só as contas de empresa, freelancer ou franquia veem este botão Adicionar um documento e a cruz de eliminar. Todos os outros na sua equipa apenas leem e abrem.", "Solo las cuentas de empresa, autónomo o franquicia ven este botón Añadir un documento y la cruz de eliminar. El resto de tu equipo solo lee y abre.", "Seuls les comptes entreprise, indépendant ou franchise voient ce bouton Ajouter un document et la croix de suppression. Tous les autres membres de votre équipe ne peuvent que lire et ouvrir.", "Dim ond cyfrifon cwmni, llawrydd neu fasnachfraint sy'n gweld y botwm Ychwanegu dogfen hwn a'r groes ddileu. Mae pawb arall yn eich tîm yn darllen ac yn agor yn unig."],
  "lt_documents_s3": ["To add one, you press Add a document, and this form opens.", "Aby dodać dokument, naciskasz Dodaj dokument i otwiera się ten formularz.", "Pentru a adăuga unul, apeși Adaugă un document și se deschide acest formular.", "دستاویز شامل کرنے کے لیے آپ «دستاویز شامل کریں» دباتے ہیں، اور یہ فارم کھل جاتا ہے۔", "ਦਸਤਾਵੇਜ਼ ਜੋੜਨ ਲਈ ਤੁਸੀਂ «ਦਸਤਾਵੇਜ਼ ਜੋੜੋ» ਦਬਾਉਂਦੇ ਹੋ, ਅਤੇ ਇਹ ਫਾਰਮ ਖੁੱਲ੍ਹ ਜਾਂਦਾ ਹੈ।", "একটি নথি যোগ করতে আপনি «নথি যোগ করুন» চাপেন, আর এই ফর্মটি খুলে যায়।", "لإضافة مستند، تضغط «إضافة مستند» فيُفتح هذا النموذج.", "Para acrescentar um, prime Adicionar um documento e este formulário abre-se.", "Para añadir uno, pulsas Añadir un documento y se abre este formulario.", "Pour en ajouter un, vous appuyez sur Ajouter un document et ce formulaire s'ouvre.", "I ychwanegu un, pwyswch Ychwanegu dogfen ac mae'r ffurflen hon yn agor."],
  "lt_documents_s4": ["Give it a clear title. Here we'll type Autumn Half-Term Camp Risk Assessment, then pick its category from the dropdown, tagging this one as a risk assessment.", "Nadaj jasny tytuł. Tutaj wpiszemy Ocena ryzyka obozu w przerwie jesiennej, a potem wybierzemy kategorię z listy rozwijanej — oznaczymy ten jako ocenę ryzyka.", "Dă-i un titlu clar. Aici vom scrie Evaluarea de risc pentru tabăra din vacanța de toamnă, apoi vom alege categoria din lista derulantă, etichetându-l ca evaluare de risc.", "اسے ایک واضح عنوان دیں۔ یہاں ہم «خزاں کی آدھی چھٹی کے کیمپ کا خطرے کا جائزہ» ٹائپ کریں گے، پھر ڈراپ ڈاؤن سے اس کا زمرہ چنیں گے، اور اسے خطرے کے جائزے کے طور پر ٹیگ کریں گے۔", "ਇਸ ਨੂੰ ਇੱਕ ਸਾਫ਼ ਸਿਰਲੇਖ ਦਿਓ। ਇੱਥੇ ਅਸੀਂ «ਪਤਝੜ ਅੱਧ-ਮਿਆਦ ਕੈਂਪ ਜੋਖਮ ਮੁਲਾਂਕਣ» ਟਾਈਪ ਕਰਾਂਗੇ, ਫਿਰ ਡ੍ਰੌਪਡਾਊਨ ਵਿੱਚੋਂ ਇਸ ਦੀ ਸ਼੍ਰੇਣੀ ਚੁਣਾਂਗੇ, ਅਤੇ ਇਸ ਨੂੰ ਜੋਖਮ ਮੁਲਾਂਕਣ ਵਜੋਂ ਟੈਗ ਕਰਾਂਗੇ।", "একটি স্পষ্ট শিরোনাম দিন। এখানে আমরা «শরৎকালীন হাফ-টার্ম ক্যাম্পের ঝুঁকি মূল্যায়ন» লিখব, তারপর ড্রপডাউন থেকে এর বিভাগ বেছে নেব, এবং এটিকে ঝুঁকি মূল্যায়ন হিসেবে ট্যাগ করব।", "أعطِه عنوانًا واضحًا. سنكتب هنا «تقييم مخاطر مخيم عطلة منتصف الفصل في الخريف»، ثم نختار فئته من القائمة المنسدلة، ونصنّف هذا المستند «تقييم مخاطر».", "Dê-lhe um título claro. Aqui vamos escrever Avaliação de risco do campo da pausa do outono, depois escolher a categoria na lista, etiquetando este como avaliação de risco.", "Ponle un título claro. Aquí escribiremos Evaluación de riesgos del campamento de la semana de otoño, y luego elegiremos su categoría en el desplegable, etiquetando este como evaluación de riesgos.", "Donnez-lui un titre clair. Ici, nous taperons Évaluation des risques du camp des vacances de la Toussaint, puis choisirons sa catégorie dans la liste déroulante, en l'étiquetant comme évaluation des risques.", "Rhowch deitl clir iddo. Yma teipiwn Asesiad Risg Gwersyll Hanner Tymor yr Hydref, yna dewis ei gategori o'r gwymplen, gan dagio'r un hwn fel asesiad risg."],
  "lt_documents_s5": ["Now either choose a file to upload from your device, or simply paste a link. We'll paste the web address of the saved PDF.", "Teraz wybierz plik do przesłania z urządzenia albo po prostu wklej link. Wkleimy adres internetowy zapisanego pliku PDF.", "Acum alege fie un fișier de încărcat de pe dispozitiv, fie lipește pur și simplu un link. Vom lipi adresa web a PDF-ului salvat.", "اب یا تو اپنے آلے سے اپ لوڈ کرنے کے لیے فائل چنیں یا بس ایک لنک پیسٹ کریں۔ ہم محفوظ کردہ پی ڈی ایف کا ویب ایڈریس پیسٹ کریں گے۔", "ਹੁਣ ਜਾਂ ਤਾਂ ਆਪਣੇ ਡਿਵਾਈਸ ਤੋਂ ਅੱਪਲੋਡ ਕਰਨ ਲਈ ਫਾਈਲ ਚੁਣੋ ਜਾਂ ਸਿੱਧਾ ਇੱਕ ਲਿੰਕ ਪੇਸਟ ਕਰੋ। ਅਸੀਂ ਸੰਭਾਲੀ ਹੋਈ PDF ਦਾ ਵੈੱਬ ਪਤਾ ਪੇਸਟ ਕਰਾਂਗੇ।", "এবার আপনার ডিভাইস থেকে আপলোড করার জন্য একটি ফাইল বেছে নিন, অথবা শুধু একটি লিংক পেস্ট করুন। আমরা সংরক্ষিত পিডিএফের ওয়েব ঠিকানা পেস্ট করব।", "الآن إمّا أن تختار ملفًا لرفعه من جهازك أو تلصق رابطًا ببساطة. سنلصق عنوان الويب لملف PDF المحفوظ.", "Agora escolha um ficheiro para carregar do seu dispositivo ou simplesmente cole uma ligação. Vamos colar o endereço web do PDF guardado.", "Ahora elige un archivo para subir desde tu dispositivo o simplemente pega un enlace. Pegaremos la dirección web del PDF guardado.", "Choisissez maintenant un fichier à téléverser depuis votre appareil, ou collez simplement un lien. Nous collerons l'adresse web du PDF enregistré.", "Nawr dewiswch ffeil i'w huwchlwytho o'ch dyfais, neu gludwch ddolen yn syml. Gludwn gyfeiriad gwe'r PDF sydd wedi'i gadw."],
  "lt_documents_s6": ["An optional note adds context. We'll say it's been reviewed for the October half-term dates, for ages four to twelve.", "Opcjonalna notatka dodaje kontekst. Napiszemy, że został sprawdzony pod kątem terminów przerwy październikowej, dla dzieci w wieku od czterech do dwunastu lat.", "O notă opțională adaugă context. Vom scrie că a fost revizuit pentru datele vacanței de la mijlocul lui octombrie, pentru vârste de la patru la doisprezece ani.", "اختیاری نوٹ سیاق و سباق شامل کرتا ہے۔ ہم لکھیں گے کہ اس کا اکتوبر کی آدھی چھٹی کی تاریخوں کے لیے جائزہ لیا گیا ہے، چار سے بارہ سال کی عمر کے لیے۔", "ਇੱਕ ਵਿਕਲਪਿਕ ਨੋਟ ਸੰਦਰਭ ਜੋੜਦਾ ਹੈ। ਅਸੀਂ ਲਿਖਾਂਗੇ ਕਿ ਇਸ ਦੀ ਅਕਤੂਬਰ ਅੱਧ-ਮਿਆਦ ਦੀਆਂ ਤਾਰੀਖਾਂ ਲਈ ਸਮੀਖਿਆ ਹੋ ਚੁੱਕੀ ਹੈ, ਚਾਰ ਤੋਂ ਬਾਰਾਂ ਸਾਲ ਦੀ ਉਮਰ ਲਈ।", "একটি ঐচ্ছিক নোট প্রসঙ্গ যোগ করে। আমরা লিখব যে এটি অক্টোবরের হাফ-টার্মের তারিখের জন্য পর্যালোচিত হয়েছে, চার থেকে বারো বছর বয়সের জন্য।", "ملاحظة اختيارية تضيف سياقًا. سنكتب أنه روجع لمواعيد عطلة منتصف الفصل في أكتوبر، للأعمار من أربع إلى اثنتي عشرة سنة.", "Uma nota opcional acrescenta contexto. Vamos dizer que foi revisto para as datas da pausa de outubro, para idades dos quatro aos doze anos.", "Una nota opcional añade contexto. Diremos que se ha revisado para las fechas de la semana de octubre, para edades de cuatro a doce años.", "Une note facultative ajoute du contexte. Nous indiquerons qu'il a été revu pour les dates des vacances d'octobre, pour les âges de quatre à douze ans.", "Mae nodyn dewisol yn ychwanegu cyd-destun. Dywedwn ei fod wedi'i adolygu ar gyfer dyddiadau hanner tymor mis Hydref, ar gyfer oedrannau pedwar i ddeuddeg."],
  "lt_documents_s7": ["And that's it. Press Save, and the document lands in your shared list, tagged and ready for the whole team to open any time.", "I gotowe. Naciśnij Zapisz, a dokument trafia na Twoją wspólną listę, oznaczony i gotowy, by cały zespół mógł go otworzyć w każdej chwili.", "Și gata. Apasă Salvează, iar documentul ajunge în lista ta comună, etichetat și gata ca întreaga echipă să-l deschidă oricând.", "بس یہی۔ «محفوظ کریں» دبائیں، اور دستاویز آپ کی مشترکہ فہرست میں آ جاتی ہے، ٹیگ شدہ اور پوری ٹیم کے کسی بھی وقت کھولنے کے لیے تیار۔", "ਬੱਸ ਇਹੀ। «ਸੰਭਾਲੋ» ਦਬਾਓ, ਅਤੇ ਦਸਤਾਵੇਜ਼ ਤੁਹਾਡੀ ਸਾਂਝੀ ਸੂਚੀ ਵਿੱਚ ਆ ਜਾਂਦਾ ਹੈ, ਟੈਗ ਕੀਤਾ ਹੋਇਆ ਅਤੇ ਪੂਰੀ ਟੀਮ ਦੇ ਕਦੇ ਵੀ ਖੋਲ੍ਹਣ ਲਈ ਤਿਆਰ।", "ব্যস। «সেভ করুন» চাপুন, আর নথিটি আপনার ভাগ করা তালিকায় চলে আসে, ট্যাগ করা এবং পুরো টিমের যেকোনো সময় খোলার জন্য প্রস্তুত।", "وهذا كل شيء. اضغط «حفظ» فيصل المستند إلى قائمتك المشتركة، موسومًا وجاهزًا ليفتحه الفريق كله في أي وقت.", "E está feito. Prima Guardar e o documento aterra na sua lista partilhada, etiquetado e pronto para toda a equipa o abrir a qualquer momento.", "Y ya está. Pulsa Guardar y el documento llega a tu lista compartida, etiquetado y listo para que todo el equipo lo abra en cualquier momento.", "Et voilà. Appuyez sur Enregistrer, et le document arrive dans votre liste partagée, étiqueté et prêt à être ouvert par toute l'équipe à tout moment.", "A dyna ni. Pwyswch Cadw, ac mae'r ddogfen yn glanio yn eich rhestr a rennir, wedi'i thagio ac yn barod i'r tîm cyfan ei hagor unrhyw bryd."],
  "lt_finance_title": ["Finance and analytics", "Finanse i analityka", "Finanțe și analize", "مالیات اور تجزیات", "ਵਿੱਤ ਅਤੇ ਵਿਸ਼ਲੇਸ਼ਣ", "অর্থ ও বিশ্লেষণ", "المالية والتحليلات", "Finanças e análises", "Finanzas y analítica", "Finances et analyses", "Cyllid a dadansoddeg"],
  "lt_finance_intro": ["This is your money-and-analytics hub — one place to see what you've earned, what's still owed, when it lands in the bank, and who's actually booking.", "To Twoje centrum finansów i analityki — jedno miejsce, gdzie widzisz, ile zarobiłeś, ile jeszcze jest należne, kiedy trafi do banku i kto naprawdę rezerwuje.", "Acesta este centrul tău de bani și analize — un singur loc unde vezi cât ai câștigat, cât se mai datorează, când ajunge în bancă și cine rezervă de fapt.", "یہ آپ کا رقم اور تجزیات کا مرکز ہے — ایک ہی جگہ جہاں آپ دیکھتے ہیں کہ آپ نے کتنا کمایا، کتنا ابھی واجب الادا ہے، بینک میں کب پہنچے گا، اور دراصل بکنگ کون کر رہا ہے۔", "ਇਹ ਤੁਹਾਡਾ ਪੈਸੇ ਅਤੇ ਵਿਸ਼ਲੇਸ਼ਣ ਦਾ ਕੇਂਦਰ ਹੈ — ਇੱਕ ਥਾਂ ਜਿੱਥੇ ਤੁਸੀਂ ਵੇਖਦੇ ਹੋ ਕਿ ਕਿੰਨਾ ਕਮਾਇਆ, ਕਿੰਨਾ ਅਜੇ ਬਕਾਇਆ ਹੈ, ਬੈਂਕ ਵਿੱਚ ਕਦੋਂ ਪਹੁੰਚੇਗਾ, ਅਤੇ ਅਸਲ ਵਿੱਚ ਬੁਕਿੰਗ ਕੌਣ ਕਰ ਰਿਹਾ ਹੈ।", "এটি আপনার অর্থ ও বিশ্লেষণ কেন্দ্র — একটি জায়গায় দেখুন কত আয় করেছেন, কত এখনও বাকি, কখন ব্যাংকে পৌঁছাবে, আর আসলে কারা বুকিং করছে।", "هذا هو مركز المال والتحليلات لديك — مكان واحد ترى فيه ما كسبته، وما لا يزال مستحقًا، ومتى يصل إلى البنك، ومن يحجز فعلًا.", "Este é o seu centro de dinheiro e análises — um só lugar para ver o que ganhou, o que ainda é devido, quando chega ao banco e quem realmente está a reservar.", "Este es tu centro de dinero y analítica: un solo lugar para ver lo que has ganado, lo que aún se debe, cuándo llega al banco y quién reserva realmente.", "C'est votre centre d'argent et d'analyses — un seul endroit pour voir ce que vous avez gagné, ce qui reste dû, quand cela arrive en banque et qui réserve réellement.", "Dyma'ch canolfan arian a dadansoddeg — un lle i weld beth rydych chi wedi'i ennill, beth sy'n dal i fod yn ddyledus, pryd mae'n glanio yn y banc, a phwy sy'n archebu mewn gwirionedd."],
  "lt_finance_done": ["That's the whole money picture on one page — revenue, payouts, debts and demand, all moving together with your chosen window.", "To cały obraz finansów na jednej stronie — przychody, wypłaty, zaległości i popyt, wszystko porusza się razem z wybranym przez Ciebie okresem.", "Aceasta este întreaga imagine financiară pe o singură pagină — venituri, plăți, datorii și cerere, toate mișcându-se împreună cu intervalul ales de tine.", "یہ پورا مالی منظر ایک صفحے پر ہے — آمدنی، ادائیگیاں، قرضے اور طلب، سب آپ کی منتخب کردہ مدت کے ساتھ ساتھ بدلتے ہیں۔", "ਇਹ ਪੂਰੀ ਪੈਸੇ ਦੀ ਤਸਵੀਰ ਇੱਕ ਪੰਨੇ ਉੱਤੇ ਹੈ — ਆਮਦਨ, ਅਦਾਇਗੀਆਂ, ਬਕਾਏ ਅਤੇ ਮੰਗ, ਸਭ ਤੁਹਾਡੀ ਚੁਣੀ ਹੋਈ ਮਿਆਦ ਦੇ ਨਾਲ ਇਕੱਠੇ ਬਦਲਦੇ ਹਨ।", "এটি এক পেজে পুরো অর্থের চিত্র — আয়, পেআউট, বকেয়া ও চাহিদা, সবকিছু আপনার বেছে নেওয়া সময়সীমার সঙ্গে একসাথে নড়ে।", "هذه هي الصورة المالية كاملة في صفحة واحدة — الإيرادات والمدفوعات والديون والطلب، كلها تتحرك معًا مع النطاق الزمني الذي اخترته.", "Este é o retrato financeiro completo numa só página — receitas, pagamentos, dívidas e procura, tudo a mover-se em conjunto com o período que escolheu.", "Este es todo el panorama del dinero en una sola página: ingresos, pagos, deudas y demanda, todo moviéndose a la vez según el periodo que elijas.", "Voici toute la situation financière sur une seule page — revenus, versements, impayés et demande, le tout évoluant ensemble selon la période choisie.", "Dyna'r darlun ariannol cyfan ar un dudalen — refeniw, taliadau, dyledion a galw, y cyfan yn symud gyda'i gilydd gyda'r cyfnod rydych chi wedi'i ddewis."],
  "lt_finance_s0": ["Pick a window at the top — three, six or twelve months — and every figure on the page recalculates, with the five tabs simply slicing that same data different ways.", "Wybierz okres u góry — trzy, sześć lub dwanaście miesięcy — a każda liczba na stronie zostanie przeliczona, a pięć kart po prostu pokazuje te same dane na różne sposoby.", "Alege un interval sus — trei, șase sau douăsprezece luni — și fiecare cifră de pe pagină se recalculează, cele cinci file împărțind pur și simplu aceleași date în moduri diferite.", "اوپر مدت چنیں — تین، چھ یا بارہ مہینے — اور صفحے کی ہر رقم دوبارہ شمار ہو جاتی ہے، جبکہ پانچ ٹیب اسی ڈیٹا کو مختلف انداز میں کاٹ کر دکھاتے ہیں۔", "ਉੱਪਰ ਮਿਆਦ ਚੁਣੋ — ਤਿੰਨ, ਛੇ ਜਾਂ ਬਾਰਾਂ ਮਹੀਨੇ — ਅਤੇ ਪੰਨੇ ਦਾ ਹਰ ਅੰਕੜਾ ਦੁਬਾਰਾ ਗਿਣਿਆ ਜਾਂਦਾ ਹੈ, ਜਦਕਿ ਪੰਜ ਟੈਬ ਉਸੇ ਡੇਟਾ ਨੂੰ ਵੱਖ-ਵੱਖ ਢੰਗਾਂ ਨਾਲ ਵੰਡ ਕੇ ਵਿਖਾਉਂਦੇ ਹਨ।", "ওপরে সময়সীমা বেছে নিন — তিন, ছয় বা বারো মাস — আর পেজের প্রতিটি সংখ্যা আবার গণনা হয়, পাঁচটি ট্যাব কেবল একই তথ্যকে ভিন্নভাবে ভাগ করে দেখায়।", "اختر نطاقًا زمنيًا في الأعلى — ثلاثة أو ستة أو اثني عشر شهرًا — فيُعاد احتساب كل رقم في الصفحة، بينما تعرض التبويبات الخمسة البيانات نفسها بطرق مختلفة.", "Escolha um período no topo — três, seis ou doze meses — e cada valor da página é recalculado, com os cinco separadores a cortar os mesmos dados de formas diferentes.", "Elige un periodo arriba (tres, seis o doce meses) y cada cifra de la página se recalcula, con las cinco pestañas simplemente cortando esos mismos datos de distintas formas.", "Choisissez une période en haut — trois, six ou douze mois — et chaque chiffre de la page est recalculé, les cinq onglets découpant simplement les mêmes données de différentes façons.", "Dewiswch ffenestr ar y brig — tri, chwe neu ddeuddeg mis — ac mae pob ffigur ar y dudalen yn ailgyfrifo, gyda'r pum tab yn syml yn sleisio'r un data mewn ffyrdd gwahanol."],
  "lt_finance_s1": ["The headline tiles show collected against booked, what's still owed and what reaches your bank after fees, with a trend line and a sources donut just below.", "Główne kafelki pokazują pobrane środki w porównaniu z zarezerwowanymi, to, co jeszcze należne, i to, co trafia do banku po opłatach, a tuż pod nimi linia trendu i wykres kołowy źródeł.", "Casetele principale arată încasatul față de rezervat, ce se mai datorează și ce ajunge în banca ta după comisioane, cu o linie de tendință și un grafic circular al surselor chiar dedesubt.", "اہم ٹائلیں وصول شدہ بمقابلہ بک کی گئی رقم، جو ابھی واجب الادا ہے، اور فیس کے بعد آپ کے بینک میں کیا پہنچتا ہے دکھاتی ہیں، اور ان کے ٹھیک نیچے رجحان کی لکیر اور ذرائع کا ڈونٹ چارٹ ہے۔", "ਮੁੱਖ ਟਾਈਲਾਂ ਵਸੂਲ ਕੀਤੀ ਬਨਾਮ ਬੁਕ ਕੀਤੀ ਰਕਮ, ਜੋ ਅਜੇ ਬਕਾਇਆ ਹੈ, ਅਤੇ ਫੀਸਾਂ ਤੋਂ ਬਾਅਦ ਤੁਹਾਡੇ ਬੈਂਕ ਵਿੱਚ ਕੀ ਪਹੁੰਚਦਾ ਹੈ ਦਿਖਾਉਂਦੀਆਂ ਹਨ, ਅਤੇ ਇਨ੍ਹਾਂ ਦੇ ਠੀਕ ਹੇਠਾਂ ਰੁਝਾਨ ਲਕੀਰ ਅਤੇ ਸਰੋਤਾਂ ਦਾ ਡੋਨਟ ਚਾਰਟ ਹੈ।", "প্রধান টাইলগুলো দেখায় সংগৃহীত বনাম বুক করা অর্থ, এখনও কত বাকি, এবং ফির পর আপনার ব্যাংকে কত পৌঁছায়, আর ঠিক নিচে আছে প্রবণতার রেখা ও উৎসের ডোনাট চার্ট।", "تعرض البطاقات الرئيسية المحصَّل مقابل المحجوز، وما لا يزال مستحقًا، وما يصل إلى بنكك بعد الرسوم، مع خط اتجاه ومخطط دائري للمصادر أسفلها مباشرة.", "Os mosaicos principais mostram o cobrado face ao reservado, o que ainda é devido e o que chega ao seu banco depois das comissões, com uma linha de tendência e um gráfico circular das fontes logo abaixo.", "Las tarjetas principales muestran lo cobrado frente a lo reservado, lo que aún se debe y lo que llega a tu banco tras las comisiones, con una línea de tendencia y un gráfico de anillo de fuentes justo debajo.", "Les tuiles principales affichent l'encaissé par rapport au réservé, ce qui reste dû et ce qui arrive sur votre compte après frais, avec une courbe de tendance et un graphique en anneau des sources juste en dessous.", "Mae'r teils pennawd yn dangos yr hyn a gasglwyd yn erbyn yr hyn a archebwyd, yr hyn sy'n dal i fod yn ddyledus a'r hyn sy'n cyrraedd eich banc ar ôl ffioedd, gyda llinell duedd a thoesen ffynonellau ychydig islaw."],
  "lt_finance_s2": ["Revenue breaks your takings down by where the money actually comes from — card payments against funded and voucher places — and by which programmes earn the most.", "Przychody dzielą Twoje wpływy według tego, skąd naprawdę pochodzą pieniądze — płatności kartą wobec miejsc finansowanych i opłaconych voucherami — oraz według tego, które programy zarabiają najwięcej.", "Veniturile îți împart încasările după proveniența reală a banilor — plăți cu cardul față de locuri finanțate și cu vouchere — și după programele care câștigă cel mai mult.", "آمدنی آپ کی وصولیوں کو اس کے مطابق تقسیم کرتی ہے کہ پیسہ اصل میں کہاں سے آتا ہے — کارڈ ادائیگیاں بمقابلہ فنڈڈ اور واؤچر والی جگہیں — اور یہ کہ کون سے پروگرام سب سے زیادہ کماتے ہیں۔", "ਆਮਦਨ ਤੁਹਾਡੀ ਵਸੂਲੀ ਨੂੰ ਇਸ ਅਨੁਸਾਰ ਵੰਡਦੀ ਹੈ ਕਿ ਪੈਸਾ ਅਸਲ ਵਿੱਚ ਕਿੱਥੋਂ ਆਉਂਦਾ ਹੈ — ਕਾਰਡ ਅਦਾਇਗੀਆਂ ਬਨਾਮ ਫੰਡ ਪ੍ਰਾਪਤ ਅਤੇ ਵਾਊਚਰ ਵਾਲੀਆਂ ਥਾਵਾਂ — ਅਤੇ ਕਿਹੜੇ ਪ੍ਰੋਗਰਾਮ ਸਭ ਤੋਂ ਵੱਧ ਕਮਾਉਂਦੇ ਹਨ।", "আয় আপনার সংগ্রহকে ভাগ করে দেখায় টাকা আসলে কোথা থেকে আসছে — কার্ড পেমেন্ট বনাম অনুদানপ্রাপ্ত ও ভাউচারের আসন — এবং কোন কর্মসূচি সবচেয়ে বেশি আয় করছে।", "تُقسّم الإيرادات مقبوضاتك حسب المصدر الفعلي للمال — مدفوعات البطاقات مقابل المقاعد الممولة والمدفوعة بقسائم — وحسب البرامج الأعلى ربحًا.", "A Receita divide os seus recebimentos por onde o dinheiro realmente vem — pagamentos com cartão face a lugares financiados e com vales — e pelos programas que mais rendem.", "Ingresos desglosa lo que cobras según de dónde viene realmente el dinero (pagos con tarjeta frente a plazas financiadas y con vales) y según qué programas ganan más.", "Revenus répartit vos encaissements selon la provenance réelle de l'argent — paiements par carte contre places financées et payées par bons — et selon les programmes qui rapportent le plus.", "Mae Refeniw yn dadansoddi eich derbyniadau yn ôl o ble mae'r arian yn dod mewn gwirionedd — taliadau cerdyn yn erbyn lleoedd wedi'u hariannu a thalebau — a pha raglenni sy'n ennill fwyaf."],
  "lt_finance_s3": ["This is where you connect or manage your Stripe payout account and see your on-the-way against in-the-bank split, though the amounts stay estimates until Stripe is fully connected.", "Tutaj łączysz lub zarządzasz kontem wypłat Stripe i widzisz podział na kwoty w drodze i już w banku, choć kwoty pozostają szacunkowe, dopóki Stripe nie zostanie w pełni połączony.", "Aici conectezi sau gestionezi contul tău de plăți Stripe și vezi împărțirea între sumele în drum și cele aflate deja în bancă, deși sumele rămân estimări până când Stripe este conectat complet.", "یہاں آپ اپنا اسٹرائپ پے آؤٹ اکاؤنٹ جوڑتے یا سنبھالتے ہیں اور «راستے میں» اور «بینک میں» کی تقسیم دیکھتے ہیں، البتہ جب تک اسٹرائپ مکمل طور پر منسلک نہ ہو رقوم اندازے ہی رہتی ہیں۔", "ਇੱਥੇ ਤੁਸੀਂ ਆਪਣਾ ਸਟ੍ਰਾਈਪ ਪੇਆਊਟ ਖਾਤਾ ਜੋੜਦੇ ਜਾਂ ਸੰਭਾਲਦੇ ਹੋ ਅਤੇ «ਰਸਤੇ ਵਿੱਚ» ਅਤੇ «ਬੈਂਕ ਵਿੱਚ» ਦੀ ਵੰਡ ਵੇਖਦੇ ਹੋ, ਹਾਲਾਂਕਿ ਜਦੋਂ ਤੱਕ ਸਟ੍ਰਾਈਪ ਪੂਰੀ ਤਰ੍ਹਾਂ ਨਹੀਂ ਜੁੜਦਾ ਰਕਮਾਂ ਅੰਦਾਜ਼ੇ ਹੀ ਰਹਿੰਦੀਆਂ ਹਨ।", "এখানে আপনি আপনার স্ট্রাইপ পেআউট অ্যাকাউন্ট সংযুক্ত বা পরিচালনা করেন এবং «পথে আছে» ও «ব্যাংকে আছে»-র ভাগ দেখেন, তবে স্ট্রাইপ পুরোপুরি সংযুক্ত না হওয়া পর্যন্ত অঙ্কগুলো আনুমানিকই থাকে।", "هنا تربط حساب دفعات Stripe أو تديره وترى التقسيم بين «في الطريق» و«في البنك»، مع بقاء المبالغ تقديرية إلى أن يكتمل ربط Stripe.", "É aqui que liga ou gere a sua conta de pagamentos Stripe e vê a divisão entre a caminho e já no banco, embora os valores continuem a ser estimativas até o Stripe estar totalmente ligado.", "Aquí conectas o gestionas tu cuenta de pagos de Stripe y ves el reparto entre lo que está en camino y lo que ya está en el banco, aunque las cifras siguen siendo estimaciones hasta que Stripe esté totalmente conectado.", "C'est ici que vous connectez ou gérez votre compte de versements Stripe et voyez la répartition entre ce qui est en route et ce qui est déjà en banque, même si les montants restent des estimations tant que Stripe n'est pas entièrement connecté.", "Dyma lle rydych chi'n cysylltu neu'n rheoli eich cyfrif taliadau Stripe ac yn gweld y rhaniad rhwng ar y ffordd ac yn y banc, er bod y symiau'n amcangyfrifon nes bod Stripe wedi'i gysylltu'n llawn."],
  "lt_finance_s4": ["Here's the money still owed — unpaid booking balances and open or overdue invoices — with a name beside each amount so you know exactly who to chase.", "Tu są należności — niezapłacone salda rezerwacji oraz otwarte lub przeterminowane faktury — z nazwiskiem obok każdej kwoty, żebyś wiedział dokładnie, kogo monitować.", "Aici sunt banii încă datorați — solduri de rezervări neplătite și facturi deschise sau restante — cu un nume lângă fiecare sumă, ca să știi exact pe cine să urmărești.", "یہ وہ رقم ہے جو ابھی واجب الادا ہے — بکنگ کے غیر ادا شدہ بقایا اور کھلے یا مدت گزر جانے والے انوائس — ہر رقم کے ساتھ نام لکھا ہے تاکہ آپ کو ٹھیک معلوم ہو کہ کس سے تقاضا کرنا ہے۔", "ਇਹ ਉਹ ਪੈਸਾ ਹੈ ਜੋ ਅਜੇ ਬਕਾਇਆ ਹੈ — ਬੁਕਿੰਗ ਦੇ ਨਾ-ਅਦਾ ਕੀਤੇ ਬਕਾਏ ਅਤੇ ਖੁੱਲ੍ਹੇ ਜਾਂ ਮਿਆਦ ਲੰਘ ਚੁੱਕੇ ਇਨਵੌਇਸ — ਹਰ ਰਕਮ ਦੇ ਕੋਲ ਨਾਂ ਲਿਖਿਆ ਹੈ ਤਾਂ ਜੋ ਤੁਹਾਨੂੰ ਠੀਕ ਪਤਾ ਹੋਵੇ ਕਿ ਕਿਸ ਤੋਂ ਮੰਗਣਾ ਹੈ।", "এটি এখনও বকেয়া অর্থ — অপরিশোধিত বুকিং ব্যালেন্স এবং খোলা বা মেয়াদোত্তীর্ণ ইনভয়েস — প্রতিটি অঙ্কের পাশে একটি নাম, যাতে ঠিক জানেন কার কাছে তাগাদা দিতে হবে।", "هنا المبالغ التي لا تزال مستحقة — أرصدة الحجوزات غير المدفوعة والفواتير المفتوحة أو المتأخرة — مع اسم بجانب كل مبلغ لتعرف بالضبط من تطالب.", "Aqui está o dinheiro ainda devido — saldos de reservas por pagar e faturas em aberto ou em atraso — com um nome ao lado de cada valor para saber exatamente a quem cobrar.", "Aquí está el dinero que aún se debe: saldos de reservas sin pagar y facturas abiertas o vencidas, con un nombre junto a cada importe para que sepas exactamente a quién reclamar.", "Voici l'argent encore dû — soldes de réservations impayés et factures ouvertes ou en retard — avec un nom à côté de chaque montant pour que vous sachiez exactement qui relancer.", "Dyma'r arian sy'n dal i fod yn ddyledus — balansau archebu heb eu talu a chyfrifon agored neu hwyr — gydag enw wrth ymyl pob swm fel eich bod yn gwybod yn union pwy i fynd ar ei ôl."],
  "lt_finance_s5": ["Beyond the cash, this tab shows loyalty, value per family and which age bands fill up — the demand signal sitting behind your revenue.", "Poza gotówką ta karta pokazuje lojalność, wartość na rodzinę i to, które przedziały wiekowe się zapełniają — sygnał popytu stojący za Twoimi przychodami.", "Dincolo de bani, această filă arată loialitatea, valoarea per familie și ce grupe de vârstă se umplu — semnalul cererii din spatele veniturilor tale.", "نقد رقم سے آگے یہ ٹیب وفاداری، فی خاندان قدر، اور کون سے عمر کے گروپ بھرتے ہیں دکھاتا ہے — آپ کی آمدنی کے پیچھے چھپی طلب کا اشارہ۔", "ਨਕਦੀ ਤੋਂ ਅੱਗੇ ਇਹ ਟੈਬ ਵਫ਼ਾਦਾਰੀ, ਪ੍ਰਤੀ ਪਰਿਵਾਰ ਮੁੱਲ ਅਤੇ ਕਿਹੜੇ ਉਮਰ ਵਰਗ ਭਰਦੇ ਹਨ ਦਿਖਾਉਂਦਾ ਹੈ — ਤੁਹਾਡੀ ਆਮਦਨ ਦੇ ਪਿੱਛੇ ਬੈਠਾ ਮੰਗ ਦਾ ਸੰਕੇਤ।", "নগদ অর্থের বাইরে, এই ট্যাব দেখায় আনুগত্য, প্রতি পরিবারের মূল্য এবং কোন বয়সের সীমা ভরে উঠছে — আপনার আয়ের পেছনের চাহিদার সংকেত।", "إلى جانب النقد، يعرض هذا التبويب الولاء وقيمة كل عائلة والفئات العمرية التي تمتلئ — إشارة الطلب الكامنة خلف إيراداتك.", "Além do dinheiro, este separador mostra a fidelização, o valor por família e que faixas etárias enchem — o sinal de procura por trás das suas receitas.", "Más allá del dinero, esta pestaña muestra la fidelidad, el valor por familia y qué franjas de edad se llenan: la señal de demanda que hay detrás de tus ingresos.", "Au-delà de l'argent, cet onglet montre la fidélité, la valeur par famille et les tranches d'âge qui se remplissent — le signal de demande derrière vos revenus.", "Y tu hwnt i'r arian parod, mae'r tab hwn yn dangos teyrngarwch, gwerth fesul teulu a pha fandiau oedran sy'n llenwi — y signal galw sy'n eistedd y tu ôl i'ch refeniw."],
};
